export type EnergyLevel = 'LOW' | 'MEDIUM' | 'HIGH';

export interface DailyLog {
  date: string;
  action: string;
  timeSpent: number;
  mentalState: string;
  energy: EnergyLevel;
}

export interface UserIdentity {
  role: string;
  anchors: string[];
  lockedAt: string; // ISO string
}

export type AppView = 'SETUP' | 'CHECKIN' | 'FEEDBACK' | 'HISTORY';

export type AlignmentStatus = 'ALIGNED' | 'UNSTABLE' | 'DRIFTING';

export interface FeedbackData {
  status: AlignmentStatus;
  message: string;
}

import { DailyLog, UserIdentity, FeedbackData } from './types';

const KEYS = {
  IDENTITY: 'noah_identity',
  LOGS: 'noah_logs',
  LAST_FEEDBACK: 'noah_feedback'
};

export const store = {
  getIdentity: (): UserIdentity | null => {
    const data = localStorage.getItem(KEYS.IDENTITY);
    return data ? JSON.parse(data) : null;
  },
  saveIdentity: (identity: UserIdentity) => {
    localStorage.setItem(KEYS.IDENTITY, JSON.stringify(identity));
  },
  getLogs: (): DailyLog[] => {
    const data = localStorage.getItem(KEYS.LOGS);
    return data ? JSON.parse(data) : [];
  },
  addLog: (log: DailyLog) => {
    const logs = store.getLogs();
    // Unique per date
    const filtered = logs.filter(l => l.date !== log.date);
    localStorage.setItem(KEYS.LOGS, JSON.stringify([...filtered, log]));
  },
  getLastFeedback: (): FeedbackData | null => {
    const data = localStorage.getItem(KEYS.LAST_FEEDBACK);
    return data ? JSON.parse(data) : null;
  },
  saveFeedback: (feedback: FeedbackData) => {
    localStorage.setItem(KEYS.LAST_FEEDBACK, JSON.stringify(feedback));
  }
};

import { GoogleGenAI, Type } from "@google/genai";
import { UserIdentity, DailyLog, FeedbackData } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export async function generateAlignmentFeedback(
  identity: UserIdentity,
  logs: DailyLog[]
): Promise<FeedbackData> {
  if (logs.length === 0) {
    return {
      status: 'UNSTABLE',
      message: 'No patterns yet. Reality starts today.'
    };
  }

  // Use the last 7 logs for analysis
  const recentLogs = logs.slice(-7);

  const prompt = `
    Analyze the alignment between a user's chosen identity and their recent behavior.

    IDENTITY: ${identity.role}
    BEHAVIORAL ANCHORS: ${identity.anchors.join(', ')}

    RECENT ACTIVITY LOGS (Last 7 days):
    ${recentLogs.map(l => `- ${l.date}: Did "${l.action}" for ${l.timeSpent} mins. Mental state: ${l.mentalState}. Energy: ${l.energy}.`).join('\n')}

    RULES:
    1. Be cold, honest, and factual.
    2. Do not use motivational language or encouragement.
    3. Output must be valid JSON matching the schema.
    4. Provide exactly one 2-3 line feedback message.
    5. Determine status: ALIGNED (consistency), UNSTABLE (sporadic), or DRIFTING (significant deviation).
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: 'application/json',
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            status: {
              type: Type.STRING,
              enum: ['ALIGNED', 'UNSTABLE', 'DRIFTING']
            },
            message: {
              type: Type.STRING
            }
          },
          required: ['status', 'message']
        }
      }
    });

    const result = JSON.parse(response.text || '{}');
    return {
      status: result.status || 'UNSTABLE',
      message: result.message || 'Patterns require more clarity.'
    };
  } catch (error) {
    console.error('Gemini error:', error);
    return {
      status: 'UNSTABLE',
      message: 'Connection to logic systems interrupted.'
    };
  }
}

import React, { useState, useEffect } from 'react';
import { AppView, UserIdentity, DailyLog, FeedbackData } from './types';
import { store } from './store';
import IdentitySetup from './components/IdentitySetup';
import CheckIn from './components/CheckIn';
import Feedback from './components/Feedback';
import History from './components/History';

const App: React.FC = () => {
  const [view, setView] = useState<AppView>('CHECKIN');
  const [identity, setIdentity] = useState<UserIdentity | null>(null);
  const [logs, setLogs] = useState<DailyLog[]>([]);
  const [lastFeedback, setLastFeedback] = useState<FeedbackData | null>(null);

  useEffect(() => {
    const storedIdentity = store.getIdentity();
    const storedLogs = store.getLogs();
    const storedFeedback = store.getLastFeedback();

    setIdentity(storedIdentity);
    setLogs(storedLogs);
    setLastFeedback(storedFeedback);

    if (!storedIdentity) {
      setView('SETUP');
    }
  }, []);

  const handleIdentityLocked = (newIdentity: UserIdentity) => {
    setIdentity(newIdentity);
    store.saveIdentity(newIdentity);
    setView('CHECKIN');
  };

  const handleLogSubmitted = (newLog: DailyLog) => {
    store.addLog(newLog);
    setLogs(prev => [...prev.filter(l => l.date !== newLog.date), newLog]);
    setView('FEEDBACK');
  };

  if (view === 'SETUP' || !identity) {
    return <IdentitySetup onLock={handleIdentityLocked} />;
  }

  return (
    <div className="min-h-screen bg-bgMain flex flex-col items-center max-w-md mx-auto relative px-6 pt-12 pb-32">
      <main className="w-full flex-grow flex flex-col">
        {view === 'CHECKIN' && (
          <CheckIn 
            lastLog={logs[logs.length - 1]} 
            onComplete={handleLogSubmitted} 
          />
        )}
        {view === 'FEEDBACK' && (
          <Feedback identity={identity} logs={logs} />
        )}
        {view === 'HISTORY' && (
          <History logs={logs} />
        )}
      </main>

      <nav className="fixed bottom-0 left-0 right-0 bg-bgSurface border-t border-white/5 h-20 flex items-center justify-around px-4">
        <button 
          onClick={() => setView('CHECKIN')}
          className={`text-[10px] tracking-widest uppercase font-mono ${view === 'CHECKIN' ? 'text-accent' : 'text-textSecondary'}`}
        >
          Check-in
        </button>
        <button 
          onClick={() => setView('FEEDBACK')}
          className={`text-[10px] tracking-widest uppercase font-mono ${view === 'FEEDBACK' ? 'text-accent' : 'text-textSecondary'}`}
        >
          Feedback
        </button>
        <button 
          onClick={() => setView('HISTORY')}
          className={`text-[10px] tracking-widest uppercase font-mono ${view === 'HISTORY' ? 'text-accent' : 'text-textSecondary'}`}
        >
          History
        </button>
      </nav>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { UserIdentity } from '../types';

interface Props {
  onLock: (id: UserIdentity) => void;
}

const IdentitySetup: React.FC<Props> = ({ onLock }) => {
  const [role, setRole] = useState('');
  const [anchors, setAnchors] = useState(['', '', '']);
  const [showConfirm, setShowConfirm] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    inputRef.current?.focus();
  }, []);

  const handleAnchorChange = (index: number, val: string) => {
    const next = [...anchors];
    next[index] = val;
    setAnchors(next);
  };

  const handleLock = () => {
    if (!role.trim()) return;
    const finalAnchors = anchors.filter(a => a.trim() !== '');
    onLock({
      role: role.trim(),
      anchors: finalAnchors,
      lockedAt: new Date().toISOString()
    });
  };

  return (
    <div className="min-h-screen bg-bgMain flex flex-col items-center justify-center p-6 text-center">
      <div className="w-full max-w-sm space-y-12">
        <div className="space-y-4">
          <h1 className="text-xs font-mono tracking-[0.3em] uppercase text-textSecondary">
            Who do you want to become?
          </h1>
          <input
            ref={inputRef}
            type="text"
            value={role}
            onChange={(e) => setRole(e.target.value)}
            placeholder="Founder. Artist. Student. Choose one."
            className="w-full bg-transparent border-b border-white/10 py-2 text-xl text-center focus:outline-none focus:border-white/40 transition-colors"
          />
        </div>

        <div className="space-y-6">
          <h2 className="text-xs font-mono tracking-[0.3em] uppercase text-textSecondary">
            Behavioral Anchors (Max 3)
          </h2>
          <div className="space-y-4">
            {anchors.map((a, i) => (
              <input
                key={i}
                type="text"
                value={a}
                onChange={(e) => handleAnchorChange(i, e.target.value)}
                placeholder={i === 0 ? "Daily building" : i === 1 ? "Active learning" : "Energy management"}
                className="w-full bg-transparent border-b border-white/5 py-1 text-sm text-center focus:outline-none focus:border-white/20"
              />
            ))}
          </div>
        </div>

        <div className="space-y-8">
          <p className="text-[10px] uppercase tracking-widest text-textSecondary opacity-50">
            30-day commitment
          </p>
          <button
            onClick={() => setShowConfirm(true)}
            className="w-full bg-accent py-4 text-xs font-mono tracking-[0.4em] uppercase hover:opacity-90 transition-opacity"
          >
            Lock Identity
          </button>
        </div>
      </div>

      {showConfirm && (
        <div className="fixed inset-0 bg-bgMain/95 flex items-center justify-center p-6 z-50">
          <div className="max-w-xs space-y-8 text-center">
            <p className="text-sm font-light leading-relaxed">
              This identity cannot be changed for 30 days.
            </p>
            <div className="flex flex-col space-y-4">
              <button
                onClick={handleLock}
                className="text-accent text-[10px] tracking-[0.4em] uppercase"
              >
                Confirm
              </button>
              <button
                onClick={() => setShowConfirm(false)}
                className="text-textSecondary text-[10px] tracking-[0.4em] uppercase"
              >
                Cancel
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default IdentitySetup;

import React, { useState } from 'react';
import { DailyLog, EnergyLevel } from '../types';

interface Props {
  lastLog?: DailyLog;
  onComplete: (log: DailyLog) => void;
}

const CheckIn: React.FC<Props> = ({ lastLog, onComplete }) => {
  const [action, setAction] = useState('');
  const [time, setTime] = useState(60);
  const [state, setState] = useState('');
  const [energy, setEnergy] = useState<EnergyLevel>('MEDIUM');

  const handleSubmit = () => {
    if (!action || !state) return;
    onComplete({
      date: new Date().toLocaleDateString(),
      action,
      timeSpent: time,
      mentalState: state,
      energy
    });
  };

  const todayStr = new Date().toLocaleDateString('en-US', {
    month: 'short',
    day: 'numeric',
    year: 'numeric'
  });

  return (
    <div className="w-full space-y-12 pb-12">
      <header className="space-y-1">
        <h1 className="text-xs font-mono tracking-[0.3em] uppercase text-textSecondary">
          {todayStr}
        </h1>
        {lastLog && (
          <p className="text-[10px] text-textSecondary/40 uppercase tracking-widest">
            Last: {lastLog.action.length > 20 ? lastLog.action.slice(0, 20) + '...' : lastLog.action}
          </p>
        )}
      </header>

      {/* Section 1: Action */}
      <section className="space-y-4">
        <label className="text-[10px] font-mono tracking-widest uppercase text-textSecondary">
          What did you actually do today?
        </label>
        <textarea
          value={action}
          onChange={(e) => setAction(e.target.value.slice(0, 120))}
          maxLength={120}
          className="w-full bg-bgSurface p-4 text-sm text-textPrimary focus:outline-none min-h-[100px] resize-none border border-white/5"
          placeholder="Document specific reality..."
        />
        <div className="flex justify-end">
          <span className="text-[10px] text-textSecondary/30 font-mono">
            {action.length}/120
          </span>
        </div>
      </section>

      {/* Section 2: Time */}
      <section className="space-y-6">
        <div className="flex justify-between items-end">
          <label className="text-[10px] font-mono tracking-widest uppercase text-textSecondary">
            Time Spent
          </label>
          <span className="text-sm font-mono text-textPrimary">{time}{time >= 180 ? '+' : ''}m</span>
        </div>
        <input
          type="range"
          min="0"
          max="180"
          step="15"
          value={time}
          onChange={(e) => setTime(parseInt(e.target.value))}
          className="w-full accent-white"
        />
      </section>

      {/* Section 3: Mental State */}
      <section className="space-y-4">
        <label className="text-[10px] font-mono tracking-widest uppercase text-textSecondary">
          Mental State
        </label>
        <input
          type="text"
          value={state}
          onChange={(e) => setState(e.target.value)}
          placeholder="Focused / Avoiding / Calm..."
          className="w-full bg-bgSurface p-4 text-sm text-textPrimary focus:outline-none border border-white/5"
        />
      </section>

      {/* Section 4: Energy */}
      <section className="space-y-4">
        <label className="text-[10px] font-mono tracking-widest uppercase text-textSecondary">
          Energy Level
        </label>
        <div className="grid grid-cols-3 gap-2">
          {(['LOW', 'MEDIUM', 'HIGH'] as EnergyLevel[]).map((level) => (
            <button
              key={level}
              onClick={() => setEnergy(level)}
              className={`py-3 text-[10px] font-mono tracking-widest transition-colors ${
                energy === level 
                  ? 'bg-accent text-textPrimary' 
                  : 'bg-bgSurface text-textSecondary border border-white/5'
              }`}
            >
              {level}
            </button>
          ))}
        </div>
      </section>

      <button
        onClick={handleSubmit}
        disabled={!action || !state}
        className="w-full bg-accent py-4 text-xs font-mono tracking-[0.4em] uppercase disabled:opacity-30 disabled:cursor-not-allowed transition-all"
      >
        Submit
      </button>
    </div>
  );
};

export default CheckIn;

import React, { useState, useEffect } from 'react';
import { UserIdentity, DailyLog, FeedbackData, AlignmentStatus } from '../types';
import { generateAlignmentFeedback } from '../services/geminiService';
import { store } from '../store';

interface Props {
  identity: UserIdentity;
  logs: DailyLog[];
}

const Feedback: React.FC<Props> = ({ identity, logs }) => {
  const [data, setData] = useState<FeedbackData | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    async function fetchTruth() {
      setLoading(true);
      const result = await generateAlignmentFeedback(identity, logs);
      setData(result);
      store.saveFeedback(result);
      setLoading(false);
    }
    fetchTruth();
  }, [identity, logs]);

  if (loading) {
    return (
      <div className="flex-grow flex flex-col items-center justify-center space-y-4">
        <div className="w-8 h-[1px] bg-white/20 animate-pulse" />
        <p className="text-[10px] font-mono tracking-widest uppercase text-textSecondary opacity-40">
          Observing reality...
        </p>
      </div>
    );
  }

  if (!data) return null;

  const getStatusColor = (status: AlignmentStatus) => {
    switch (status) {
      case 'ALIGNED': return 'text-textPrimary';
      case 'UNSTABLE': return 'text-textSecondary';
      case 'DRIFTING': return 'text-accent';
      default: return 'text-textSecondary';
    }
  };

  return (
    <div className="flex-grow flex flex-col items-center justify-center text-center space-y-16 py-12">
      <h2 className={`text-6xl font-mono tracking-[0.2em] font-medium transition-colors duration-1000 ${getStatusColor(data.status)}`}>
        {data.status}
      </h2>

      <div className="max-w-xs">
        <p className="text-sm font-light leading-relaxed text-textPrimary/80">
          {data.message}
        </p>
      </div>

      <footer className="pt-12">
        <p className="text-[10px] font-mono tracking-widest uppercase text-textSecondary/30">
          Based on recent patterns
        </p>
      </footer>
    </div>
  );
};

export default Feedback;

import React from 'react';
