const History: React.FC<Props> = ({ logs }) => {
  if (logs.length === 0) {
    return (
      <div className="flex-grow flex flex-col items-center justify-center">
        <p className="text-[10px] font-mono tracking-widest uppercase text-textSecondary/50">
          No patterns yet. Reality starts today.
        </p>
      </div>
    );
  }

  // Take last 7 days
  const history = logs.slice(-7).reverse();

  // Mock alignment inference for visual purposes in history
  // In a real app, this could be stored in each log
  const getAlignmentIndicator = (log: DailyLog) => {
    if (log.timeSpent >= 90) return 'bg-white'; // Aligned
    if (log.timeSpent >= 30) return 'bg-textSecondary/40'; // Unstable
    return 'bg-accent'; // Drifting
