  const handleSubmit = () => {
    if (!action || !state) return;
    setIsSubmitting(true);

    // Dry confirmation delay
    setTimeout(() => {
      onComplete({
        date: new Date().toLocaleDateString(),
        action,
        timeSpent: time,
        mentalState: state,
        energy
      });
    }, 800);
  };

  const todayStr = new Date().toLocaleDateString('en-US', {
    month: 'short',
    day: 'numeric',
