  if (isSubmitting) {
    return (
      <div className="flex-grow flex items-center justify-center animate-in fade-in zoom-in-95 duration-500">
        <span className="text-[10px] font-mono tracking-[0.5em] uppercase text-textSecondary opacity-60">Logged.</span>
