import React, { useState, useEffect } from 'react';
import { UserIdentity, DailyLog, FeedbackData, AlignmentStatus } from '../types';
import { generateAlignmentFeedback } from '../services/geminiService';
import { store } from '../store';

interface Props {
  identity: UserIdentity;
  logs: DailyLog[];
  onCycleReset?: () => void;
}

const Feedback: React.FC<Props> = ({ identity, logs, onCycleReset }) => {
  const [data, setData] = useState<FeedbackData | null>(null);
  const [loading, setLoading] = useState(true);
  const [daysPassed, setDaysPassed] = useState(0);

  useEffect(() => {
    const start = new Date(identity.lockedAt).getTime();
    const now = new Date().getTime();
    const diff = Math.floor((now - start) / (1000 * 60 * 60 * 24));
    setDaysPassed(diff);

    async function fetchTruth() {
      setLoading(true);
      const result = await generateAlignmentFeedback(identity, logs);
      setData(result);
      store.saveFeedback(result);
      setLoading(false);
    }
    fetchTruth();
  }, [identity, logs]);

  const handleReset = () => {
    if (confirm("Reset current patterns?")) {
      onCycleReset?.();
    }
  };

  if (loading) {
    return (
      <div className="flex-grow flex flex-col items-center justify-center space-y-4">
        <div className="w-8 h-[1px] bg-white/20 animate-pulse" />
        <p className="text-[10px] font-mono tracking-widest uppercase text-textSecondary opacity-40">
          Observing reality...
        </p>
      </div>
    );
  }

  if (!data) return null;

  const getStatusColor = (status: AlignmentStatus) => {
    switch (status) {
      case 'ALIGNED': return 'text-textPrimary';
      case 'UNSTABLE': return 'text-textSecondary';
      case 'DRIFTING': return 'text-accent';
      default: return 'text-textSecondary';
    }
  };

  const isCycleComplete = daysPassed >= 30;

  return (
    <div className="flex-grow flex flex-col items-center justify-center text-center space-y-12 py-12 reveal">
      <div className="space-y-2">
        <h2 className={`text-6xl font-mono tracking-[0.2em] font-medium transition-colors duration-1000 ${getStatusColor(data.status)} ${data.status === 'DRIFTING' ? 'pulse-drifting' : ''}`}>
          {data.status}
        </h2>
        <p className="text-[10px] font-mono tracking-[0.4em] uppercase text-textSecondary opacity-40">
          Day {Math.min(daysPassed + 1, 30)} of 30
        </p>
      </div>

      <div className="max-w-xs space-y-8">
        <p className="text-sm font-light leading-relaxed text-textPrimary/80">
          {data.message}
        </p>

        {isCycleComplete && (
          <div className="pt-8 space-y-6">
            <p className="text-xs text-accent tracking-widest uppercase">Cycle Complete</p>
            <div className="flex flex-col space-y-4">
              <button onClick={onCycleReset} className="bg-accent py-3 text-[10px] tracking-widest uppercase">Recommit</button>
              <button onClick={handleReset} className="text-[10px] tracking-widest uppercase text-textSecondary">Reset Identity</button>
            </div>
          </div>
        )}
      </div>

      <footer className="pt-8">
        <p className="text-[10px] font-mono tracking-widest uppercase text-textSecondary/20">
          Reality is persistent.
        </p>
      </footer>
    </div>
  );
};

