import React, { useState, useEffect, useMemo } from 'react';
import { AppView, UserIdentity, DailyLog, FeedbackData } from './types';
import { store } from './store';
import IdentitySetup from './components/IdentitySetup';
import CheckIn from './components/CheckIn';
import Feedback from './components/Feedback';
import History from './components/History';
import Landing from './components/Landing';
import Auth from './components/Auth';
import Renewal from './components/Renewal';

const App: React.FC = () => {
  const [view, setView] = useState<AppView>('LANDING');
  const [identity, setIdentity] = useState<UserIdentity | null>(null);
  const [logs, setLogs] = useState<DailyLog[]>([]);
  const [userEmail, setUserEmail] = useState<string | null>(null);

  const isExpired = useMemo(() => {
    if (!identity) return false;
    const start = new Date(identity.lockedAt).getTime();
    const now = new Date().getTime();
    const diffDays = (now - start) / (1000 * 60 * 60 * 24);
    return diffDays >= 30;
  }, [identity]);

  useEffect(() => {
    const storedIdentity = store.getIdentity();
    const storedLogs = store.getLogs();
    const storedEmail = store.getEmail();
    const seenLanding = store.hasSeenLanding();

    setIdentity(storedIdentity);
    setLogs(storedLogs);
    setUserEmail(storedEmail);

    if (seenLanding) {
      if (!storedIdentity) {
        setView('SETUP');
      } else {
        // Automatic redirect to renewal if expired
        const start = new Date(storedIdentity.lockedAt).getTime();
        const now = new Date().getTime();
        const diffDays = (now - start) / (1000 * 60 * 60 * 24);

        if (diffDays >= 30) {
          setView('RENEWAL');
        } else {
          setView('CHECKIN');
        }
      }
    } else {
      setView('LANDING');
    }
  }, []);

  // Watch for expiration and redirect if not on Landing/Auth
  useEffect(() => {
    if (isExpired && view !== 'RENEWAL' && view !== 'LANDING' && view !== 'AUTH') {
      setView('RENEWAL');
    }
  }, [isExpired, view]);

  const handleLandingProceed = () => setView('AUTH');

  const handleLandingEnter = () => {
    store.setSeenLanding();
    if (!identity) setView('SETUP');
    else if (isExpired) setView('RENEWAL');
    else setView('CHECKIN');
  };

  const handleAuthSuccess = (email: string) => {
    store.saveEmail(email);
    setUserEmail(email);
    store.setSeenLanding();
    if (!identity) setView('SETUP');
    else if (isExpired) setView('RENEWAL');
    else setView('CHECKIN');
  };

  const handleIdentityLocked = (newIdentity: UserIdentity) => {
    setIdentity(newIdentity);
    store.saveIdentity(newIdentity);
    setView('CHECKIN');
  };

  const handleLogSubmitted = (newLog: DailyLog) => {
    store.addLog(newLog);
    setLogs(prev => [...prev.filter(l => l.date !== newLog.date), newLog]);
    setView('FEEDBACK');
  };

  const handleCycleReset = () => {
    localStorage.removeItem('noah_identity');
    localStorage.removeItem('noah_logs');
    setIdentity(null);
    setLogs([]);
    setView('SETUP');
  };

  const handleRecommit = () => {
    if (identity) {
      const newIdentity = { ...identity, lockedAt: new Date().toISOString() };
      setIdentity(newIdentity);
      store.saveIdentity(newIdentity);
      setView('CHECKIN');
    }
  };

  // Rendering logic
  if (view === 'LANDING') return <Landing onProceed={handleLandingProceed} onEnter={handleLandingEnter} />;
  if (view === 'AUTH') return <Auth onSuccess={handleAuthSuccess} onSkip={handleLandingEnter} />;
  if (view === 'SETUP' || !identity) return <IdentitySetup onLock={handleIdentityLocked} />;

  return (
    <div className="min-h-screen bg-bgMain flex flex-col items-center max-w-md mx-auto relative px-6 pt-12 pb-32 overflow-hidden">
      <main className="w-full flex-grow flex flex-col transition-all duration-300">
        {view === 'CHECKIN' && <CheckIn lastLog={logs[logs.length - 1]} onComplete={handleLogSubmitted} />}
        {view === 'FEEDBACK' && <Feedback identity={identity} logs={logs} onCycleReset={handleCycleReset} />}
        {view === 'HISTORY' && <History logs={logs} />}
        {view === 'RENEWAL' && <Renewal identity={identity} onRecommit={handleRecommit} onReset={handleCycleReset} />}
      </main>

      <nav className="fixed bottom-0 left-0 right-0 bg-bgSurface border-t border-white/5 h-20 flex items-center justify-around px-4 z-10">
        <button 
          onClick={() => !isExpired && setView('CHECKIN')}
          disabled={isExpired}
          className={`text-[10px] tracking-widest uppercase font-mono transition-colors duration-500 active:scale-95 disabled:opacity-20 ${view === 'CHECKIN' ? 'text-textPrimary' : 'text-textSecondary/40'}`}
        >
          Check-in
        </button>
        <button 
          onClick={() => setView('FEEDBACK')}
          className={`text-[10px] tracking-widest uppercase font-mono transition-colors duration-500 active:scale-95 ${view === 'FEEDBACK' ? 'text-textPrimary' : 'text-textSecondary/40'}`}
        >
          {isExpired ? 'Renewal' : 'Feedback'}
        </button>
        <button 
          onClick={() => setView('HISTORY')}
          className={`text-[10px] tracking-widest uppercase font-mono transition-colors duration-500 active:scale-95 ${view === 'HISTORY' ? 'text-textPrimary' : 'text-textSecondary/40'}`}
        >
          History
        </button>
      </nav>
    </div>
  );
};

export default App;

