import React, { useState } from 'react';
import { DailyLog, EnergyLevel, UserIdentity } from '../types';

interface Props {
  identity: UserIdentity;
  lastLog?: DailyLog;
  onComplete: (log: DailyLog) => void;
}

const CheckIn: React.FC<Props> = ({ identity, lastLog, onComplete }) => {
  const [action, setAction] = useState('');
  const [time, setTime] = useState(60);
  const [state, setState] = useState('');
  const [energy, setEnergy] = useState<EnergyLevel>('MEDIUM');
  const [anchorStatus, setAnchorStatus] = useState<boolean[]>(new Array(identity.anchors.length).fill(false));
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [showSummary, setShowSummary] = useState(false);

  const handleSubmit = () => {
    if (!action || !state) return;
    setIsSubmitting(true);

    setTimeout(() => {
      onComplete({
        date: new Date().toLocaleDateString(),
        action,
        timeSpent: time,
        mentalState: state,
        energy,
        anchorsCompleted: anchorStatus
      });
    }, 800);
  };

  const toggleAnchor = (index: number) => {
    const next = [...anchorStatus];
    next[index] = !next[index];
    setAnchorStatus(next);
  };

  const todayStr = new Date().toLocaleDateString('en-US', {
    month: 'short',
    day: 'numeric',
    year: 'numeric'
  });

  if (isSubmitting) {
    return (
      <div className="flex-grow flex items-center justify-center view-transition">
        <span className="text-[10px] font-mono tracking-[0.5em] uppercase text-textSecondary opacity-60">Logged.</span>
      </div>
    );
  }

  return (
    <div className="w-full space-y-12 pb-12 view-transition">
      <header className="flex justify-between items-start">
        <div className="space-y-1">
          <h1 className="text-xs font-mono tracking-[0.3em] uppercase text-textSecondary">
            {todayStr}
          </h1>
          {lastLog && (
            <p className="text-[10px] text-textSecondary/40 uppercase tracking-widest">
              Last: {lastLog.action.length > 20 ? lastLog.action.slice(0, 20) + '...' : lastLog.action}
            </p>
          )}
        </div>
        <button 
          onClick={() => setShowSummary(!showSummary)}
          className="text-[10px] font-mono uppercase tracking-widest text-textSecondary/40 hover:text-textSecondary transition-colors"
        >
          {showSummary ? 'Close' : 'Anchors'}
        </button>
      </header>

      {showSummary && (
        <section className="bg-bgSurface/40 p-6 space-y-4 border border-white/5 animate-in slide-in-from-top-2 duration-300">
          <p className="text-[10px] font-mono uppercase tracking-widest text-textSecondary/60">Anchors being tracked</p>
          <div className="space-y-2">
            {identity.anchors.map((anchor, i) => (
              <p key={i} className="text-sm font-light text-textPrimary/80">• {anchor}</p>
            ))}
          </div>
        </section>
      )}

      {/* Section 1: Action */}
      <section className="space-y-4">
        <label className="text-[10px] font-mono tracking-widest uppercase text-textSecondary">
          What did you actually do today?
        </label>
        <textarea
          value={action}
          onChange={(e) => setAction(e.target.value.slice(0, 120))}
          maxLength={120}
          className="w-full bg-bgSurface p-4 text-sm text-textPrimary focus:outline-none min-h-[100px] resize-none border border-white/5 focus:border-white/10 transition-colors"
          placeholder="Document specific reality..."
        />
        <div className="flex justify-end">
          <span className="text-[10px] text-textSecondary/30 font-mono">
            {action.length}/120
          </span>
        </div>
      </section>

      {/* Section: Anchor Evaluation */}
      <section className="space-y-4">
        <label className="text-[10px] font-mono tracking-widest uppercase text-textSecondary">
          Anchor Alignment
        </label>
        <div className="space-y-2">
          {identity.anchors.map((anchor, i) => (
            <button
              key={i}
              onClick={() => toggleAnchor(i)}
              className={`w-full text-left p-4 flex items-center justify-between border active-feedback ${
                anchorStatus[i] 
                  ? 'border-accent bg-accent/5 text-textPrimary' 
                  : 'border-white/5 bg-bgSurface text-textSecondary/60'
              } transition-all duration-300`}
            >
              <span className="text-xs tracking-wide">{anchor}</span>
              <div className={`w-3 h-3 border ${anchorStatus[i] ? 'bg-accent border-accent' : 'border-white/20'}`} />
            </button>
          ))}
        </div>
      </section>

      {/* Section 2: Time */}
      <section className="space-y-6">
        <div className="flex justify-between items-end">
          <label className="text-[10px] font-mono tracking-widest uppercase text-textSecondary">
            Time Spent
          </label>
          <span className="text-sm font-mono text-textPrimary">{time}{time >= 180 ? '+' : ''}m</span>
        </div>
        <input
          type="range"
          min="0"
          max="180"
          step="15"
          value={time}
          onChange={(e) => setTime(parseInt(e.target.value))}
          className="w-full accent-white active-feedback"
        />
      </section>

      {/* Section 3: Mental State */}
      <section className="space-y-4">
        <label className="text-[10px] font-mono tracking-widest uppercase text-textSecondary">
          Mental State
        </label>
        <input
          type="text"
          value={state}
          onChange={(e) => setState(e.target.value)}
          placeholder="Focused / Avoiding / Calm..."
          className="w-full bg-bgSurface p-4 text-sm text-textPrimary focus:outline-none border border-white/5 focus:border-white/10 transition-colors"
        />
      </section>

      {/* Section 4: Energy */}
      <section className="space-y-4">
        <label className="text-[10px] font-mono tracking-widest uppercase text-textSecondary">
          Energy Level
        </label>
        <div className="grid grid-cols-3 gap-2">
          {(['LOW', 'MEDIUM', 'HIGH'] as EnergyLevel[]).map((level) => (
            <button
              key={level}
              onClick={() => setEnergy(level)}
              className={`py-3 text-[10px] font-mono tracking-widest transition-colors active-feedback ${
                energy === level 
                  ? 'bg-accent text-textPrimary' 
                  : 'bg-bgSurface text-textSecondary border border-white/5'
              }`}
            >
              {level}
            </button>
          ))}
        </div>
      </section>

      <button
        onClick={handleSubmit}
        disabled={!action || !state}
        className="w-full bg-accent py-4 text-xs font-mono tracking-[0.4em] uppercase disabled:opacity-30 disabled:cursor-not-allowed transition-all active-feedback"
      >
        Submit
      </button>
    </div>
  );
};

