        <button 
          onClick={() => setView('FEEDBACK')}
          className={`text-[9px] tracking-widest uppercase font-mono transition-colors duration-500 active-feedback ${view === 'FEEDBACK' ? 'text-textPrimary' : 'text-textSecondary/30'}`}
        >
          {isExpired ? 'Renew' : 'Truth'}
        </button>
        <button 
          onClick={() => setView('HISTORY')}
          className={`text-[9px] tracking-widest uppercase font-mono transition-colors duration-500 active-feedback ${view === 'HISTORY' ? 'text-textPrimary' : 'text-textSecondary/30'}`}
