import React, { useState, useEffect, useRef } from 'react';
import { UserIdentity } from '../types';
import { motion, AnimatePresence } from 'framer-motion';

interface Props {
  onLock: (id: UserIdentity) => void;
}

const IdentitySetup: React.FC<Props> = ({ onLock }) => {
  const [slideIndex, setSlideIndex] = useState(0);
  const [role, setRole] = useState('');
  const [anchors, setAnchors] = useState(['', '', '']);
  const [isLocking, setIsLocking] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);

  const slides = [
    "This is not a productivity app.",
    "This is a mirror.",
    "You will define who you want to become.",
    "Then you will observe yourself.",
    "Nothing more. Nothing less."
  ];

  const handleNextSlide = () => {
    if (slideIndex < slides.length - 1) setSlideIndex(slideIndex + 1);
    else setSlideIndex(99); // Go to form
  };

  const handleLock = () => {
    if (!role.trim()) return;
    setIsLocking(true);
    const finalAnchors = anchors.filter(a => a.trim() !== '');

    // Simulate irreversible "locking" process
    setTimeout(() => {
      onLock({
        role: role.trim(),
        anchors: finalAnchors,
        lockedAt: new Date().toISOString(),
        expiresAt: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString()
      });
    }, 1500);
  };

  if (slideIndex < slides.length) {
    return (
      <div 
        onClick={handleNextSlide}
        className="min-h-screen bg-bgMain flex flex-col items-center justify-center p-12 text-center cursor-pointer select-none"
      >
        <AnimatePresence mode="wait">
          <motion.p 
            key={slideIndex}
            initial={{ opacity: 0, scale: 0.98 }}
            animate={{ opacity: 1, scale: 1 }}
            exit={{ opacity: 0, scale: 1.02 }}
            transition={{ duration: 0.8, ease: "easeInOut" }}
            className="text-xl md:text-2xl font-light tracking-wide text-textPrimary max-w-md"
          >
            {slides[slideIndex]}
          </motion.p>
        </AnimatePresence>

        <div className="absolute bottom-16 flex space-x-2">
          {slides.map((_, i) => (
            <div key={i} className={`h-[1px] w-4 transition-all duration-700 ${i === slideIndex ? 'bg-textPrimary' : 'bg-white/10'}`} />
          ))}
        </div>

        <button 
          onClick={(e) => { e.stopPropagation(); setSlideIndex(99); }}
          className="absolute top-12 right-12 text-[10px] uppercase tracking-widest text-textSecondary/40 hover:text-textSecondary"
        >
          Skip
        </button>
      </div>
    );
  }

  return (
    <motion.div 
      initial={{ opacity: 0 }} 
      animate={{ opacity: 1 }}
      className="min-h-screen bg-bgMain flex flex-col items-center justify-center p-6 text-center overflow-y-auto no-scrollbar"
    >
      <div className="w-full max-w-sm space-y-16 py-12">
        <div className="space-y-6">
          <h1 className="noah-title">Who do you want to become?</h1>
          <input
            ref={inputRef}
            type="text"
            value={role}
            onChange={(e) => setRole(e.target.value)}
            placeholder="Founder. Artist. Student."
            className="w-full bg-transparent border-b border-white/10 py-3 text-2xl text-center focus:outline-none focus:border-accent transition-colors placeholder:text-textSecondary/20"
            autoFocus
          />
        </div>

        <div className="space-y-8">
          <h2 className="noah-title">Behavioral Anchors (Max 3)</h2>
          <div className="space-y-4">
            {anchors.map((a, i) => (
              <input
                key={i}
                type="text"
                value={a}
                onChange={(e) => {
                  const n = [...anchors];
                  n[i] = e.target.value;
                  setAnchors(n);
                }}
                placeholder={`Anchor ${i + 1}`}
                className="w-full bg-muted/30 border border-border/50 rounded-sm p-4 text-sm focus:outline-none focus:border-accent transition-all text-center"
              />
            ))}
          </div>
        </div>

        <div className="space-y-8">
          <p className="text-[10px] uppercase tracking-widest text-textSecondary opacity-30">
            Identity locks for 30 days
          </p>
          <button
            onClick={handleLock}
            disabled={!role.trim() || isLocking}
            className="w-full bg-accent py-4 text-[11px] font-mono tracking-[0.4em] uppercase hover:opacity-90 transition-all active-feedback disabled:opacity-10"
          >
            {isLocking ? 'Locking...' : 'Lock Identity'}
          </button>
        </div>
      </div>
    </motion.div>
  );
};

export default IdentitySetup;

import React, { useState, useEffect } from 'react';
import { UserIdentity, DailyLog, FeedbackData, AlignmentStatus } from '../types';
import { generateAlignmentFeedback } from '../services/geminiService';
import { store } from '../store';
import { motion } from 'framer-motion';

interface Props {
  identity: UserIdentity;
  logs: DailyLog[];
  onCycleReset?: () => void;
}

const Feedback: React.FC<Props> = ({ identity, logs, onCycleReset }) => {
  const [data, setData] = useState<FeedbackData | null>(null);
  const [loading, setLoading] = useState(true);
  const [daysPassed, setDaysPassed] = useState(0);

  useEffect(() => {
    const start = new Date(identity.lockedAt).getTime();
    const now = new Date().getTime();
    const diff = Math.floor((now - start) / (1000 * 60 * 60 * 24));
    setDaysPassed(diff);

    async function fetchTruth() {
      setLoading(true);
      const result = await generateAlignmentFeedback(identity, logs);
      setData(result);
      store.saveFeedback(result);
      setLoading(false);
    }
    fetchTruth();
  }, [identity, logs]);

  if (loading) {
    return (
      <div className="flex-grow flex flex-col items-center justify-center space-y-6">
        <motion.div 
          animate={{ opacity: [0.1, 0.4, 0.1] }}
          transition={{ repeat: Infinity, duration: 2 }}
          className="w-12 h-[1px] bg-textPrimary" 
        />
        <p className="text-[10px] font-mono tracking-[0.5em] uppercase text-textSecondary opacity-40">
          Observing reality...
        </p>
      </div>
    );
  }

  if (!data) return null;

  const getStatusColor = (status: AlignmentStatus) => {
    switch (status) {
      case 'ALIGNED': return 'text-textPrimary';
      case 'UNSTABLE': return 'text-textSecondary';
      case 'DRIFTING': return 'text-accent';
      default: return 'text-textSecondary';
    }
  };

  return (
    <div className="flex-grow flex flex-col items-center justify-center text-center space-y-16 py-12 view-transition">
      <div className="space-y-4">
        <h1 className="noah-title opacity-40">Current Status</h1>
        <motion.h2 
          animate={data.status === 'DRIFTING' ? { opacity: [1, 0.7, 1] } : {}}
          transition={{ repeat: Infinity, duration: 2.5 }}
          className={`text-6xl md:text-8xl font-bold tracking-[0.1em] font-mono transition-colors duration-1000 ${getStatusColor(data.status)}`}
        >
          {data.status}
        </motion.h2>
        <p className="text-[10px] font-mono tracking-[0.3em] uppercase text-textSecondary opacity-30">
          Day {Math.min(daysPassed + 1, 30)} of 30
        </p>
      </div>

      <div className="max-w-xs space-y-12">
        <div className="noah-card p-6 border-white/5 space-y-4">
          <p className="text-sm font-light leading-relaxed text-textPrimary/80 italic">
            "{data.message}"
          </p>
        </div>

        {data.observation && (
          <div className="space-y-2">
            <h4 className="noah-title text-[9px]">Observation</h4>
            <p className="text-xs text-textSecondary font-light leading-relaxed">
              {data.observation}
            </p>
          </div>
        )}
      </div>

      <footer className="pt-8 opacity-20">
        <p className="text-[9px] font-mono tracking-[0.5em] uppercase">
          Reality is persistent.
        </p>
      </footer>
    </div>
  );
};

export default Feedback;

