import React, { useState, useEffect, useMemo } from 'react';
import { AppView, UserIdentity, DailyLog } from './types';
import { store } from './store';
import IdentitySetup from './components/IdentitySetup';
import CheckIn from './components/CheckIn';
import Feedback from './components/Feedback';
import History from './components/History';
import Landing from './components/Landing';
import Auth from './components/Auth';
import Renewal from './components/Renewal';
import IdentityView from './components/IdentityView';
import { Circle, MessageSquare, Clock, User as UserIcon, RefreshCw, WifiOff } from 'lucide-react';
import { AnimatePresence, motion } from 'framer-motion';

const App: React.FC = () => {
  const [view, setView] = useState<AppView>('LANDING');
  const [identity, setIdentity] = useState<UserIdentity | null>(null);
  const [logs, setLogs] = useState<DailyLog[]>([]);
  const [userEmail, setUserEmail] = useState<string | null>(null);
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [isSyncing, setIsSyncing] = useState(false);

  const isExpired = useMemo(() => {
    if (!identity) return false;
    const expiresAt = new Date(identity.expiresAt).getTime();
    const now = new Date().getTime();
    return now >= expiresAt;
  }, [identity]);

  useEffect(() => {
    const storedIdentity = store.getIdentity();
    const storedLogs = store.getLogs();
    const storedEmail = store.getEmail();
    const seenLanding = store.hasSeenLanding();

    setIdentity(storedIdentity);
    setLogs(storedLogs);
    setUserEmail(storedEmail);

    if (seenLanding) {
      if (!storedIdentity) setView('SETUP');
      else if (new Date().getTime() >= new Date(storedIdentity.expiresAt).getTime()) setView('RENEWAL');
      else setView('CHECKIN');
    } else {
      setView('LANDING');
    }

    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  const triggerSync = async () => {
    if (!isOnline || !userEmail) return;
    setIsSyncing(true);
    // Placeholder for Supabase sync logic
    await new Promise(r => setTimeout(r, 1000));
    setIsSyncing(false);
  };

  const handleLandingProceed = () => setView('AUTH');
  const handleLandingEnter = () => {
    store.setSeenLanding();
    if (!identity) setView('SETUP');
    else if (isExpired) setView('RENEWAL');
    else setView('CHECKIN');
  };

  const handleAuthSuccess = (email: string) => {
    store.saveEmail(email);
    setUserEmail(email);
    store.setSeenLanding();
    if (!identity) setView('SETUP');
    else if (isExpired) setView('RENEWAL');
    else setView('CHECKIN');
    triggerSync();
  };

  const handleIdentityLocked = (newIdentity: UserIdentity) => {
    setIdentity(newIdentity);
    store.saveIdentity(newIdentity);
    setView('CHECKIN');
  };

  const handleLogSubmitted = (newLog: DailyLog) => {
    store.addLog(newLog);
    setLogs(prev => [...prev.filter(l => l.date !== newLog.date), newLog]);
    setView('FEEDBACK');
    triggerSync();
  };

  const handleCycleReset = () => {
    localStorage.removeItem('noah_identity');
    localStorage.removeItem('noah_logs');
    setIdentity(null);
    setLogs([]);
    setView('SETUP');
  };

  if (view === 'LANDING') return <Landing onProceed={handleLandingProceed} onEnter={handleLandingEnter} />;
  if (view === 'AUTH') return <Auth onSuccess={handleAuthSuccess} onSkip={handleLandingEnter} />;
  if (view === 'SETUP' || !identity) return <IdentitySetup onLock={handleIdentityLocked} />;

  return (
    <div className="min-h-screen bg-bgMain flex flex-col items-center max-w-md mx-auto relative px-6 pb-24 overflow-hidden">
      {/* Network & Sync Status Header */}
      <header className="w-full py-6 flex justify-between items-center z-20">
        <div className="flex items-center space-x-2">
          <span className="text-[10px] font-mono tracking-widest text-textSecondary/40 uppercase">N.O.A.H</span>
          {isSyncing && <RefreshCw size={10} className="text-accent animate-spin" />}
        </div>
        {!isOnline && (
          <div className="flex items-center space-x-1.5 opacity-40">
            <WifiOff size={12} className="text-textSecondary" />
            <span className="text-[8px] font-mono tracking-widest uppercase text-textSecondary">Local Session</span>
          </div>
        )}
      </header>

      <main className="w-full flex-grow flex flex-col relative z-10">
        <AnimatePresence mode="wait">
          <motion.div
            key={view}
            initial={{ opacity: 0, scale: 0.98 }}
            animate={{ opacity: 1, scale: 1 }}
            exit={{ opacity: 0, scale: 1.02 }}
            transition={{ duration: 0.15, ease: "easeOut" }}
            className="w-full flex-grow flex flex-col"
          >
            {view === 'CHECKIN' && <CheckIn identity={identity} logs={logs} onComplete={handleLogSubmitted} />}
            {view === 'FEEDBACK' && <Feedback identity={identity} logs={logs} onCycleReset={handleCycleReset} />}
            {view === 'HISTORY' && <History logs={logs} />}
            {view === 'RENEWAL' && <Renewal identity={identity} onRecommit={() => setView('CHECKIN')} onReset={handleCycleReset} />}
            {view === 'IDENTITY' && <IdentityView identity={identity} />}
          </motion.div>
        </AnimatePresence>
      </main>

      {/* Bottom Nav */}
      <nav className="fixed bottom-0 left-0 right-0 bg-bgSurface/95 backdrop-blur-md border-t border-white/5 h-20 flex items-center justify-around px-4 z-50 pb-[env(safe-area-inset-bottom)]">
        <NavButton active={view === 'CHECKIN'} icon={<Circle size={18} />} label="Check-in" onClick={() => setView('CHECKIN')} />
        <NavButton active={view === 'FEEDBACK'} icon={<MessageSquare size={18} />} label="Truth" onClick={() => setView('FEEDBACK')} />
        <NavButton active={view === 'HISTORY'} icon={<Clock size={18} />} label="History" onClick={() => setView('HISTORY')} />
        <NavButton active={view === 'IDENTITY'} icon={<UserIcon size={18} />} label="Id" onClick={() => setView('IDENTITY')} />
      </nav>
    </div>
  );
};

const NavButton = ({ active, icon, label, onClick }: { active: boolean, icon: React.ReactNode, label: string, onClick: () => void }) => (
  <button 
    onClick={onClick}
    className={`flex flex-col items-center space-y-1 transition-all duration-300 active-feedback ${active ? 'text-textPrimary' : 'text-textSecondary/30'}`}
  >
    <div className={`${active ? 'text-accent scale-110' : ''} transition-all`}>{icon}</div>
    <span className="text-[9px] uppercase tracking-widest font-mono font-medium">{label}</span>
  </button>
);

export default App;

import { GoogleGenAI, Type } from "@google/genai";
import { UserIdentity, DailyLog, FeedbackData } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export async function generateAlignmentFeedback(
  identity: UserIdentity,
  logs: DailyLog[]
): Promise<FeedbackData> {
  if (logs.length === 0) {
    return {
      status: 'UNSTABLE',
      message: 'No patterns yet. Reality starts today.',
      observation: 'Observation requires initial data points.'
    };
  }

  // Use the last 7 logs for analysis
  const recentLogs = logs.slice(-7);

  const prompt = `
    Analyze the alignment between a user's chosen identity and their recent behavior.

    IDENTITY: ${identity.role}
    BEHAVIORAL ANCHORS: ${identity.anchors.join(', ')}

    RECENT ACTIVITY LOGS (Last 7 days):
    ${recentLogs.map(l => `- ${l.date}: Did "${l.action}" for ${l.timeSpent} mins. Mental state: ${l.mentalState}. Energy: ${l.energy}. Anchors met: ${l.anchorsCompleted?.filter(Boolean).length}/${identity.anchors.length}`).join('\n')}

    RULES:
    1. Be cold, honest, and factual.
    2. Do not use motivational language or encouragement.
    3. Output must be valid JSON matching the schema.
    4. Provide exactly one 2-3 line feedback message.
    5. Provide one short, factual "observation" about a specific trend or pattern.
    6. Determine status: ALIGNED (consistency), UNSTABLE (sporadic), or DRIFTING (significant deviation or avoidance).
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: 'application/json',
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            status: {
              type: Type.STRING,
              enum: ['ALIGNED', 'UNSTABLE', 'DRIFTING']
            },
            message: {
              type: Type.STRING
            },
            observation: {
              type: Type.STRING
            }
          },
          required: ['status', 'message', 'observation']
        }
      }
    });

    const result = JSON.parse(response.text || '{}');
    return {
      status: result.status || 'UNSTABLE',
      message: result.message || 'Patterns require more clarity.',
      observation: result.observation || 'Insufficient data for factual trend detection.'
    };
  } catch (error) {
    console.error('Gemini error:', error);
    return {
      status: 'UNSTABLE',
      message: 'Connection to logic systems interrupted.',
      observation: 'External analysis unavailable.'
    };
  }
}

import React, { useState, useEffect, useRef } from 'react';
import { UserIdentity, DailyLog, FeedbackData, AlignmentStatus } from '../types';
import { generateAlignmentFeedback } from '../services/geminiService';
import { store } from '../store';
import { motion, AnimatePresence } from 'framer-motion';

interface Props {
  identity: UserIdentity;
  logs: DailyLog[];
  onCycleReset?: () => void;
}

const Feedback: React.FC<Props> = ({ identity, logs, onCycleReset }) => {
  const [data, setData] = useState<FeedbackData | null>(null);
  const [loading, setLoading] = useState(true);
  const [showStatusOverlay, setShowStatusOverlay] = useState(false);
  const prevStatusRef = useRef<AlignmentStatus | null>(null);

  useEffect(() => {
    // Load last known status from store to detect change
    const lastFeedback = store.getLastFeedback();
    if (lastFeedback) {
      prevStatusRef.current = lastFeedback.status;
    }

    async function fetchTruth() {
      setLoading(true);
      const result = await generateAlignmentFeedback(identity, logs);

      // Detect status change
      if (prevStatusRef.current && prevStatusRef.current !== result.status) {
        setShowStatusOverlay(true);
        setTimeout(() => setShowStatusOverlay(false), 300);
      }

      setData(result);
      store.saveFeedback(result);
      setLoading(false);
    }
    fetchTruth();
  }, [identity, logs]);

  if (loading) {
    return (
      <div className="flex-grow flex flex-col items-center justify-center space-y-6">
        <motion.div 
          animate={{ opacity: [0.1, 0.4, 0.1] }}
          transition={{ repeat: Infinity, duration: 2 }}
          className="w-12 h-[1px] bg-textPrimary" 
        />
        <p className="text-[10px] font-mono tracking-[0.5em] uppercase text-textSecondary opacity-40">
          Observing reality...
        </p>
      </div>
    );
  }

  if (!data) return null;

  const getStatusStyle = (status: AlignmentStatus) => {
    switch (status) {
      case 'ALIGNED': 
        return { color: 'text-textPrimary', animation: '' };
      case 'UNSTABLE': 
        return { color: 'text-textSecondary', animation: '' };
      case 'DRIFTING': 
        return { color: 'text-accent', animation: 'animate-pulse-drift' };
      default: 
        return { color: 'text-textSecondary', animation: '' };
    }
  };

  const style = getStatusStyle(data.status);

  return (
    <div className="flex-grow flex flex-col items-center justify-center text-center px-4 relative">
      <AnimatePresence>
        {showStatusOverlay && (
          <motion.div 
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 bg-bgMain z-[100] flex items-center justify-center pointer-events-none"
          >
            <span className="text-[11px] font-mono tracking-[0.5em] uppercase text-textPrimary">Status changed.</span>
          </motion.div>
        )}
      </AnimatePresence>

      <div className="space-y-2 mb-12">
        <span className="text-[9px] font-mono tracking-[0.4em] uppercase text-textSecondary/30">Target Identity</span>
        <p className="text-xs font-medium tracking-widest text-textSecondary/60 uppercase">{identity.role}</p>
      </div>

      <div className="space-y-4 mb-16">
        <motion.h2 
          className={`text-6xl md:text-8xl font-bold tracking-[0.1em] font-mono transition-colors duration-1000 ${style.color} ${style.animation}`}
        >
          {data.status}
        </motion.h2>
      </div>

      <div className="w-full max-w-xs space-y-12">
        <div className="noah-card p-6 border-white/5 bg-muted/20">
          <p className="text-sm font-light leading-relaxed text-textPrimary/80">
            {data.message}
          </p>
        </div>

        {data.observation && (
          <div className="space-y-3">
            <h4 className="noah-title text-[9px] opacity-40">Pattern Observation</h4>
            <p className="text-[11px] text-textSecondary font-light leading-relaxed tracking-wide px-4">
              {data.observation}
            </p>
          </div>
        )}
      </div>

      <footer className="absolute bottom-12 opacity-20">
        <p className="text-[9px] font-mono tracking-[0.5em] uppercase">
          Based on recent patterns
        </p>
      </footer>
    </div>
  );
};

export default Feedback;

import React, { useState, useEffect, useRef } from 'react';
import { UserIdentity } from '../types';
import { motion, AnimatePresence } from 'framer-motion';
import { Upload, X, AlertTriangle } from 'lucide-react';

interface Props {
  onLock: (id: UserIdentity) => void;
}

const IdentitySetup: React.FC<Props> = ({ onLock }) => {
  const [slideIndex, setSlideIndex] = useState(0);
  const [role, setRole] = useState('');
  const [anchors, setAnchors] = useState(['', '', '']);
  const [isLocking, setIsLocking] = useState(false);
  const [showConfirm, setShowConfirm] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  const slides = [
    "This is not a productivity app.",
    "This is a mirror.",
    "You will define who you want to become.",
    "Then you will observe yourself.",
    "Nothing more. Nothing less."
  ];

  const handleNextSlide = () => {
    if (slideIndex < slides.length - 1) setSlideIndex(slideIndex + 1);
    else setSlideIndex(99); // Go to form
  };

  const handleLock = () => {
    if (!role.trim()) return;
    setIsLocking(true);
    const finalAnchors = anchors.filter(a => a.trim() !== '');

    onLock({
      role: role.trim(),
      anchors: finalAnchors,
      lockedAt: new Date().toISOString(),
      expiresAt: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString()
    });
  };

  const handleImportJson = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const json = JSON.parse(event.target?.result as string);
        if (json.role) setRole(json.role);
        if (Array.isArray(json.anchors)) {
          const newAnchors = [...anchors];
          json.anchors.forEach((a: string, i: number) => {
            if (i < 3) newAnchors[i] = a;
          });
          setAnchors(newAnchors);
        }
      } catch (err) {
        console.error("Invalid JSON format", err);
      }
    };
    reader.readAsText(file);
  };

  if (slideIndex < slides.length) {
    return (
      <div 
        onClick={handleNextSlide}
        className="min-h-screen bg-bgMain flex flex-col items-center justify-center p-12 text-center cursor-pointer select-none"
      >
        <AnimatePresence mode="wait">
          <motion.p 
            key={slideIndex}
            initial={{ opacity: 0, scale: 0.98 }}
            animate={{ opacity: 1, scale: 1 }}
            exit={{ opacity: 0, scale: 1.02 }}
            transition={{ duration: 0.8, ease: "easeInOut" }}
            className="text-xl md:text-2xl font-light tracking-wide text-textPrimary max-w-md"
          >
            {slides[slideIndex]}
          </motion.p>
        </AnimatePresence>

        <div className="absolute bottom-16 flex space-x-2">
          {slides.map((_, i) => (
            <div key={i} className={`h-[1px] w-4 transition-all duration-700 ${i === slideIndex ? 'bg-textPrimary' : 'bg-white/10'}`} />
          ))}
        </div>

        <button 
          onClick={(e) => { e.stopPropagation(); setSlideIndex(99); }}
          className="absolute top-12 right-12 text-[10px] uppercase tracking-widest text-textSecondary/40 hover:text-textSecondary"
        >
          Skip
        </button>
      </div>
    );
  }

  return (
    <motion.div 
      initial={{ opacity: 0 }} 
      animate={{ opacity: 1 }}
      className="min-h-screen bg-bgMain flex flex-col items-center justify-center p-6 text-center overflow-y-auto no-scrollbar"
    >
      <AnimatePresence>
        {showConfirm && (
          <motion.div 
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 bg-bgMain/95 z-[100] flex items-center justify-center p-6 backdrop-blur-sm"
          >
            <motion.div 
              initial={{ scale: 0.95, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              className="noah-card max-w-xs w-full p-8 space-y-8 border-accent/20"
            >
              <div className="flex justify-center">
                <AlertTriangle size={32} className="text-accent opacity-50" />
