              <div className="space-y-4">
                <h3 className="noah-title text-center text-textPrimary">Final Confirmation</h3>
                <p className="text-sm text-textSecondary font-light leading-relaxed">
                  This identity cannot be changed for 30 days. The system will hold you to this image.
                </p>
              </div>
              <div className="space-y-3">
                <button
                  onClick={handleLock}
                  className="w-full bg-accent py-4 text-[10px] font-mono tracking-[0.3em] uppercase hover:opacity-90 active-feedback"
