import React from 'react';
import { DailyLog } from '../types';

interface Props {
  logs: DailyLog[];
}

const History: React.FC<Props> = ({ logs }) => {
  const handleExport = () => {
    const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(logs, null, 2));
    const downloadAnchorNode = document.createElement('a');
    downloadAnchorNode.setAttribute("href", dataStr);
    downloadAnchorNode.setAttribute("download", `noah_history_${new Date().toISOString().split('T')[0]}.json`);
    document.body.appendChild(downloadAnchorNode);
    downloadAnchorNode.click();
    downloadAnchorNode.remove();
  };

  if (logs.length === 0) {
    return (
      <div className="flex-grow flex flex-col items-center justify-center text-center p-12 view-transition">
        <p className="text-[10px] font-mono tracking-widest uppercase text-textSecondary/50 max-w-[180px] leading-relaxed">
          No patterns yet. Reality starts today.
        </p>
      </div>
    );
  }

  // Get last 7 days of logs
  const history = logs.slice(-7).reverse();

  // Mapping logic for minimal indicator dots
  // Light = Aligned (high completion/time)
  // Grey = Unstable (moderate completion/time)
  // Dark/Accent = Drifting (low completion/time)
  const getIndicatorColor = (log: DailyLog) => {
    const completionRate = log.anchorsCompleted?.filter(Boolean).length || 0;
    if (completionRate >= 2 && log.timeSpent >= 60) return 'bg-textPrimary'; // Aligned
    if (completionRate >= 1 || log.timeSpent >= 30) return 'bg-textSecondary/30'; // Unstable
    return 'bg-accent'; // Drifting
  };

  return (
    <div className="w-full space-y-12 view-transition pt-8">
      <header className="flex justify-between items-end mb-16">
        <div className="space-y-1">
          <h1 className="noah-title opacity-40">Persistence</h1>
          <p className="text-[10px] font-mono uppercase tracking-[0.3em] text-textSecondary">Last 7 Days</p>
        </div>
        <button 
          onClick={handleExport}
          className="text-[9px] font-mono tracking-widest uppercase text-textSecondary/20 hover:text-textSecondary transition-colors active-feedback"
        >
          Export Data
        </button>
      </header>

      <div className="space-y-10">
        {history.map((log, idx) => {
          const date = new Date(log.date);
          const formattedDate = date.toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' }).toUpperCase();

          return (
            <div key={idx} className="flex items-center justify-between group">
              <span className="text-[10px] font-mono tracking-[0.2em] text-textSecondary/40 group-hover:text-textSecondary/80 transition-colors">
                {formattedDate}
              </span>
              <div className="flex items-center space-x-6">
                <span className="text-[9px] font-mono text-textSecondary/10 opacity-0 group-hover:opacity-100 transition-opacity">
                  {log.timeSpent}m recorded
                </span>
                <div className={`w-1.5 h-1.5 rounded-full ${getIndicatorColor(log)} shadow-[0_0_8px_rgba(255,255,255,0.05)]`} />
              </div>
            </div>
          );
        })}

        {history.length < 3 && (
          <div className="py-20 flex flex-col items-center justify-center space-y-4">
             <div className="w-[1px] h-12 bg-white/5" />
             <p className="text-[9px] font-mono tracking-widest uppercase text-textSecondary/20 text-center max-w-[140px] leading-loose">
               Insufficient data points. Continue observation.
             </p>
          </div>
        )}
      </div>

      <div className="pt-24 space-y-4 border-t border-white/5">
        <div className="flex items-center space-x-4">
          <div className="w-1.5 h-1.5 rounded-full bg-textPrimary" />
          <span className="text-[9px] font-mono tracking-widest uppercase text-textSecondary/40">Aligned</span>
        </div>
        <div className="flex items-center space-x-4">
          <div className="w-1.5 h-1.5 rounded-full bg-textSecondary/30" />
          <span className="text-[9px] font-mono tracking-widest uppercase text-textSecondary/40">Unstable</span>
        </div>
        <div className="flex items-center space-x-4">
          <div className="w-1.5 h-1.5 rounded-full bg-accent" />
          <span className="text-[9px] font-mono tracking-widest uppercase text-textSecondary/40">Drifting</span>
        </div>
      </div>
    </div>
  );
};

