import React from 'react';
import { DailyLog } from '../types';

interface Props {
  logs: DailyLog[];
}

const History: React.FC<Props> = ({ logs }) => {
  const handleExport = () => {
    const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(logs, null, 2));
    const downloadAnchorNode = document.createElement('a');
    downloadAnchorNode.setAttribute("href", dataStr);
    downloadAnchorNode.setAttribute("download", `noah_history_${new Date().toISOString().split('T')[0]}.json`);
    document.body.appendChild(downloadAnchorNode);
    downloadAnchorNode.click();
    downloadAnchorNode.remove();
  };

  if (logs.length === 0) {
    return (
      <div className="flex-grow flex flex-col items-center justify-center text-center p-12 view-transition">
        <p className="text-[10px] font-mono tracking-widest uppercase text-textSecondary/50 max-w-[180px] leading-relaxed">
          No patterns yet. Reality starts today.
        </p>
      </div>
    );
  }

  // Get last 7 days of logs
  const history = logs.slice(-7).reverse();

  // Mapping logic for minimal indicator dots
  const getIndicatorData = (log: DailyLog) => {
    const completionRate = log.anchorsCompleted?.filter(Boolean).length || 0;
    if (completionRate >= 2 && log.timeSpent >= 60) return { color: 'bg-textPrimary', label: 'Aligned' };
    if (completionRate >= 1 || log.timeSpent >= 30) return { color: 'bg-textSecondary/30', label: 'Unstable' };
    return { color: 'bg-accent', label: 'Drifting' };
  };

  return (
    <div className="w-full space-y-12 view-transition pt-8">
      <header className="flex justify-between items-end mb-16">
        <div className="space-y-1">
          <h1 className="noah-title opacity-40">Persistence</h1>
          <p className="text-[10px] font-mono uppercase tracking-[0.3em] text-textSecondary">Last 7 Days</p>
        </div>
        <button 
          onClick={handleExport}
          className="text-[9px] font-mono tracking-widest uppercase text-textSecondary/20 hover:text-textSecondary transition-colors active-feedback"
          aria-label="Export history as JSON"
        >
          Export Data
        </button>
      </header>

      <div className="space-y-10" role="list" aria-label="Daily logs history">
        {history.map((log, idx) => {
          const date = new Date(log.date);
          const formattedDate = date.toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' }).toUpperCase();
          const indicator = getIndicatorData(log);

          return (
            <div key={idx} role="listitem" className="flex items-center justify-between group">
              <span className="text-[10px] font-mono tracking-[0.2em] text-textSecondary/40 group-hover:text-textSecondary/80 transition-colors">
                {formattedDate}
              </span>
              <div className="flex items-center space-x-6">
                <span className="text-[9px] font-mono text-textSecondary/10 opacity-0 group-hover:opacity-100 transition-opacity" aria-hidden="true">
                  {log.timeSpent}m recorded
                </span>
                <div 
                  className={`w-1.5 h-1.5 rounded-full ${indicator.color} shadow-[0_0_8px_rgba(255,255,255,0.05)]`} 
                  aria-label={`Status: ${indicator.label}, ${log.timeSpent} minutes spent`}
                  role="img"
                />
              </div>
            </div>
          );
        })}

        {history.length < 3 && (
