const CACHE_NAME = 'noah-v1';

self.addEventListener('install', (event) => {
  // Activate immediately after installing
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  // Take control of all pages immediately
  event.waitUntil(clients.claim());
});

self.addEventListener('fetch', (event) => {
  // Simple network-first strategy for a data-driven app
  event.respondWith(
    fetch(event.request).catch(() => {
      return caches.match(event.request);
    })
  );
});

self.addEventListener('message', (event) => {
  if (event.data && event.data.type === 'SKIP_WAITING') {
    self.skipWaiting();
  }
});

import React, { useState, useEffect, useMemo } from 'react';
import { AppView, UserIdentity, DailyLog } from './types';
import { store } from './store';
import IdentitySetup from './components/IdentitySetup';
import CheckIn from './components/CheckIn';
import Feedback from './components/Feedback';
import History from './components/History';
import Landing from './components/Landing';
import Auth from './components/Auth';
import Renewal from './components/Renewal';
import { Circle, MessageSquare, Clock, RefreshCw, WifiOff, ArrowUpCircle } from 'lucide-react';
import { AnimatePresence, motion } from 'framer-motion';

const App: React.FC = () => {
  const [view, setView] = useState<AppView>('LANDING');
  const [identity, setIdentity] = useState<UserIdentity | null>(null);
  const [logs, setLogs] = useState<DailyLog[]>([]);
  const [userEmail, setUserEmail] = useState<string | null>(null);
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [isSyncing, setIsSyncing] = useState(false);
  const [updateAvailable, setUpdateAvailable] = useState(false);

  const isExpired = useMemo(() => {
    if (!identity) return false;
    const expiresAt = new Date(identity.expiresAt).getTime();
    const now = new Date().getTime();
    return now >= expiresAt;
  }, [identity]);

  useEffect(() => {
    const storedIdentity = store.getIdentity();
    const storedLogs = store.getLogs();
    const storedEmail = store.getEmail();
    const seenLanding = store.hasSeenLanding();

    setIdentity(storedIdentity);
    setLogs(storedLogs);
    setUserEmail(storedEmail);

    if (seenLanding) {
      if (!storedIdentity) setView('SETUP');
      else if (new Date().getTime() >= new Date(storedIdentity.expiresAt).getTime()) setView('RENEWAL');
      else setView('CHECKIN');
    } else {
      setView('LANDING');
    }

    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    if ('serviceWorker' in navigator) {
      navigator.serviceWorker.register('/sw.js').then((reg) => {
        reg.addEventListener('updatefound', () => {
          const newWorker = reg.installing;
          if (newWorker) {
            newWorker.addEventListener('statechange', () => {
              if (newWorker.state === 'installed' && navigator.serviceWorker.controller) {
                setUpdateAvailable(true);
              }
            });
          }
        });
      });

      navigator.serviceWorker.ready.then((reg) => {
        if (reg.waiting) {
          setUpdateAvailable(true);
        }
      });
    }

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  const handleUpdate = () => {
    if ('serviceWorker' in navigator) {
      navigator.serviceWorker.getRegistration().then((reg) => {
        if (reg?.waiting) {
          reg.waiting.postMessage({ type: 'SKIP_WAITING' });
        }
        window.location.reload();
      });
    } else {
      window.location.reload();
    }
  };

  const triggerSync = async () => {
    if (!isOnline || !userEmail) return;
    setIsSyncing(true);
    await new Promise(r => setTimeout(r, 1000));
    setIsSyncing(false);
  };

  const handleLandingProceed = () => setView('AUTH');
  const handleLandingEnter = () => {
    store.setSeenLanding();
    if (!identity) setView('SETUP');
    else if (isExpired) setView('RENEWAL');
    else setView('CHECKIN');
  };

  const handleAuthSuccess = (email: string) => {
    store.saveEmail(email);
    setUserEmail(email);
    store.setSeenLanding();
    if (!identity) setView('SETUP');
    else if (isExpired) setView('RENEWAL');
    else setView('CHECKIN');
    triggerSync();
  };

  const handleIdentityLocked = (newIdentity: UserIdentity) => {
    setIdentity(newIdentity);
    store.saveIdentity(newIdentity);
    setView('CHECKIN');
  };

  const handleLogSubmitted = (newLog: DailyLog) => {
    store.addLog(newLog);
    setLogs(prev => [...prev.filter(l => l.date !== newLog.date), newLog]);
    setView('FEEDBACK');
    triggerSync();
  };

  const handleCycleReset = () => {
    localStorage.removeItem('noah_identity');
    localStorage.removeItem('noah_logs');
    setIdentity(null);
    setLogs([]);
    setView('SETUP');
  };

  if (view === 'LANDING') return <Landing onProceed={handleLandingProceed} onEnter={handleLandingEnter} />;
  if (view === 'AUTH') return <Auth onSuccess={handleAuthSuccess} onSkip={handleLandingEnter} />;
  if (view === 'SETUP' || !identity) return <IdentitySetup onLock={handleIdentityLocked} />;

  return (
    <div className="min-h-screen bg-bgMain flex flex-col items-center max-w-md mx-auto relative px-6 pb-24 overflow-hidden">
      <AnimatePresence>
        {updateAvailable && (
          <motion.div 
            initial={{ y: -100, opacity: 0 }}
            animate={{ y: 0, opacity: 1 }}
            exit={{ y: -100, opacity: 0 }}
            className="fixed top-0 left-0 right-0 z-[100] p-4 flex justify-center pointer-events-none"
          >
            <div className="bg-bgSurface border border-accent/30 shadow-2xl p-4 flex items-center justify-between space-x-6 max-w-xs w-full pointer-events-auto rounded-sm">
              <div className="flex items-center space-x-3">
                <ArrowUpCircle size={16} className="text-accent" />
                <span className="text-[10px] font-mono tracking-widest uppercase text-textPrimary">System Update Available</span>
              </div>
              <button 
                onClick={handleUpdate}
                className="bg-accent/20 hover:bg-accent text-accent hover:text-textPrimary px-3 py-1.5 text-[9px] font-mono tracking-widest uppercase transition-all active-feedback"
              >
                Refresh
              </button>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      <header className="w-full py-6 flex justify-between items-center z-20" role="banner">
        <div className="flex items-center space-x-2">
          <span className="text-[10px] font-mono tracking-widest text-textSecondary/40 uppercase">N.O.A.H</span>
          {isSyncing && <RefreshCw size={10} className="text-accent animate-spin" aria-label="Synchronizing" />}
        </div>
        {!isOnline && (
          <div className="flex items-center space-x-1.5 opacity-40" aria-label="Offline Mode">
            <WifiOff size={12} className="text-textSecondary" />
            <span className="text-[8px] font-mono tracking-widest uppercase text-textSecondary">Local Session</span>
          </div>
        )}
      </header>

      <main className="w-full flex-grow flex flex-col relative z-10" id="main-content" role="main">
        <AnimatePresence mode="wait">
          <motion.div
            key={view}
            initial={{ opacity: 0, scale: 0.98 }}
            animate={{ opacity: 1, scale: 1 }}
            exit={{ opacity: 0, scale: 1.02 }}
            transition={{ duration: 0.15, ease: "easeOut" }}
            className="w-full flex-grow flex flex-col"
          >
            {view === 'CHECKIN' && <CheckIn identity={identity} logs={logs} onComplete={handleLogSubmitted} />}
            {view === 'FEEDBACK' && <Feedback identity={identity} logs={logs} onCycleReset={handleCycleReset} />}
            {view === 'HISTORY' && <History logs={logs} />}
            {view === 'RENEWAL' && <Renewal identity={identity} onRecommit={() => setView('CHECKIN')} onReset={handleCycleReset} />}
          </motion.div>
        </AnimatePresence>
      </main>

      <nav className="fixed bottom-0 left-0 right-0 bg-bgSurface/95 backdrop-blur-md border-t border-white/5 h-20 flex items-center justify-around px-4 z-50 pb-[env(safe-area-inset-bottom)]" role="navigation" aria-label="Main Navigation">
        <NavButton active={view === 'CHECKIN'} icon={<Circle size={18} />} label="Check-in" onClick={() => setView('CHECKIN')} />
        <NavButton active={view === 'FEEDBACK'} icon={<MessageSquare size={18} />} label="Truth" onClick={() => setView('FEEDBACK')} />
        <NavButton active={view === 'HISTORY'} icon={<Clock size={18} />} label="History" onClick={() => setView('HISTORY')} />
      </nav>
    </div>
  );
};

const NavButton = ({ active, icon, label, onClick }: { active: boolean, icon: React.ReactNode, label: string, onClick: () => void }) => (
  <button 
    onClick={onClick}
    aria-current={active ? 'page' : undefined}
    className={`flex flex-col items-center space-y-1 transition-all duration-300 active-feedback ${active ? 'text-textPrimary' : 'text-textSecondary/30'}`}
  >
    <div className={`${active ? 'text-accent scale-110' : ''} transition-all`} aria-hidden="true">{icon}</div>
    <span className="text-[9px] uppercase tracking-widest font-mono font-medium">{label}</span>
  </button>
);

export default App;

