interface Props {
  identity: UserIdentity;
  logs: DailyLog[];
  onComplete: (log: DailyLog) => void;
}

const CheckIn: React.FC<Props> = ({ identity, logs, onComplete }) => {
  const [action, setAction] = useState('');
  const [time, setTime] = useState(60);
  const [state, setState] = useState('');
  const [energy, setEnergy] = useState<EnergyLevel>('MEDIUM');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [lastStatus, setLastStatus] = useState<string | null>(null);

  useEffect(() => {
    const feedback = store.getLastFeedback();
    if (feedback) setLastStatus(feedback.status);
  }, []);

  const todayStr = new Date().toLocaleDateString('en-US', {
    month: 'short',
    day: 'numeric',
    year: 'numeric'
  }).toUpperCase();

  const handleSubmit = () => {
    if (!action || !state) return;
    setIsSubmitting(true);

    const log: DailyLog = {
      date: new Date().toISOString(),
      action,
      timeSpent: time,
      mentalState: state,
      energy,
      anchorsCompleted: new Array(identity.anchors.length).fill(true) // Defaulting to true for silent tracking or custom logic
