            <span className="text-sm font-mono text-textPrimary">{time}{time >= 180 ? '+' : ''}m</span>
          </div>
          <input
            id="time-slider"
            type="range"
            min="0"
            max="180"
            step="15"
            value={time}
            onChange={(e) => setTime(parseInt(e.target.value))}
            className="w-full active-feedback"
          />
        </section>

        {/* Section 3: Mental State */}
        <section className="space-y-4">
          <label htmlFor="mental-state" className="text-[10px] font-mono tracking-widest uppercase text-textSecondary">
            Mental State
          </label>
          <input
            id="mental-state"
            type="text"
            value={state}
            onChange={(e) => setState(e.target.value)}
