        >
          <BrainCircuit size={14} />
          <span>Request Deep Analysis</span>
        </button>
      </div>

      <footer className="absolute bottom-12 opacity-20">
        <p className="text-[9px] font-mono tracking-[0.5em] uppercase">
          Based on recent patterns
        </p>
      </footer>
    </div>
  );
};

export default Feedback;

export type EnergyLevel = 'LOW' | 'MEDIUM' | 'HIGH';

// Equivalent to 'checkins' table
export interface DailyLog {
  id: string;          // checkin id
  identity_id: string; // link to anon_id
  date: string;        // ISO string
  note: string;        // formerly 'action'
  state: string;       // formerly 'mentalState'
  timeSpent: number;
  energy: EnergyLevel;
  anchorsCompleted?: boolean[];
}

// Equivalent to 'identities' table
export interface UserIdentity {
  id: string;          // anon_id
  role: string;
  anchors: string[];
  created_at: string;  // ISO string (formerly 'lockedAt')
  cycle_start: string; // ISO string
  status: AlignmentStatus;
  expiresAt: string;   // ISO string (end of 30-day window)
}

export type AppView = 'LANDING' | 'AUTH' | 'SETUP' | 'CHECKIN' | 'FEEDBACK' | 'HISTORY' | 'RENEWAL' | 'IDENTITY';

export type AlignmentStatus = 'ALIGNED' | 'UNSTABLE' | 'DRIFTING';

export interface FeedbackData {
  status: AlignmentStatus;
  message: string;
  observation?: string;
}

export interface NoahState {
  userId: string | null;
  identity: UserIdentity | null;
  checkIns: DailyLog[];
}

import { DailyLog, UserIdentity, FeedbackData } from './types';

const KEYS = {
  ANON_ID: 'noah_anon_id',
  IDENTITY: 'noah_identity',
  LOGS: 'noah_logs',
  LAST_FEEDBACK: 'noah_feedback',
  USER_EMAIL: 'noah_user_email',
  SEEN_LANDING: 'noah_seen_landing'
};

const generateUUID = () => {
  return 'xxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
    const r = Math.random() * 16 | 0;
    const v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
};

export const store = {
  getAnonId: (): string => {
    let id = localStorage.getItem(KEYS.ANON_ID);
    if (!id) {
      id = generateUUID();
      localStorage.setItem(KEYS.ANON_ID, id);
    }
    return id;
  },
  getIdentity: (): UserIdentity | null => {
    const data = localStorage.getItem(KEYS.IDENTITY);
    return data ? JSON.parse(data) : null;
  },
  saveIdentity: (identity: UserIdentity) => {
    localStorage.setItem(KEYS.IDENTITY, JSON.stringify(identity));
  },
  getLogs: (): DailyLog[] => {
    const data = localStorage.getItem(KEYS.LOGS);
    return data ? JSON.parse(data) : [];
  },
  addLog: (log: DailyLog) => {
    const logs = store.getLogs();
    // Unique per date or ID
    const filtered = logs.filter(l => l.date !== log.date && l.id !== log.id);
    localStorage.setItem(KEYS.LOGS, JSON.stringify([...filtered, log]));
  },
  getLastFeedback: (): FeedbackData | null => {
    const data = localStorage.getItem(KEYS.LAST_FEEDBACK);
    return data ? JSON.parse(data) : null;
  },
  saveFeedback: (feedback: FeedbackData) => {
    localStorage.setItem(KEYS.LAST_FEEDBACK, JSON.stringify(feedback));
  },
  getEmail: (): string | null => {
    return localStorage.getItem(KEYS.USER_EMAIL);
  },
  saveEmail: (email: string) => {
    localStorage.setItem(KEYS.USER_EMAIL, email);
  },
  hasSeenLanding: (): boolean => {
    return localStorage.getItem(KEYS.SEEN_LANDING) === 'true';
  },
  setSeenLanding: () => {
    localStorage.setItem(KEYS.SEEN_LANDING, 'true');
  },
  clearAll: () => {
    localStorage.removeItem(KEYS.IDENTITY);
    localStorage.removeItem(KEYS.LOGS);
    localStorage.removeItem(KEYS.LAST_FEEDBACK);
  }
};

import React, { useState, useEffect, useMemo } from 'react';
import { AppView, UserIdentity, DailyLog } from './types';
import { store } from './store';
import IdentitySetup from './components/IdentitySetup';
import CheckIn from './components/CheckIn';
import Feedback from './components/Feedback';
import History from './components/History';
import Landing from './components/Landing';
import Auth from './components/Auth';
import Renewal from './components/Renewal';
import IdentityView from './components/IdentityView';
import { Circle, MessageSquare, Clock, User as UserIcon, RefreshCw, WifiOff } from 'lucide-react';
import { AnimatePresence, motion } from 'framer-motion';

const App: React.FC = () => {
  const [view, setView] = useState<AppView>('LANDING');
  const [identity, setIdentity] = useState<UserIdentity | null>(null);
  const [logs, setLogs] = useState<DailyLog[]>([]);
  const [userEmail, setUserEmail] = useState<string | null>(null);
  const [anonId, setAnonId] = useState<string | null>(null);
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [isSyncing, setIsSyncing] = useState(false);

  const isExpired = useMemo(() => {
    if (!identity) return false;
    const expiresAt = new Date(identity.expiresAt).getTime();
    const now = new Date().getTime();
    return now >= expiresAt;
  }, [identity]);

  useEffect(() => {
    // 1. Initialize anonymous ID
    const id = store.getAnonId();
    setAnonId(id);

    const storedIdentity = store.getIdentity();
    const storedLogs = store.getLogs();
    const storedEmail = store.getEmail();
    const seenLanding = store.hasSeenLanding();

    setIdentity(storedIdentity);
    setLogs(storedLogs);
    setUserEmail(storedEmail);

    if (seenLanding) {
      if (!storedIdentity) setView('SETUP');
      else if (new Date().getTime() >= new Date(storedIdentity.expiresAt).getTime()) setView('RENEWAL');
      else setView('CHECKIN');
    } else {
      setView('LANDING');
    }

    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  const triggerSync = async () => {
    if (!isOnline || (!userEmail && !anonId)) return;
    setIsSyncing(true);
    // Sync logic uses anonId as the primary identifier if email isn't present
    await new Promise(r => setTimeout(r, 1000));
    setIsSyncing(false);
  };

  const handleLandingProceed = () => setView('AUTH');
  const handleLandingEnter = () => {
    store.setSeenLanding();
    if (!identity) setView('SETUP');
    else if (isExpired) setView('RENEWAL');
    else setView('CHECKIN');
  };

  const handleAuthSuccess = (email: string) => {
    store.saveEmail(email);
    setUserEmail(email);
    store.setSeenLanding();
    if (!identity) setView('SETUP');
    else if (isExpired) setView('RENEWAL');
    else setView('CHECKIN');
    triggerSync();
  };

  const handleIdentityLocked = (newIdentity: UserIdentity) => {
    setIdentity(newIdentity);
    store.saveIdentity(newIdentity);
    setView('CHECKIN');
  };

  const handleLogSubmitted = (newLog: DailyLog) => {
    store.addLog(newLog);
    setLogs(prev => [...prev.filter(l => l.id !== newLog.id), newLog]);
    setView('FEEDBACK');
    triggerSync();
  };

  const handleCycleReset = () => {
    store.clearAll();
    setIdentity(null);
    setLogs([]);
    setView('SETUP');
  };

  if (view === 'LANDING') return <Landing onProceed={handleLandingProceed} onEnter={handleLandingEnter} />;
  if (view === 'AUTH') return <Auth onSuccess={handleAuthSuccess} onSkip={handleLandingEnter} />;
  if (view === 'SETUP' || !identity) return <IdentitySetup onLock={handleIdentityLocked} />;

  return (
    <div className="min-h-screen bg-bgMain flex flex-col items-center max-w-md mx-auto relative px-6 pb-24 overflow-hidden">
      <header className="w-full py-6 flex justify-between items-center z-20" role="banner">
        <div className="flex flex-col">
          <span className="text-[10px] font-mono tracking-widest text-textSecondary/40 uppercase">N.O.A.H</span>
          {anonId && (
            <span className="text-[7px] font-mono text-textSecondary/20 uppercase tracking-tighter">
              Node: {anonId.slice(0, 8)}
            </span>
          )}
        </div>
        <div className="flex items-center space-x-3">
          {isSyncing && <RefreshCw size={10} className="text-accent animate-spin" aria-label="Synchronizing" />}
          {!isOnline && (
            <div className="flex items-center space-x-1.5 opacity-40" aria-label="Offline Mode">
              <WifiOff size={12} className="text-textSecondary" />
            </div>
          )}
        </div>
      </header>

      <main className="w-full flex-grow flex flex-col relative z-10" id="main-content" role="main">
        <AnimatePresence mode="wait">
          <motion.div
            key={view}
            initial={{ opacity: 0, scale: 0.98 }}
            animate={{ opacity: 1, scale: 1 }}
            exit={{ opacity: 0, scale: 1.02 }}
            transition={{ duration: 0.15, ease: "easeOut" }}
            className="w-full flex-grow flex flex-col"
          >
            {view === 'CHECKIN' && <CheckIn identity={identity} logs={logs} onComplete={handleLogSubmitted} />}
            {view === 'FEEDBACK' && <Feedback identity={identity} logs={logs} onCycleReset={handleCycleReset} />}
            {view === 'HISTORY' && <History logs={logs} />}
            {view === 'RENEWAL' && <Renewal identity={identity} onRecommit={() => setView('CHECKIN')} onReset={handleCycleReset} />}
            {view === 'IDENTITY' && <IdentityView identity={identity} />}
          </motion.div>
        </AnimatePresence>
      </main>

      <nav className="fixed bottom-0 left-0 right-0 bg-bgSurface/95 backdrop-blur-md border-t border-white/5 h-20 flex items-center justify-around px-4 z-50 pb-[env(safe-area-inset-bottom)]" role="navigation" aria-label="Main Navigation">
        <NavButton active={view === 'CHECKIN'} icon={<Circle size={18} />} label="Check-in" onClick={() => setView('CHECKIN')} />
        <NavButton active={view === 'FEEDBACK'} icon={<MessageSquare size={18} />} label="Truth" onClick={() => setView('FEEDBACK')} />
        <NavButton active={view === 'HISTORY'} icon={<Clock size={18} />} label="History" onClick={() => setView('HISTORY')} />
        <NavButton active={view === 'IDENTITY'} icon={<UserIcon size={18} />} label="Id" onClick={() => setView('IDENTITY')} />
      </nav>
    </div>
  );
};

const NavButton = ({ active, icon, label, onClick }: { active: boolean, icon: React.ReactNode, label: string, onClick: () => void }) => (
  <button 
    onClick={onClick}
    aria-current={active ? 'page' : undefined}
    className={`flex flex-col items-center space-y-1 transition-all duration-300 active-feedback ${active ? 'text-textPrimary' : 'text-textSecondary/30'}`}
  >
    <div className={`${active ? 'text-accent scale-110' : ''} transition-all`} aria-hidden="true">{icon}</div>
    <span className="text-[9px] uppercase tracking-widest font-mono font-medium">{label}</span>
  </button>
);

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { UserIdentity } from '../types';
import { motion, AnimatePresence } from 'framer-motion';
import { Upload, X, AlertTriangle } from 'lucide-react';
import { store } from '../store';

interface Props {
  onLock: (id: UserIdentity) => void;
}

const IdentitySetup: React.FC<Props> = ({ onLock }) => {
  const [slideIndex, setSlideIndex] = useState(0);
  const [role, setRole] = useState('');
  const [anchors, setAnchors] = useState(['', '', '']);
  const [isLocking, setIsLocking] = useState(false);
  const [showConfirm, setShowConfirm] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  const slides = [
    "This is not a productivity app.",
    "This is a mirror.",
    "You will define who you want to become.",
    "Then you will observe yourself.",
    "Nothing more. Nothing less."
  ];

  const handleNextSlide = () => {
    if (slideIndex < slides.length - 1) setSlideIndex(slideIndex + 1);
    else setSlideIndex(99); // Go to form
  };

  const handleLock = () => {
    if (!role.trim()) return;
    setIsLocking(true);
    const finalAnchors = anchors.filter(a => a.trim() !== '');
    const now = new Date().toISOString();
    const anonId = store.getAnonId();

    onLock({
      id: anonId,
      role: role.trim(),
      anchors: finalAnchors,
      created_at: now,
      cycle_start: now,
      status: 'UNSTABLE',
      expiresAt: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString()
    });
  };

  const handleImportJson = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const json = JSON.parse(event.target?.result as string);
        if (json.role) setRole(json.role);
        if (Array.isArray(json.anchors)) {
          const newAnchors = [...anchors];
          json.anchors.forEach((a: string, i: number) => {
            if (i < 3) newAnchors[i] = a;
          });
          setAnchors(newAnchors);
        }
      } catch (err) {
        console.error("Invalid JSON format", err);
      }
    };
    reader.readAsText(file);
  };

  if (slideIndex < slides.length) {
    return (
      <div 
        onClick={handleNextSlide}
        role="button"
        tabIndex={0}
        onKeyDown={(e) => { if (e.key === 'Enter' || e.key === ' ') handleNextSlide(); }}
        aria-label="Click to proceed through introduction"
        className="min-h-screen bg-bgMain flex flex-col items-center justify-center p-12 text-center cursor-pointer select-none"
      >
        <AnimatePresence mode="wait">
          <motion.p 
            key={slideIndex}
            initial={{ opacity: 0, scale: 0.98 }}
            animate={{ opacity: 1, scale: 1 }}
            exit={{ opacity: 0, scale: 1.02 }}
            transition={{ duration: 0.8, ease: "easeInOut" }}
            className="text-xl md:text-2xl font-light tracking-wide text-textPrimary max-w-md"
            aria-live="polite"
          >
            {slides[slideIndex]}
          </motion.p>
        </AnimatePresence>

        <div className="absolute bottom-16 flex space-x-2" role="presentation">
          {slides.map((_, i) => (
            <div key={i} className={`h-[1px] w-4 transition-all duration-700 ${i === slideIndex ? 'bg-textPrimary' : 'bg-white/10'}`} />
          ))}
        </div>

        <button 
          onClick={(e) => { e.stopPropagation(); setSlideIndex(99); }}
          className="absolute top-12 right-12 text-[10px] uppercase tracking-widest text-textSecondary/40 hover:text-textSecondary"
        >
          Skip Intro
        </button>
      </div>
    );
  }

  return (
    <motion.div 
      initial={{ opacity: 0 }} 
      animate={{ opacity: 1 }}
      className="min-h-screen bg-bgMain flex flex-col items-center justify-center p-6 text-center overflow-y-auto no-scrollbar"
    >
      <AnimatePresence>
        {showConfirm && (
          <motion.div 
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            role="dialog"
            aria-modal="true"
            aria-labelledby="confirm-title"
            aria-describedby="confirm-desc"
            className="fixed inset-0 bg-bgMain/95 z-[100] flex items-center justify-center p-6 backdrop-blur-sm"
          >
            <motion.div 
              initial={{ scale: 0.95, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              className="noah-card max-w-xs w-full p-8 space-y-8 border-accent/20"
            >
              <div className="flex justify-center" aria-hidden="true">
                <AlertTriangle size={32} className="text-accent opacity-50" />
              </div>
              <div className="space-y-4">
                <h3 id="confirm-title" className="noah-title text-center text-textPrimary">Final Confirmation</h3>
                <p id="confirm-desc" className="text-sm text-textSecondary font-light leading-relaxed">
                  This identity cannot be changed for 30 days. The system will hold you to this image.
                </p>
              </div>
              <div className="space-y-3">
                <button
                  onClick={handleLock}
                  className="w-full bg-accent py-4 text-[10px] font-mono tracking-[0.3em] uppercase hover:opacity-90 active-feedback"
                >
                  Confirm Lock
                </button>
                <button
                  onClick={() => setShowConfirm(false)}
                  className="w-full py-4 text-[10px] font-mono tracking-[0.3em] uppercase text-textSecondary/40 hover:text-textSecondary/60 active-feedback"
                >
                  Review
                </button>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      <div className="w-full max-w-sm space-y-16 py-12">
        <header className="flex justify-between items-center">
          <button 
            onClick={() => fileInputRef.current?.click()}
            className="flex items-center space-x-2 text-[10px] uppercase tracking-widest text-textSecondary/40 hover:text-textSecondary transition-colors"
            aria-label="Import identity from JSON file"
          >
            <Upload size={12} aria-hidden="true" />
            <span>Import Identity</span>
          </button>
          <input 
            ref={fileInputRef}
            type="file" 
            id="json-import"
            accept=".json" 
            onChange={handleImportJson} 
            className="hidden" 
          />
        </header>

        <div className="space-y-6">
          <label htmlFor="identity-input" className="noah-title block">Who do you want to become?</label>
          <input
            ref={inputRef}
            id="identity-input"
            type="text"
            value={role}
            onChange={(e) => setRole(e.target.value)}
            placeholder="Founder. Artist. Student."
            className="w-full bg-transparent border-b border-white/10 py-3 text-2xl text-center focus:outline-none focus:border-accent transition-colors placeholder:text-textSecondary/20"
            autoFocus
          />
        </div>

        <div className="space-y-8">
          <h2 className="noah-title">Behavioral Anchors (Max 3)</h2>
          <div className="space-y-4">
            {anchors.map((a, i) => (
              <div key={i}>
                <label htmlFor={`anchor-${i}`} className="sr-only">Anchor {i + 1}</label>
                <input
                  id={`anchor-${i}`}
                  type="text"
                  value={a}
                  onChange={(e) => {
                    const n = [...anchors];
                    n[i] = e.target.value;
                    setAnchors(n);
                  }}
                  placeholder={`Anchor ${i + 1}`}
                  className="w-full bg-muted/30 border border-border/50 rounded-sm p-4 text-sm focus:outline-none focus:border-accent transition-all text-center"
                />
              </div>
            ))}
          </div>
        </div>

        <div className="space-y-8">
          <p className="text-[10px] uppercase tracking-widest text-textSecondary opacity-30" aria-live="polite">
            Identity locks for 30 days
          </p>
          <button
            onClick={() => setShowConfirm(true)}
            disabled={!role.trim() || isLocking}
            className="w-full bg-accent py-4 text-[11px] font-mono tracking-[0.4em] uppercase hover:opacity-90 transition-all active-feedback disabled:opacity-10"
          >
            {isLocking ? 'Processing...' : 'Lock Identity'}
          </button>
        </div>
      </div>
    </motion.div>
  );
};

export default IdentitySetup;

import React, { useState, useMemo, useRef } from 'react';
import { DailyLog, EnergyLevel, UserIdentity } from '../types';
import { ChevronDown, AlertCircle, Mic, Square, Loader2 } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { transcribeAudio } from '../services/geminiService';

interface Props {
  identity: UserIdentity;
  logs: DailyLog[];
  onComplete: (log: DailyLog) => void;
}

const CheckIn: React.FC<Props> = ({ identity, logs, onComplete }) => {
  const [note, setNote] = useState('');
  const [time, setTime] = useState(60);
  const [state, setState] = useState('');
  const [energy, setEnergy] = useState<EnergyLevel>('MEDIUM');
  const [anchorStatus, setAnchorStatus] = useState<boolean[]>(new Array(identity.anchors.length).fill(false));
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [showAnchors, setShowAnchors] = useState(false);

  const [isRecording, setIsRecording] = useState(false);
  const [isTranscribing, setIsTranscribing] = useState(false);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioChunksRef = useRef<Blob[]>([]);

  // Constants & Calculations
  const today = new Date();
  const todayStr = today.toLocaleDateString('en-US', {
    month: 'short',
    day: 'numeric',
    year: 'numeric'
  }).toUpperCase();

  const dayOfCycle = useMemo(() => {
    const start = new Date(identity.created_at).getTime();
    const diff = Math.floor((today.getTime() - start) / (1000 * 60 * 60 * 24));
    return Math.min(diff + 1, 30);
  }, [identity.created_at]);

  const { continuity, showWarning } = useMemo(() => {
    if (logs.length === 0) return { continuity: 0, showWarning: false };

    const sortedLogs = [...logs].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    const lastLogDate = new Date(sortedLogs[0].date);
    lastLogDate.setHours(0,0,0,0);

    const midnightToday = new Date();
    midnightToday.setHours(0,0,0,0);

    const diffDays = Math.floor((midnightToday.getTime() - lastLogDate.getTime()) / (1000 * 60 * 60 * 24));

    let count = 0;
    let checkDate = new Date(midnightToday);

    if (diffDays > 0) {
      checkDate.setDate(checkDate.getDate() - 1);
    }

    const logDates = new Set(logs.map(l => {
      const d = new Date(l.date);
      d.setHours(0,0,0,0);
      return d.getTime();
    }));

    while (logDates.has(checkDate.getTime())) {
      count++;
      checkDate.setDate(checkDate.getDate() - 1);
    }

    return { 
      continuity: count, 
      showWarning: diffDays >= 2 
    };
  }, [logs]);

  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const mediaRecorder = new MediaRecorder(stream);
      mediaRecorderRef.current = mediaRecorder;
      audioChunksRef.current = [];

      mediaRecorder.ondataavailable = (event) => {
        audioChunksRef.current.push(event.data);
      };

      mediaRecorder.onstop = async () => {
        const audioBlob = new Blob(audioChunksRef.current, { type: 'audio/webm' });
        const reader = new FileReader();
        reader.readAsDataURL(audioBlob);
        reader.onloadend = async () => {
          const base64Data = (reader.result as string).split(',')[1];
          setIsTranscribing(true);
          try {
            const text = await transcribeAudio(base64Data, 'audio/webm');
            setNote((prev) => (prev + ' ' + text).trim().slice(0, 120));
          } catch (error) {
            console.error(error);
          } finally {
            setIsTranscribing(false);
          }
        };
        stream.getTracks().forEach(track => track.stop());
      };

      mediaRecorder.start();
      setIsRecording(true);
    } catch (error) {
      console.error('Mic error:', error);
    }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
    }
  };

  const handleSubmit = () => {
    if (!note || !state) return;
    setIsSubmitting(true);

    const log: DailyLog = {
      id: Math.random().toString(36).substring(7),
      identity_id: identity.id,
      date: new Date().toISOString(),
      note,
      timeSpent: time,
      state,
      energy,
      anchorsCompleted: anchorStatus
    };

    setTimeout(() => {
      onComplete(log);
    }, 400);
  };

  const toggleAnchor = (index: number) => {
    const next = [...anchorStatus];
    next[index] = !next[index];
    setAnchorStatus(next);
  };

  return (
    <div className="w-full pb-20 view-transition font-sans">
      <AnimatePresence>
        {isSubmitting && (
          <motion.div 
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 bg-bgMain z-[100] flex items-center justify-center"
            role="alert"
            aria-live="assertive"
          >
            <span className="text-[11px] font-mono tracking-[0.5em] uppercase text-textPrimary">Logged.</span>
          </motion.div>
        )}
      </AnimatePresence>

      <header className="space-y-6 mb-12">
        <div className="flex justify-between items-start">
          <div className="space-y-1">
            <h1 className="text-[11px] font-mono tracking-[0.2em] text-textSecondary uppercase">{todayStr}</h1>
            <p className="text-sm font-semibold uppercase tracking-widest text-textPrimary">Day {dayOfCycle} of 30</p>
          </div>
          <div className="text-right space-y-1">
            <p className="text-[10px] font-mono tracking-widest text-textSecondary/40 uppercase">Identity: {identity.role}</p>
            <p className="text-[10px] font-mono tracking-widest text-accent uppercase" aria-label={`Continuity: ${continuity} Days`}>Continuity: {continuity} Days</p>
          </div>
        </div>

        {showWarning && (
          <motion.div 
            initial={{ opacity: 0, y: -10 }}
            animate={{ opacity: 1, y: 0 }}
            className="flex items-center space-x-3 p-4 bg-accent/5 border border-accent/20"
            role="alert"
          >
            <AlertCircle size={14} className="text-accent" aria-hidden="true" />
            <span className="text-[10px] font-mono tracking-widest uppercase text-accent">Observation gap detected.</span>
          </motion.div>
        )}

        <div className="noah-card overflow-hidden">
          <button 
            onClick={() => setShowAnchors(!showAnchors)}
            className="w-full flex items-center justify-between p-4 active-feedback"
            aria-expanded={showAnchors}
            aria-controls="anchor-details"
          >
            <span className="noah-title">Anchors being tracked</span>
            <ChevronDown size={14} className={`text-textSecondary/40 transition-transform ${showAnchors ? 'rotate-180' : ''}`} aria-hidden="true" />
          </button>
          <AnimatePresence>
            {showAnchors && (
              <motion.div 
                id="anchor-details"
                initial={{ height: 0 }}
                animate={{ height: 'auto' }}
                exit={{ height: 0 }}
                className="px-4 pb-4 space-y-2"
              >
                {identity.anchors.map((anchor, i) => (
                  <p key={i} className="text-xs text-textSecondary font-light leading-relaxed">• {anchor}</p>
                ))}
              </motion.div>
            )}
          </AnimatePresence>
        </div>
      </header>

      <div className="space-y-10">
        <section className="space-y-4">
          <div className="flex justify-between items-center">
            <label htmlFor="daily-action" className="text-[10px] font-mono tracking-widest uppercase text-textSecondary">
              What did you actually do today?
            </label>
            <div className="flex items-center space-x-2">
              {isTranscribing && <Loader2 size={12} className="text-accent animate-spin" />}
              <button
                type="button"
                onClick={isRecording ? stopRecording : startRecording}
                disabled={isTranscribing}
                className={`p-2 rounded-full transition-all active-feedback ${isRecording ? 'bg-accent/20 text-accent animate-pulse' : 'text-textSecondary/40 hover:text-textPrimary'}`}
                aria-label={isRecording ? "Stop recording" : "Record voice input"}
              >
                {isRecording ? <Square size={14} /> : <Mic size={14} />}
              </button>
            </div>
          </div>
          <textarea
            id="daily-action"
            value={note}
            onChange={(e) => setNote(e.target.value.slice(0, 120))}
            maxLength={120}
            className="w-full bg-muted/30 border border-border p-4 text-sm text-textPrimary focus:outline-none focus:ring-1 focus:ring-accent min-h-[120px] resize-none transition-all placeholder:text-textSecondary/20"
            placeholder={isRecording ? "Listening..." : "Document reality..."}
          />
          <div className="flex justify-end">
            <span className="text-[9px] text-textSecondary/30 font-mono tracking-widest" aria-live="polite">
              {note.length}/120 characters
            </span>
          </div>
        </section>

        <section className="space-y-4">
          <h2 className="text-[10px] font-mono tracking-widest uppercase text-textSecondary">
            Alignment Verification
          </h2>
          <div className="space-y-2" role="group" aria-label="Anchors verification">
            {identity.anchors.map((anchor, i) => (
              <button
                key={i}
                onClick={() => toggleAnchor(i)}
                aria-pressed={anchorStatus[i]}
                className={`w-full text-left p-4 flex items-center justify-between border active-feedback ${
                  anchorStatus[i] 
                    ? 'border-accent bg-accent/10 text-textPrimary' 
                    : 'border-border bg-muted/20 text-textSecondary/40'
                } transition-all duration-300`}
              >
                <span className="text-[11px] uppercase tracking-widest">{anchor}</span>
                <div className={`w-3 h-3 border ${anchorStatus[i] ? 'bg-accent border-accent' : 'border-white/10'}`} aria-hidden="true" />
              </button>
            ))}
          </div>
        </section>

        <section className="space-y-6">
          <div className="flex justify-between items-end">
            <label htmlFor="time-slider" className="text-[10px] font-mono tracking-widest uppercase text-textSecondary">
              Time Spent
            </label>
            <span className="text-sm font-mono text-textPrimary" aria-live="polite">{time}{time >= 180 ? '+' : ''}m</span>
          </div>
          <input
            id="time-slider"
            type="range"
            min="0"
            max="180"
            step="15"
            value={time}
            onChange={(e) => setTime(parseInt(e.target.value))}
            className="w-full active-feedback"
            aria-valuemin={0}
            aria-valuemax={180}
            aria-valuenow={time}
            aria-valuetext={`${time} minutes`}
          />
        </section>

        <section className="space-y-4">
          <label htmlFor="mental-state" className="text-[10px] font-mono tracking-widest uppercase text-textSecondary">
            Mental State
          </label>
          <input
            id="mental-state"
            type="text"
            value={state}
            onChange={(e) => setState(e.target.value)}
            placeholder="Focused / Avoiding / Calm..."
            className="w-full bg-muted/30 border border-border p-4 text-sm text-textPrimary focus:outline-none focus:ring-1 focus:ring-accent transition-all placeholder:text-textSecondary/20"
          />
        </section>

        <section className="space-y-4">
          <h2 className="text-[10px] font-mono tracking-widest uppercase text-textSecondary">
            Energy Level
          </h2>
          <div className="grid grid-cols-3 gap-2" role="radiogroup" aria-label="Energy level selection">
            {(['LOW', 'MEDIUM', 'HIGH'] as EnergyLevel[]).map((level) => (
              <button
                key={level}
                role="radio"
                aria-checked={energy === level}
                onClick={() => setEnergy(level)}
                className={`py-4 text-[10px] font-mono tracking-widest transition-all active-feedback border ${
                  energy === level 
                    ? 'bg-accent text-textPrimary border-accent' 
                    : 'bg-muted/30 text-textSecondary/40 border-border'
                }`}
              >
                {level}
              </button>
            ))}
          </div>
        </section>

        <button
          onClick={handleSubmit}
          disabled={!note || !state}
          className="w-full bg-accent py-5 text-[11px] font-mono tracking-[0.5em] uppercase disabled:opacity-20 disabled:cursor-not-allowed transition-all active-feedback mt-4"
        >
          Submit Check-in
        </button>
      </div>
    </div>
  );
};

export default CheckIn;

import React, { useMemo } from 'react';
import { DailyLog, EnergyLevel } from '../types';
import { Download } from 'lucide-react';

interface Props {
  logs: DailyLog[];
}

const History: React.FC<Props> = ({ logs }) => {
  const handleExport = () => {
    const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(logs, null, 2));
    const downloadAnchorNode = document.createElement('a');
    downloadAnchorNode.setAttribute("href", dataStr);
    downloadAnchorNode.setAttribute("download", `noah_history_${new Date().toISOString().split('T')[0]}.json`);
    document.body.appendChild(downloadAnchorNode);
    downloadAnchorNode.click();
    downloadAnchorNode.remove();
  };

  const history = useMemo(() => {
    // Return last 7 logs, reversed to show most recent first
    return [...logs].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime()).slice(0, 7);
  }, [logs]);

  const stats = useMemo(() => {
    if (logs.length === 0) return null;
    const last7 = logs.slice(-7);
    const totalTime = last7.reduce((acc, curr) => acc + curr.timeSpent, 0);

    const energyMap: Record<EnergyLevel, number> = { 'LOW': 1, 'MEDIUM': 2, 'HIGH': 3 };
    const avgEnergyVal = last7.reduce((acc, curr) => acc + energyMap[curr.energy], 0) / last7.length;
    let avgEnergyLabel: EnergyLevel = 'MEDIUM';
    if (avgEnergyVal < 1.5) avgEnergyLabel = 'LOW';
    else if (avgEnergyVal > 2.5) avgEnergyLabel = 'HIGH';

    return {
      totalTime,
      avgEnergy: avgEnergyLabel,
      frequency: last7.length,
      isComplete: last7.length >= 7
    };
  }, [logs]);

  // SVG Trend Line Data
  const trendPoints = useMemo(() => {
    if (logs.length < 2) return "";
    const last7 = logs.slice(-7);
    const maxTime = Math.max(...last7.map(l => l.timeSpent), 180);
    const width = 300;
    const height = 40;
    const step = width / (last7.length - 1 || 1);

    return last7.map((l, i) => {
      const x = i * step;
      const y = height - (l.timeSpent / maxTime) * height;
      return `${x},${y}`;
    }).join(" ");
  }, [logs]);

  if (logs.length === 0) {
    return (
      <div className="flex-grow flex flex-col items-center justify-center text-center p-12 view-transition">
        <p className="text-[10px] font-mono tracking-widest uppercase text-textSecondary/50 max-w-[180px] leading-relaxed">
          No patterns yet. Reality starts today.
        </p>
      </div>
    );
  }

  const getIndicatorColor = (log: DailyLog) => {
    const completionRate = log.anchorsCompleted?.filter(Boolean).length || 0;
    // Aligned: High time and high completion
    if (completionRate >= 2 && log.timeSpent >= 60) return 'bg-textPrimary'; 
    // Unstable: Moderate time or moderate completion
    if (completionRate >= 1 || log.timeSpent >= 30) return 'bg-textSecondary/40'; 
    // Drifting: Low everything
    return 'bg-accent'; 
  };

  return (
    <div className="w-full space-y-12 view-transition pt-8 pb-12 animate-fade-in">
      <header className="flex justify-between items-end">
        <div className="space-y-1">
          <h1 className="text-xl font-bold tracking-[0.2em] uppercase text-textPrimary">History</h1>
          <p className="text-[10px] font-mono uppercase tracking-[0.3em] text-textSecondary/40">Last 7 Days</p>
        </div>
        <button 
          onClick={handleExport}
          className="flex items-center space-x-2 text-[9px] font-mono tracking-widest uppercase text-textSecondary/30 hover:text-textSecondary transition-colors active-feedback group"
          aria-label="Export history as JSON"
        >
          <Download size={10} className="group-hover:text-textPrimary transition-colors" />
          <span>Export Data</span>
        </button>
      </header>

      {/* Weekly Summary */}
      {stats && (
        <section className="noah-card p-6 space-y-8 border-white/5 bg-muted/10 relative overflow-hidden">
          {!stats.isComplete && (
            <div className="absolute top-2 right-4">
              <span className="text-[7px] font-mono uppercase tracking-[0.2em] text-textSecondary/20">Partial Data</span>
            </div>
          )}

          <div className="grid grid-cols-3 gap-4">
            <div className="space-y-1">
              <span className="text-[8px] font-mono uppercase tracking-widest text-textSecondary/40">Total Time</span>
              <p className="text-sm font-mono text-textPrimary">{stats.totalTime}m</p>
            </div>
            <div className="space-y-1">
              <span className="text-[8px] font-mono uppercase tracking-widest text-textSecondary/40">Avg Energy</span>
              <p className="text-sm font-mono text-textPrimary">{stats.avgEnergy}</p>
            </div>
            <div className="space-y-1">
              <span className="text-[8px] font-mono uppercase tracking-widest text-textSecondary/40">Frequency</span>
              <p className="text-sm font-mono text-textPrimary">{stats.frequency}/7 days</p>
            </div>
          </div>

          {/* Trend Line SVG */}
          {trendPoints && (
            <div className="pt-6 border-t border-white/5">
               <svg className="w-full h-10 overflow-visible" viewBox="0 0 300 40" preserveAspectRatio="none" aria-hidden="true">
                <polyline
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="1.5"
                  className="text-accent/60"
                  points={trendPoints}
                  strokeLinecap="round"
                  strokeLinejoin="round"
                />
              </svg>
              <div className="flex justify-between mt-3">
                <span className="text-[7px] font-mono uppercase tracking-widest text-textSecondary/20">7d ago</span>
                <span className="text-[7px] font-mono uppercase tracking-widest text-textSecondary/20">Today</span>
              </div>
            </div>
          )}
        </section>
      )}

      {/* Detailed List */}
      <div className="space-y-6" role="list" aria-label="Daily logs history list">
        {history.map((log, idx) => {
          const date = new Date(log.date);
          const formattedDate = date.toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' }).toUpperCase();

          return (
            <div key={idx} role="listitem" className="flex items-center justify-between group border-b border-white/5 pb-4 last:border-0 hover:bg-white/[0.01] transition-colors rounded-sm px-1">
              <div className="flex flex-col">
                <span className="text-[10px] font-mono tracking-[0.15em] text-textSecondary/80 group-hover:text-textPrimary transition-colors">
                  {formattedDate}
                </span>
                <div className="flex items-center space-x-2 mt-1">
                  <span className="text-[9px] font-mono text-textSecondary/20">
                    {log.timeSpent}m
                  </span>
                  <span className="text-[9px] font-mono text-textSecondary/20">•</span>
                  <span className="text-[9px] font-mono text-textSecondary/20 uppercase tracking-tighter">
                    {log.state}
                  </span>
                </div>
              </div>

              <div 
                className={`w-2.5 h-2.5 rounded-sm ${getIndicatorColor(log)} transition-all duration-700 shadow-sm`} 
                role="img"
                aria-label={`Alignment indicator for ${formattedDate}`}
              />
            </div>
          );
        })}
      </div>

      {/* Legend */}
      <div className="pt-16 space-y-4 border-t border-white/5">
        <h4 className="text-[8px] font-mono tracking-[0.4em] uppercase text-textSecondary/20">Indicator Meaning</h4>
        <div className="flex flex-wrap gap-x-8 gap-y-4">
          <div className="flex items-center space-x-3">
            <div className="w-2 h-2 rounded-sm bg-textPrimary" />
            <span className="text-[9px] font-mono tracking-widest uppercase text-textSecondary/40">Aligned</span>
          </div>
          <div className="flex items-center space-x-3">
            <div className="w-2 h-2 rounded-sm bg-textSecondary/40" />
            <span className="text-[9px] font-mono tracking-widest uppercase text-textSecondary/40">Unstable</span>
          </div>
          <div className="flex items-center space-x-3">
            <div className="w-2 h-2 rounded-sm bg-accent" />
            <span className="text-[9px] font-mono tracking-widest uppercase text-textSecondary/40">Drifting</span>
          </div>
        </div>
      </div>
    </div>
  );
};

export default History;

import React, { useState } from 'react';

interface Props {
  onSuccess: (email: string) => void;
  onSkip: () => void;
}

const Auth: React.FC<Props> = ({ onSuccess, onSkip }) => {
