import { DailyLog, UserIdentity, AlignmentStatus, EnergyLevel } from '../types';

export interface SignalVector {
  time: number[];
  energy: number[];
  alignment: number[];
  combined: number[];
}

export interface DriftAnalysis {
  coefficient: number; // 0 (perfect) to 1 (critical drift)
  momentum: number;    // negative is downward trajectory
  entropy: number;     // variance/instability
  prediction: number;  // days until critical collapse
  state: AlignmentStatus;
}

/**
 * NOAH Core: Deterministic Signal Processing Engine
 * Zero AI/ML logic. Pure statistical derivation.
 */
export const noahCore = {
  /**
   * Normalizes raw behavioral logs into numerical signals
   */
  processSignals(logs: DailyLog[]): SignalVector {
    const energyMap: Record<EnergyLevel, number> = { 'LOW': 0.1, 'MEDIUM': 0.5, 'HIGH': 1.0 };

    // Last 7 days or total if less
    const window = logs.slice(-7);

    const time = window.map(l => Math.min(l.timeSpent / 180, 1.0));
    const energy = window.map(l => energyMap[l.energy]);
    const alignment = window.map(l => {
      if (!l.anchorsCompleted) return 0;
      return l.anchorsCompleted.filter(Boolean).length / (l.anchorsCompleted.length || 1);
    });

    const combined = time.map((t, i) => (t * 0.4) + (energy[i] * 0.2) + (alignment[i] * 0.4));

    return { time, energy, alignment, combined };
  },

  /**
   * Calculates linear regression slope (momentum)
   */
  calculateMomentum(values: number[]): number {
    if (values.length < 2) return 0;
    const n = values.length;
    let sumX = 0, sumY = 0, sumXY = 0, sumXX = 0;
    for (let i = 0; i < n; i++) {
      sumX += i;
      sumY += values[i];
      sumXY += i * values[i];
      sumXX += i * i;
    }
    return (n * sumXY - sumX * sumY) / (n * sumXX - sumX * sumX);
  },

  /**
   * Calculates standard deviation (entropy)
   */
  calculateEntropy(values: number[]): number {
    if (values.length < 2) return 0;
    const mean = values.reduce((a, b) => a + b) / values.length;
    const variance = values.reduce((a, b) => a + Math.pow(b - mean, 2), 0) / values.length;
    return Math.sqrt(variance);
  },

  /**
   * Pure deterministic analysis engine
   */
  analyzeTrajectory(logs: DailyLog[], identity: UserIdentity): DriftAnalysis {
    if (logs.length === 0) {
      return { coefficient: 0, momentum: 0, entropy: 0, prediction: 30, state: 'UNSTABLE' };
    }

    const signals = this.processSignals(logs);
    const momentum = this.calculateMomentum(signals.combined);
    const entropy = this.calculateEntropy(signals.combined);
    const average = signals.combined.reduce((a, b) => a + b) / signals.combined.length;

    // Coefficient: higher is worse drift
    // Inversely proportional to average, weighted by entropy and downward momentum
    const coefficient = Math.max(0, Math.min(1.0, (1.0 - average) + (entropy * 0.5) - (momentum > 0 ? momentum : 0)));

    // Predict collapse: solve for combined = 0 using y = mx + b
    // b = last average
    const lastAvg = signals.combined[signals.combined.length - 1];
    let prediction = 30;
    if (momentum < 0) {
      prediction = Math.floor(Math.abs(lastAvg / momentum));
    }

    // Classification Logic (Deterministic)
    let state: AlignmentStatus = 'UNSTABLE';
    if (average > 0.75 && entropy < 0.15 && momentum >= -0.05) {
      state = 'ALIGNED';
    } else if (momentum < -0.1 || average < 0.4) {
      state = 'DRIFTING';
    }

    return { coefficient, momentum, entropy, prediction, state };
  }
};

