export type DriftState = 'stable' | 'fragile' | 'drift' | 'critical';
export type RiskLevel = 'low' | 'medium' | 'high';

export interface SignalMetrics {
  avg: number;
  negCount: number;
  variance: number;
}

export interface WindowAnalysis {
  recent: SignalMetrics;
  previous: SignalMetrics;
  delta: number;
  dominantCategory: 'Time' | 'Energy' | 'Alignment' | 'None';
  repetitionCount: number;
}

export interface NoahResult {
  driftScore: number;
  state: DriftState;
  confidence: number;
  projections: {
    '7d': RiskLevel;
    '14d': RiskLevel;
    '30d': RiskLevel;
  };
  explanation: string;
  rawSignals: number[];
}

import { DailyLog, EnergyLevel } from '../types';
import { SignalMetrics, WindowAnalysis } from './types';

const energyValue: Record<EnergyLevel, number> = { 'LOW': 0.1, 'MEDIUM': 0.5, 'HIGH': 1.0 };
const NEGATIVE_THRESHOLD = 0.4;

function calculateMetrics(logs: DailyLog[]): SignalMetrics {
  if (logs.length === 0) return { avg: 0, negCount: 0, variance: 0 };

  const values = logs.map(l => {
    const time = Math.min(l.timeSpent / 180, 1.0);
    const energy = energyValue[l.energy];
    const alignment = l.anchorsCompleted ? l.anchorsCompleted.filter(Boolean).length / (l.anchorsCompleted.length || 1) : 0;
    return (time * 0.4) + (energy * 0.2) + (alignment * 0.4);
  });

  const avg = values.reduce((a, b) => a + b, 0) / values.length;
  const negCount = values.filter(v => v < NEGATIVE_THRESHOLD).length;
  const variance = values.length < 2 ? 0 : values.reduce((acc, v) => acc + Math.pow(v - avg, 2), 0) / values.length;

  return { avg, negCount, variance };
}

export const signalAnalyzer = {
  analyze(logs: DailyLog[]): WindowAnalysis {
    // Split into last 7 days and days 8-14
    const sorted = [...logs].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    const windowRecent = sorted.slice(0, 7);
    const windowPrevious = sorted.slice(7, 14);

    const recent = calculateMetrics(windowRecent);
    const previous = calculateMetrics(windowPrevious);
    const delta = recent.avg - previous.avg;

    // Detect dominant negative category in recent window
    let dominantCategory: 'Time' | 'Energy' | 'Alignment' | 'None' = 'None';
    let maxNeg = 0;

    if (windowRecent.length > 0) {
      const timeNeg = windowRecent.filter(l => l.timeSpent < 30).length;
      const energyNeg = windowRecent.filter(l => l.energy === 'LOW').length;
      const alignNeg = windowRecent.filter(l => (l.anchorsCompleted?.filter(Boolean).length || 0) === 0).length;

      maxNeg = Math.max(timeNeg, energyNeg, alignNeg);
      if (maxNeg > 0) {
        if (maxNeg === timeNeg) dominantCategory = 'Time';
        else if (maxNeg === energyNeg) dominantCategory = 'Energy';
        else dominantCategory = 'Alignment';
      }
    }

    return {
      recent,
      previous,
      delta,
      dominantCategory,
      repetitionCount: maxNeg
    };
  }
};

import { WindowAnalysis } from './types';

export const driftDetector = {
  detect(analysis: WindowAnalysis): number {
    let score = 0;

    // 1. Negative trend delta -> +2
    if (analysis.delta < -0.1) {
      score += 2;
    }

    // 2. Repeated negative signals (>=3 same category) -> +2
    if (analysis.repetitionCount >= 3) {
      score += 2;
    }

    // 3. High instability -> +1
    if (analysis.recent.variance > 0.15) {
      score += 1;
    }

    return score;
  }
};

import { DriftState } from './types';

export const stateClassifier = {
  classify(score: number): { state: DriftState, confidence: number } {
    let state: DriftState = 'stable';
    if (score >= 4) state = 'critical';
    else if (score === 3) state = 'drift';
    else if (score === 2) state = 'fragile';
    else state = 'stable';

    // Confidence derived from data density (pseudo-confidence)
    // 100 base, reduced by high instability
    const confidence = Math.max(40, 95 - (score * 5));

    return { state, confidence };
  }
};

import { DriftState, RiskLevel } from './types';

const riskTable: Record<DriftState, { '7d': RiskLevel, '14d': RiskLevel, '30d': RiskLevel }> = {
  stable: { '7d': 'low', '14d': 'low', '30d': 'low' },
  fragile: { '7d': 'medium', '14d': 'medium', '30d': 'high' },
  drift: { '7d': 'medium', '14d': 'high', '30d': 'high' },
  critical: { '7d': 'high', '14d': 'high', '30d': 'high' }
};

export const predictor = {
  predict(state: DriftState) {
    return riskTable[state];
  }
};

import { WindowAnalysis, DriftState } from './types';

export const explanationBuilder = {
  build(analysis: WindowAnalysis, state: DriftState): string {
    if (analysis.dominantCategory === 'None') {
      return "No significant signal deviation detected within the observation window.";
    }

    const trend = analysis.delta < 0 ? "deteriorating" : "stable";
    const repetition = analysis.repetitionCount >= 3 ? "repeated" : "sporadic";

    return `${analysis.dominantCategory} signals show ${repetition} patterns with a ${trend} delta across temporal windows.`;
  }
};

import { DailyLog } from '../types';
import { NoahResult } from './types';
import { signalAnalyzer } from './signalAnalyzer';
import { driftDetector } from './driftDetector';
import { stateClassifier } from './stateClassifier';
import { predictor } from './predictor';
import { explanationBuilder } from './explanationBuilder';

export const noahCoreEngine = {
  process(logs: DailyLog[]): NoahResult {
    // 1. Signals -> Signal Analyzer
    const analysis = signalAnalyzer.analyze(logs);

    // 2. Signal Analyzer -> Drift Detector
    const driftScore = driftDetector.detect(analysis);

    // 3. Drift Detector -> State Classifier
    const { state, confidence } = stateClassifier.classify(driftScore);

    // 4. State Classifier -> Predictor
    const projections = predictor.predict(state);

    // 5. Predictor -> Explanation Builder
    const explanation = explanationBuilder.build(analysis, state);

    // 6. Return NoahResult
    return {
      driftScore,
      state,
      confidence,
      projections,
      explanation,
      rawSignals: logs.slice(-7).map(l => l.timeSpent / 180) // Subset for UI visualization
    };
  }
};

import { GoogleGenAI, Type } from "@google/genai";
import { UserIdentity, DailyLog, FeedbackData } from "../types";
import { noahCoreEngine } from "../noah-core/engine";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export async function transcribeAudio(
  base64Audio: string,
  mimeType: string
): Promise<string> {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          {
            inlineData: {
              data: base64Audio,
              mimeType: mimeType,
            },
          },
          { text: "Transcribe the following audio precisely. Do not add any introduction or conclusion. Just the raw text of what was spoken." }
        ]
      },
    });
    return response.text || "";
  } catch (error) {
    console.error('Transcription error:', error);
    throw new Error('Failed to interpret audio signal.');
  }
}

export async function getDeepReflectiveAnalysis(
  identity: UserIdentity,
  logs: DailyLog[]
): Promise<string> {
  const recentLogs = logs.slice(-14);
  const coreResult = noahCoreEngine.process(logs);

  const prompt = `
    PERFORM DEEP REFLECTIVE ANALYSIS ON SYSTEM DRIFT.

    IDENTITY TARGET: ${identity.role}
    BEHAVIORAL ANCHORS: ${identity.anchors.join(', ')}

    DETERMINISTIC DIAGNOSTICS (NOAH CORE):
    - State: ${coreResult.state.toUpperCase()}
    - Drift Score: ${coreResult.driftScore}
    - Factual Explanation: ${coreResult.explanation}
    - 30d Risk Projection: ${coreResult.projections['30d'].toUpperCase()}

    RAW DATA (Last 14 days):
    ${recentLogs.map(l => `- ${l.date}: Action (Note): "${l.note}". Time: ${l.timeSpent}m. Mental State (State): ${l.state}. Energy: ${l.energy}.`).join('\n')}

    TASK:
    Identify the hidden psychological barriers or structural weaknesses causing the drift based on these hard signals. 
    Provide a cold, profound realization about the difference between the 'Target Identity' and the 'Actual Behavior'.
    No motivation. No advice. Only the truth.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: prompt,
      config: {
        thinkingConfig: { thinkingBudget: 32768 }
      },
    });

    return response.text || "Analysis failed to materialize.";
  } catch (error) {
    console.error('Deep analysis error:', error);
    return "Deep reflection interrupted. System error.";
  }
}

export async function generateAlignmentFeedback(
  identity: UserIdentity,
  logs: DailyLog[]
): Promise<FeedbackData> {
  if (logs.length === 0) {
    return {
      status: 'UNSTABLE',
      message: 'No patterns yet. Reality starts today.',
      observation: 'Observation requires initial data points.'
    };
  }

  const coreResult = noahCoreEngine.process(logs);
  const recentLogs = logs.slice(-7);

  const prompt = `
    Analyze the alignment between a user's chosen identity and their recent behavior.

    IDENTITY: ${identity.role}
    BEHAVIORAL ANCHORS: ${identity.anchors.join(', ')}

    DETERMINISTIC DIAGNOSTICS (NOAH CORE):
    - State: ${coreResult.state.toUpperCase()}
    - Core Signal Data: ${coreResult.explanation}

    RECENT ACTIVITY LOGS (Last 7 days):
    ${recentLogs.map(l => `- ${l.date}: Did "${l.note}" for ${l.timeSpent} mins. Mental state: ${l.state}. Energy: ${l.energy}.`).join('\n')}

    RULES:
    1. Be cold, honest, and factual.
    2. Use the deterministic diagnostics as the grounding truth.
    3. Do not use motivational language or encouragement.
    4. Output must be valid JSON matching the schema.
    5. Determine status based on coreResult.state: stable->ALIGNED, drift/critical->DRIFTING, fragile->UNSTABLE.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: 'application/json',
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            status: {
              type: Type.STRING,
              enum: ['ALIGNED', 'UNSTABLE', 'DRIFTING']
            },
            message: {
              type: Type.STRING
            },
            observation: {
              type: Type.STRING
            }
          },
          required: ['status', 'message', 'observation']
        }
      }
    });

    const result = JSON.parse(response.text || '{}');
    return {
      status: result.status || 'UNSTABLE',
      message: result.message || 'Patterns require more clarity.',
      observation: result.observation || coreResult.explanation
    };
  } catch (error) {
    console.error('Gemini error:', error);
    return {
      status: 'UNSTABLE',
      message: 'Connection to logic systems interrupted.',
      observation: coreResult.explanation
    };
  }
}

import React, { useState, useEffect, useRef } from 'react';
import { UserIdentity, DailyLog, FeedbackData, AlignmentStatus } from '../types';
import { generateAlignmentFeedback, getDeepReflectiveAnalysis } from '../services/geminiService';
import { noahCoreEngine } from '../noah-core/engine';
import { NoahResult } from '../noah-core/types';
import { store } from '../store';
import { motion, AnimatePresence } from 'framer-motion';
import { BrainCircuit, X, Activity, ShieldAlert } from 'lucide-react';

interface Props {
  identity: UserIdentity;
  logs: DailyLog[];
  onCycleReset?: () => void;
}

const Feedback: React.FC<Props> = ({ identity, logs, onCycleReset }) => {
  const [data, setData] = useState<FeedbackData | null>(null);
  const [coreResult, setCoreResult] = useState<NoahResult | null>(null);
  const [loading, setLoading] = useState(true);
  const [showStatusOverlay, setShowStatusOverlay] = useState(false);
  const prevStatusRef = useRef<AlignmentStatus | null>(null);

  const [deepAnalysis, setDeepAnalysis] = useState<string | null>(null);
  const [isAnalyzingDeeply, setIsAnalyzingDeeply] = useState(false);
  const [showDeepModal, setShowDeepModal] = useState(false);

  useEffect(() => {
    const lastFeedback = store.getLastFeedback();
    if (lastFeedback) {
      prevStatusRef.current = lastFeedback.status;
    }

    async function fetchTruth() {
      setLoading(true);

      const core = noahCoreEngine.process(logs);
      setCoreResult(core);

      const result = await generateAlignmentFeedback(identity, logs);

      if (prevStatusRef.current && prevStatusRef.current !== result.status) {
        setShowStatusOverlay(true);
        setTimeout(() => setShowStatusOverlay(false), 300);
      }

      setData(result);
      store.saveFeedback(result);
      setLoading(false);
    }
    fetchTruth();
  }, [identity, logs]);

  const handleDeepReflection = async () => {
    setShowDeepModal(true);
    if (!deepAnalysis) {
      setIsAnalyzingDeeply(true);
      const analysis = await getDeepReflectiveAnalysis(identity, logs);
      setDeepAnalysis(analysis);
      setIsAnalyzingDeeply(false);
    }
  };

  if (loading) {
    return (
      <div className="flex-grow flex flex-col items-center justify-center space-y-6">
        <motion.div 
          animate={{ opacity: [0.1, 0.4, 0.1] }}
          transition={{ repeat: Infinity, duration: 2 }}
          className="w-12 h-[1px] bg-textPrimary" 
        />
        <p className="text-[10px] font-mono tracking-[0.5em] uppercase text-textSecondary opacity-40">
          Syncing core engine...
        </p>
      </div>
    );
  }

  if (!data || !coreResult) return null;

  const getStatusStyle = (status: AlignmentStatus) => {
    switch (status) {
      case 'ALIGNED': return { color: 'text-textPrimary', animation: '' };
      case 'UNSTABLE': return { color: 'text-textSecondary', animation: '' };
      case 'DRIFTING': return { color: 'text-accent', animation: 'animate-pulse-drift' };
      default: return { color: 'text-textSecondary', animation: '' };
    }
  };

  const style = getStatusStyle(data.status);

  return (
    <div className="flex-grow flex flex-col items-center py-8 text-center px-4 relative overflow-y-auto no-scrollbar">
      <AnimatePresence>
        {showStatusOverlay && (
          <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 bg-bgMain z-[100] flex items-center justify-center pointer-events-none">
            <span className="text-[11px] font-mono tracking-[0.5em] uppercase text-textPrimary">Trajectory shift.</span>
          </motion.div>
        )}
      </AnimatePresence>

      <AnimatePresence>
        {showDeepModal && (
          <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 bg-bgMain/95 z-[200] flex items-center justify-center p-8 backdrop-blur-md overflow-y-auto" role="dialog" aria-modal="true">
            <div className="max-w-xs w-full space-y-8 py-12">
              <div className="flex justify-between items-center">
                <span className="text-[10px] font-mono tracking-[0.5em] uppercase text-accent">Deep Thinking Mode</span>
                <button onClick={() => setShowDeepModal(false)} className="text-textSecondary/40 hover:text-textPrimary transition-colors active-feedback">
                  <X size={18} />
                </button>
              </div>
              <div className="noah-card p-6 border-accent/20 bg-muted/10 min-h-[300px] flex flex-col justify-center">
                {isAnalyzingDeeply ? (
                  <div className="space-y-6 text-center">
                     <motion.div animate={{ opacity: [0.1, 1, 0.1], scale: [0.95, 1, 0.95] }} transition={{ repeat: Infinity, duration: 3 }} className="flex justify-center">
                      <BrainCircuit size={32} className="text-accent" />
                    </motion.div>
                    <p className="text-[10px] font-mono tracking-[0.3em] uppercase text-textSecondary/40 animate-pulse">Consulting deeper mirrors...</p>
                  </div>
                ) : (
                  <motion.p initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="text-sm font-light leading-relaxed text-textPrimary text-left whitespace-pre-wrap">
                    {deepAnalysis}
                  </motion.p>
                )}
              </div>
              <p className="text-[9px] font-mono tracking-widest uppercase text-textSecondary/20 text-center">Thinking enabled by Gemini 3 Pro</p>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      <div className="space-y-2 mb-8">
        <span className="text-[9px] font-mono tracking-[0.4em] uppercase text-textSecondary/30">Target Identity</span>
        <p className="text-xs font-medium tracking-widest text-textSecondary/60 uppercase">{identity.role}</p>
      </div>

      <div className="space-y-4 mb-10">
        <motion.h2 className={`text-6xl font-bold tracking-[0.1em] font-mono transition-colors duration-1000 ${style.color} ${style.animation}`}>
          {data.status}
        </motion.h2>
      </div>

      <div className="w-full max-w-xs space-y-8">
        {/* NOAH CORE DETERMINISTIC DATA */}
        <div className="noah-card p-5 border-white/5 bg-muted/5 space-y-6 text-left">
          <div className="flex items-center space-x-2 opacity-40">
            <Activity size={10} />
            <span className="text-[8px] font-mono tracking-widest uppercase">Signal Diagnostics [NOAH-CORE]</span>
          </div>
          <div className="grid grid-cols-2 gap-y-4">
            <div className="space-y-1">
              <span className="text-[7px] font-mono uppercase text-textSecondary/40 tracking-wider">State Confidence</span>
              <p className="text-xs font-mono text-textPrimary">{coreResult.confidence}%</p>
            </div>
            <div className="space-y-1">
              <span className="text-[7px] font-mono uppercase text-textSecondary/40 tracking-wider">Drift Score</span>
              <p className="text-xs font-mono text-textPrimary">{coreResult.driftScore}</p>
            </div>
          </div>
          <div className="pt-4 border-t border-white/5 space-y-3">
             <div className="flex items-center space-x-2 opacity-40">
              <ShieldAlert size={10} />
              <span className="text-[8px] font-mono tracking-widest uppercase">Risk Projections</span>
            </div>
            <div className="flex justify-between">
              <div className="text-center">
                <span className="text-[7px] font-mono text-textSecondary/30 block mb-1">7D</span>
                <span className={`text-[8px] font-mono uppercase ${coreResult.projections['7d'] === 'high' ? 'text-accent' : 'text-textPrimary/40'}`}>{coreResult.projections['7d']}</span>
              </div>
              <div className="text-center">
                <span className="text-[7px] font-mono text-textSecondary/30 block mb-1">14D</span>
                <span className={`text-[8px] font-mono uppercase ${coreResult.projections['14d'] === 'high' ? 'text-accent' : 'text-textPrimary/40'}`}>{coreResult.projections['14d']}</span>
              </div>
              <div className="text-center">
                <span className="text-[7px] font-mono text-textSecondary/30 block mb-1">30D</span>
                <span className={`text-[8px] font-mono uppercase ${coreResult.projections['30d'] === 'high' ? 'text-accent' : 'text-textPrimary/40'}`}>{coreResult.projections['30d']}</span>
              </div>
            </div>
          </div>
        </div>

        <div className="noah-card p-6 border-white/5 bg-muted/20 text-left">
          <p className="text-sm font-light leading-relaxed text-textPrimary/80">
            {data.message}
          </p>
