export default IdentitySetup;

export type DriftState = 'stable' | 'fragile' | 'drift' | 'critical';
export type RiskLevel = 'low' | 'medium' | 'high';

export interface SignalMetrics {
  avg: number;
  negCount: number;
  variance: number;
  authenticity: number; // Correlation between anchors and time
}

export interface WindowAnalysis {
  recent: SignalMetrics;
  previous: SignalMetrics;
  delta: number;
  volatility: number; // Rate of change in signal
  dominantCategory: 'Time' | 'Energy' | 'Alignment' | 'None';
  repetitionCount: number;
}

export interface NoahResult {
  driftScore: number;
  state: DriftState;
  confidence: number;
  projections: {
    '7d': RiskLevel;
    '14d': RiskLevel;
    '30d': RiskLevel;
  };
  explanation: string;
  rawSignals: number[];
  meta: {
    authenticity: number;
    volatility: number;
  };
}

import { DailyLog, EnergyLevel } from '../types';
import { SignalMetrics, WindowAnalysis } from './types';

const energyValue: Record<EnergyLevel, number> = { 'LOW': 0.1, 'MEDIUM': 0.5, 'HIGH': 1.0 };
const NEGATIVE_THRESHOLD = 0.4;

function calculateMetrics(logs: DailyLog[]): SignalMetrics {
  if (logs.length === 0) return { avg: 0, negCount: 0, variance: 0, authenticity: 1 };

  const values = logs.map(l => {
    const time = Math.min(l.timeSpent / 180, 1.0);
    const energy = energyValue[l.energy];
    const anchorRatio = l.anchorsCompleted ? l.anchorsCompleted.filter(Boolean).length / (l.anchorsCompleted.length || 1) : 0;

    // Core signal formula: Weighted towards Anchors (40%) and Time (40%)
    return (time * 0.4) + (energy * 0.2) + (anchorRatio * 0.4);
  });

  // Calculate Authenticity: Do the anchors match the time spent?
  // High time + Low anchors = Low Authenticity (Potential self-deception)
  const authenticityScores = logs.map(l => {
    const time = Math.min(l.timeSpent / 180, 1.0);
    const anchorRatio = l.anchorsCompleted ? l.anchorsCompleted.filter(Boolean).length / (l.anchorsCompleted.length || 1) : 0;
    if (time > 0.5 && anchorRatio < 0.3) return 0.5; // Disconnect
    return 1.0;
  });

  const avg = values.reduce((a, b) => a + b, 0) / values.length;
  const negCount = values.filter(v => v < NEGATIVE_THRESHOLD).length;
  const variance = values.length < 2 ? 0 : values.reduce((acc, v) => acc + Math.pow(v - avg, 2), 0) / values.length;
  const authenticity = authenticityScores.reduce((a, b) => a + b, 0) / authenticityScores.length;

  return { avg, negCount, variance, authenticity };
}

export const signalAnalyzer = {
  analyze(logs: DailyLog[]): WindowAnalysis {
    const sorted = [...logs].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    const windowRecent = sorted.slice(0, 7);
    const windowPrevious = sorted.slice(7, 14);

    const recent = calculateMetrics(windowRecent);
    const previous = calculateMetrics(windowPrevious);

    const delta = recent.avg - previous.avg;
    const volatility = Math.abs(recent.avg - previous.avg) + (recent.variance * 2);

    let dominantCategory: 'Time' | 'Energy' | 'Alignment' | 'None' = 'None';
    let maxNeg = 0;

    if (windowRecent.length > 0) {
      const timeNeg = windowRecent.filter(l => l.timeSpent < 45).length;
      const energyNeg = windowRecent.filter(l => l.energy === 'LOW').length;
      const alignNeg = windowRecent.filter(l => (l.anchorsCompleted?.filter(Boolean).length || 0) === 0).length;

      maxNeg = Math.max(timeNeg, energyNeg, alignNeg);
      if (maxNeg > 0) {
        if (maxNeg === timeNeg) dominantCategory = 'Time';
        else if (maxNeg === energyNeg) dominantCategory = 'Energy';
        else dominantCategory = 'Alignment';
      }
    }

    return {
      recent,
      previous,
      delta,
      volatility,
      dominantCategory,
      repetitionCount: maxNeg
    };
  }
};

import { WindowAnalysis, DriftState } from './types';

export const explanationBuilder = {
  build(analysis: WindowAnalysis, state: DriftState): string {
    if (analysis.dominantCategory === 'None' && analysis.recent.avg > 0.7) {
      return "Operational stability detected. Identity signals are congruent across all measured metrics.";
    }

    const segments = [];

    // Authenticity Check
    if (analysis.recent.authenticity < 0.8) {
      segments.push("Measurement disconnect: Time spent does not correlate with behavioral anchor completion.");
    }

    // Volatility Check
    if (analysis.volatility > 0.4) {
      segments.push("High trajectory volatility: Signal variance suggests unsustainable effort patterns.");
    }

    // Category Specifics
    if (analysis.dominantCategory !== 'None') {
      const trend = analysis.delta < 0 ? "deteriorating" : "stagnant";
      segments.push(`${analysis.dominantCategory} metrics are ${trend} (Negative frequency: ${analysis.repetitionCount}/7).`);
    }

    return segments.length > 0 
      ? segments.join(" ") 
      : "Insufficient signal density for deep diagnostic explanation.";
  }
};

import { DailyLog } from '../types';
import { NoahResult } from './types';
import { signalAnalyzer } from './signalAnalyzer';
import { driftDetector } from './driftDetector';
import { stateClassifier } from './stateClassifier';
import { predictor } from './predictor';
import { explanationBuilder } from './explanationBuilder';

export const noahCoreEngine = {
  process(logs: DailyLog[]): NoahResult {
    // 1. Signals -> Signal Analyzer
    const analysis = signalAnalyzer.analyze(logs);

    // 2. Signal Analyzer -> Drift Detector
    const driftScore = driftDetector.detect(analysis);

    // 3. Drift Detector -> State Classifier
    const { state, confidence } = stateClassifier.classify(driftScore);

    // 4. State Classifier -> Predictor
    const projections = predictor.predict(state);

    // 5. Predictor -> Explanation Builder
    const explanation = explanationBuilder.build(analysis, state);

    // 6. Return NoahResult with metadata
    return {
      driftScore,
      state,
      confidence,
      projections,
      explanation,
      rawSignals: logs.slice(-7).map(l => {
        const time = Math.min(l.timeSpent / 180, 1.0);
        const anchorRatio = l.anchorsCompleted ? l.anchorsCompleted.filter(Boolean).length / (l.anchorsCompleted.length || 1) : 0;
        return (time + anchorRatio) / 2;
      }),
      meta: {
        authenticity: analysis.recent.authenticity,
        volatility: analysis.volatility
      }
    };
  }
};

import React, { useState, useMemo, useRef } from 'react';
import { DailyLog, EnergyLevel, UserIdentity } from '../types';
import { ChevronDown, AlertCircle, Mic, Square, Loader2, Info } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { transcribeAudio } from '../services/geminiService';

interface Props {
  identity: UserIdentity;
  logs: DailyLog[];
  onComplete: (log: DailyLog) => void;
}

const CheckIn: React.FC<Props> = ({ identity, logs, onComplete }) => {
  const [note, setNote] = useState('');
  const [time, setTime] = useState(60);
  const [state, setState] = useState('');
  const [energy, setEnergy] = useState<EnergyLevel>('MEDIUM');
  const [anchorStatus, setAnchorStatus] = useState<boolean[]>(new Array(identity.anchors.length).fill(false));
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [showAnchors, setShowAnchors] = useState(false);

  const [isRecording, setIsRecording] = useState(false);
  const [isTranscribing, setIsTranscribing] = useState(false);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioChunksRef = useRef<Blob[]>([]);

  // Coherency Logic
  const trimmedNote = note.trim();
  const trimmedState = state.trim();
  const anchorsChecked = anchorStatus.filter(Boolean).length;

  const isNoteValid = trimmedNote.length >= 3 && trimmedNote.length <= 120;
  const isStateValid = trimmedState.length >= 2;

  // Logical Coherency: Prevent "Time/Anchor" disconnect
  const isCoherent = useMemo(() => {
    if (time === 0 && anchorsChecked > 0) return false; // Can't finish anchors in 0 mins
    if (time > 120 && anchorsChecked === 0 && trimmedNote.length < 10) return false; // Logging 2h+ but nothing to show for it
    return true;
  }, [time, anchorsChecked, trimmedNote]);

  const isFormValid = isNoteValid && isStateValid && isCoherent;

  // Constants & Calculations
  const today = new Date();
  const todayStr = today.toLocaleDateString('en-US', {
    month: 'short',
    day: 'numeric',
    year: 'numeric'
  }).toUpperCase();

  const dayOfCycle = useMemo(() => {
    const start = new Date(identity.created_at).getTime();
    const diff = Math.floor((today.getTime() - start) / (1000 * 60 * 60 * 24));
    return Math.min(diff + 1, 30);
  }, [identity.created_at]);

  const { continuity, showWarning } = useMemo(() => {
    if (logs.length === 0) return { continuity: 0, showWarning: false };
    const sortedLogs = [...logs].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    const lastLogDate = new Date(sortedLogs[0].date);
    lastLogDate.setHours(0,0,0,0);
    const midnightToday = new Date();
    midnightToday.setHours(0,0,0,0);
    const diffDays = Math.floor((midnightToday.getTime() - lastLogDate.getTime()) / (1000 * 60 * 60 * 24));
    let count = 0;
    let checkDate = new Date(midnightToday);
    if (diffDays > 0) checkDate.setDate(checkDate.getDate() - 1);
    const logDates = new Set(logs.map(l => {
      const d = new Date(l.date);
      d.setHours(0,0,0,0);
      return d.getTime();
    }));
    while (logDates.has(checkDate.getTime())) {
      count++;
      checkDate.setDate(checkDate.getDate() - 1);
    }
    return { continuity: count, showWarning: diffDays >= 2 };
  }, [logs]);

  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const mediaRecorder = new MediaRecorder(stream);
      mediaRecorderRef.current = mediaRecorder;
      audioChunksRef.current = [];
      mediaRecorder.ondataavailable = (event) => audioChunksRef.current.push(event.data);
      mediaRecorder.onstop = async () => {
        const audioBlob = new Blob(audioChunksRef.current, { type: 'audio/webm' });
        const reader = new FileReader();
        reader.readAsDataURL(audioBlob);
        reader.onloadend = async () => {
          const base64Data = (reader.result as string).split(',')[1];
          setIsTranscribing(true);
          try {
            const text = await transcribeAudio(base64Data, 'audio/webm');
            setNote((prev) => (prev + ' ' + text).trim().slice(0, 120));
          } catch (error) {
            console.error(error);
          } finally {
            setIsTranscribing(false);
          }
        };
        stream.getTracks().forEach(track => track.stop());
      };
      mediaRecorder.start();
      setIsRecording(true);
    } catch (error) {
      console.error('Mic error:', error);
    }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
    }
  };

  const handleSubmit = () => {
    if (!isFormValid) return;
    setIsSubmitting(true);
    const log: DailyLog = {
      id: Math.random().toString(36).substring(7),
      identity_id: identity.id,
      date: new Date().toISOString(),
      note: trimmedNote,
      timeSpent: time,
      state: trimmedState,
      energy,
      anchorsCompleted: anchorStatus
    };
    setTimeout(() => onComplete(log), 400);
  };

  return (
    <div className="w-full pb-20 view-transition font-sans">
      <AnimatePresence>
        {isSubmitting && (
          <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 bg-bgMain z-[100] flex items-center justify-center" role="alert" aria-live="assertive">
            <span className="text-[11px] font-mono tracking-[0.5em] uppercase text-textPrimary">Logged.</span>
          </motion.div>
        )}
      </AnimatePresence>

      <header className="space-y-6 mb-12">
        <div className="flex justify-between items-start">
          <div className="space-y-1">
            <h1 className="text-[11px] font-mono tracking-[0.2em] text-textSecondary uppercase">{todayStr}</h1>
            <p className="text-sm font-semibold uppercase tracking-widest text-textPrimary">Day {dayOfCycle} of 30</p>
          </div>
          <div className="text-right space-y-1">
            <p className="text-[10px] font-mono tracking-widest text-textSecondary/40 uppercase">Identity: {identity.role}</p>
            <p className="text-[10px] font-mono tracking-widest text-accent uppercase" aria-label={`Continuity: ${continuity} Days`}>Continuity: {continuity} Days</p>
          </div>
        </div>

        {showWarning && (
          <motion.div initial={{ opacity: 0, y: -10 }} animate={{ opacity: 1, y: 0 }} className="flex items-center space-x-3 p-4 bg-accent/5 border border-accent/20" role="alert">
            <AlertCircle size={14} className="text-accent" aria-hidden="true" />
            <span className="text-[10px] font-mono tracking-widest uppercase text-accent">Observation gap detected.</span>
          </motion.div>
        )}

        <div className="noah-card overflow-hidden">
          <button onClick={() => setShowAnchors(!showAnchors)} className="w-full flex items-center justify-between p-4 active-feedback" aria-expanded={showAnchors}>
            <span className="noah-title">Anchors being tracked</span>
            <ChevronDown size={14} className={`text-textSecondary/40 transition-transform ${showAnchors ? 'rotate-180' : ''}`} />
          </button>
          <AnimatePresence>
            {showAnchors && (
              <motion.div initial={{ height: 0 }} animate={{ height: 'auto' }} exit={{ height: 0 }} className="px-4 pb-4 space-y-2">
                {identity.anchors.map((anchor, i) => (
                  <p key={i} className="text-xs text-textSecondary font-light leading-relaxed">• {anchor}</p>
                ))}
              </motion.div>
            )}
          </AnimatePresence>
        </div>
      </header>

      <div className="space-y-10">
        {!isCoherent && (
          <motion.div initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }} className="p-4 bg-red-950/20 border border-red-900/40 rounded-sm flex items-start space-x-3">
            <Info size={14} className="text-red-500 mt-0.5" />
            <div className="space-y-1">
              <p className="text-[10px] font-mono uppercase text-red-500 tracking-widest">Coherency Check Failed</p>
              <p className="text-[9px] text-red-400/60 leading-relaxed">Logged time and anchors do not align. Verify your reality before submission.</p>
            </div>
          </motion.div>
        )}

        <section className="space-y-4">
          <div className="flex justify-between items-center">
            <label htmlFor="daily-action" className="text-[10px] font-mono tracking-widest uppercase text-textSecondary">What did you actually do today?</label>
            <div className="flex items-center space-x-2">
              {isTranscribing && <Loader2 size={12} className="text-accent animate-spin" />}
              <button type="button" onClick={isRecording ? stopRecording : startRecording} disabled={isTranscribing} className={`p-2 rounded-full transition-all active-feedback ${isRecording ? 'bg-accent/20 text-accent animate-pulse' : 'text-textSecondary/40 hover:text-textPrimary'}`}>
                {isRecording ? <Square size={14} /> : <Mic size={14} />}
              </button>
            </div>
          </div>
          <textarea id="daily-action" value={note} onChange={(e) => setNote(e.target.value.slice(0, 120))} maxLength={120} className={`w-full bg-muted/30 border p-4 text-sm text-textPrimary focus:outline-none focus:ring-1 transition-all placeholder:text-textSecondary/20 min-h-[120px] resize-none ${note.length > 0 && !isNoteValid ? 'border-red-500/50 focus:ring-red-500' : 'border-border focus:ring-accent'}`} placeholder={isRecording ? "Listening..." : "Document reality..."} />
          <div className="flex justify-between items-center">
            <p className="text-[9px] text-red-500/60 font-mono tracking-widest">{note.length > 0 && note.length < 3 ? 'Minimum 3 characters required' : ''}</p>
            <span className={`text-[9px] font-mono tracking-widest ${note.length > 120 ? 'text-red-500' : 'text-textSecondary/30'}`}>{note.length}/120 characters</span>
          </div>
        </section>

        <section className="space-y-4">
          <h2 className="text-[10px] font-mono tracking-widest uppercase text-textSecondary">Alignment Verification</h2>
          <div className="space-y-2">
            {identity.anchors.map((anchor, i) => (
              <button key={i} onClick={() => {
                const n = [...anchorStatus];
                n[i] = !n[i];
                setAnchorStatus(n);
              }} className={`w-full text-left p-4 flex items-center justify-between border active-feedback ${anchorStatus[i] ? 'border-accent bg-accent/10 text-textPrimary' : 'border-border bg-muted/20 text-textSecondary/40'} transition-all duration-300`}>
                <span className="text-[11px] uppercase tracking-widest">{anchor}</span>
                <div className={`w-3 h-3 border ${anchorStatus[i] ? 'bg-accent border-accent' : 'border-white/10'}`} />
              </button>
            ))}
          </div>
        </section>

        <section className="space-y-6">
          <div className="flex justify-between items-end">
            <label htmlFor="time-slider" className="text-[10px] font-mono tracking-widest uppercase text-textSecondary">Time Spent</label>
            <span className="text-sm font-mono text-textPrimary">{time}{time >= 180 ? '+' : ''}m</span>
          </div>
          <input id="time-slider" type="range" min="0" max="180" step="15" value={time} onChange={(e) => setTime(parseInt(e.target.value))} className="w-full active-feedback" />
        </section>

        <section className="space-y-4">
          <label htmlFor="mental-state" className="text-[10px] font-mono tracking-widest uppercase text-textSecondary">Mental State</label>
          <input id="mental-state" type="text" value={state} onChange={(e) => setState(e.target.value)} placeholder="Focused / Avoiding / Calm..." className={`w-full bg-muted/30 border p-4 text-sm text-textPrimary focus:outline-none focus:ring-1 transition-all placeholder:text-textSecondary/20 ${state.length > 0 && !isStateValid ? 'border-red-500/50 focus:ring-red-500' : 'border-border focus:ring-accent'}`} />
          {state.length > 0 && !isStateValid && <p className="text-[9px] text-red-500/60 font-mono tracking-widest">Minimum 2 characters required</p>}
        </section>

        <section className="space-y-4">
          <h2 className="text-[10px] font-mono tracking-widest uppercase text-textSecondary">Energy Level</h2>
          <div className="grid grid-cols-3 gap-2">
            {(['LOW', 'MEDIUM', 'HIGH'] as EnergyLevel[]).map((level) => (
              <button key={level} onClick={() => setEnergy(level)} className={`py-4 text-[10px] font-mono tracking-widest transition-all active-feedback border ${energy === level ? 'bg-accent text-textPrimary border-accent' : 'bg-muted/30 text-textSecondary/40 border-border'}`}>{level}</button>
            ))}
          </div>
        </section>

        <button onClick={handleSubmit} disabled={!isFormValid || isSubmitting} className="w-full bg-accent py-5 text-[11px] font-mono tracking-[0.5em] uppercase disabled:opacity-20 disabled:cursor-not-allowed transition-all active-feedback mt-4">
          {isSubmitting ? 'Processing...' : 'Submit Check-in'}
        </button>
      </div>
    </div>
  );
};

