export async function transcribeAudio(
  base64Audio: string,
  mimeType: string
): Promise<string> {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          {
            inlineData: {
              data: base64Audio,
              mimeType: mimeType,
            },
          },
          { text: "Transcribe precisely. Output raw text only. No meta-talk." }
        ]
      },
    });
    return response.text || "";
  } catch (error) {
    console.error('Transcription error:', error);
    throw new Error('Failed to interpret audio signal.');
  }
}

