export async function generateAlignmentFeedback(
  identity: UserIdentity,
  logs: DailyLog[]
): Promise<FeedbackData> {
  if (logs.length === 0) {
    return {
      status: 'UNSTABLE',
      message: 'Initial observation required.',
      observation: 'No signal.'
    };
  }

  const coreResult = noahCoreEngine.process(logs);
  const recentLogs = logs.slice(-7);

  const prompt = `
    AUDIT ALIGNMENT.

    IDENTITY: ${identity.role}
    ANCHORS: ${identity.anchors.join(', ')}
    CORE DIAGNOSTICS: ${coreResult.explanation}
    AUTHENTICITY: ${coreResult.meta.authenticity}

    LOGS (Last 7 days):
    ${recentLogs.map(l => `- ${l.date}: "${l.note}". Time: ${l.timeSpent}m. State: ${l.state}.`).join('\n')}

    RULES:
    - If Authenticity is < 0.7, call out self-deception.
    - Status priority: Deterministic Diagnostics.
    - Output valid JSON.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: 'application/json',
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            status: { type: Type.STRING, enum: ['ALIGNED', 'UNSTABLE', 'DRIFTING'] },
            message: { type: Type.STRING },
            observation: { type: Type.STRING }
          },
          required: ['status', 'message', 'observation']
        }
      }
    });

    const result = JSON.parse(response.text || '{}');
    return {
      status: result.status || 'UNSTABLE',
      message: result.message || 'Patterns require more clarity.',
      observation: result.observation || coreResult.explanation
    };
  } catch (error) {
    console.error('Gemini error:', error);
    return {
      status: 'UNSTABLE',
      message: 'Logic systems disconnected.',
      observation: coreResult.explanation
    };
  }
