import React, { useState, useEffect, useRef } from 'react';
import { UserIdentity, DailyLog } from '../types';
import { motion, AnimatePresence } from 'framer-motion';
import { Upload, X, AlertTriangle, FileUp, Check, ShieldCheck, ArrowRight, Clock } from 'lucide-react';
import { store } from '../store';

interface Props {
  onLock: (id: UserIdentity) => void;
}

const IdentitySetup: React.FC<Props> = ({ onLock }) => {
  const [slideIndex, setSlideIndex] = useState(0);
  const [role, setRole] = useState('');
  const [anchors, setAnchors] = useState(['', '', '']);
  const [checkInTime, setCheckInTime] = useState('19:00');
  const [isLocking, setIsLocking] = useState(false);
  const [showConfirm, setShowConfirm] = useState(false);
  const [importStatus, setImportStatus] = useState<'idle' | 'success' | 'error' | 'verifying'>('idle');

  const [pendingNode, setPendingNode] = useState<{ identity: UserIdentity, logs: DailyLog[] } | null>(null);
  const [nodeIdInput, setNodeIdInput] = useState('');
  const [verificationError, setVerificationError] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  const slides = [
    "This is not a productivity app.",
    "This is a mirror.",
    "You will define who you want to become.",
    "Then you will observe yourself.",
    "Nothing more. Nothing less."
  ];

  const handleNextSlide = () => {
    if (slideIndex < slides.length - 1) setSlideIndex(slideIndex + 1);
    else setSlideIndex(99); 
  };

  const trimmedRole = role.trim();
  const validAnchors = anchors.map(a => a.trim()).filter(a => a.length >= 3);
  const isRoleValid = trimmedRole.length >= 3;
  const isFormValid = isRoleValid && validAnchors.length > 0;

  const handleLock = () => {
    if (!isFormValid) return;
    setIsLocking(true);
    const finalAnchors = validAnchors;
    const now = new Date().toISOString();
    const anonId = store.getAnonId();

    onLock({
      id: anonId,
      role: trimmedRole,
      anchors: finalAnchors,
      checkInTime: checkInTime,
      created_at: now,
      cycle_start: now,
      status: 'UNSTABLE',
      expiresAt: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString()
    });
  };

  const handleImportJson = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const json = JSON.parse(event.target?.result as string);
        if (json.identity && json.logs) {
          setPendingNode({ identity: json.identity, logs: json.logs });
          setImportStatus('verifying');
          return;
        }
        if (json.role) {
          setRole(json.role);
          setImportStatus('success');
          if (Array.isArray(json.anchors)) {
            const newAnchors = ['', '', ''];
            json.anchors.forEach((a: string, i: number) => {
              if (i < 3) newAnchors[i] = a;
            });
            setAnchors(newAnchors);
          }
          if (json.checkInTime) setCheckInTime(json.checkInTime);
          setTimeout(() => setImportStatus('idle'), 2000);
        }
      } catch (err) {
        setImportStatus('error');
        setTimeout(() => setImportStatus('idle'), 2000);
      }
    };
    reader.readAsText(file);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const verifyNodeId = () => {
    if (!pendingNode) return;
    const matches = nodeIdInput.trim() === pendingNode.identity.id || 
                    pendingNode.identity.id.startsWith(nodeIdInput.trim()) && nodeIdInput.trim().length >= 8;
    if (matches) {
      setIsLocking(true);
      setImportStatus('success');
      store.saveIdentity(pendingNode.identity);
      pendingNode.logs.forEach((log: DailyLog) => store.addLog(log));
      setTimeout(() => window.location.reload(), 800);
    } else {
      setVerificationError(true);
      setTimeout(() => setVerificationError(false), 2000);
    }
  };

  if (slideIndex < slides.length) {
    return (
      <div 
        onClick={handleNextSlide}
        className="min-h-screen bg-bgMain flex flex-col items-center justify-center p-12 text-center cursor-pointer select-none"
      >
        <AnimatePresence mode="wait">
          <motion.p 
            key={slideIndex}
            initial={{ opacity: 0, scale: 0.98 }}
            animate={{ opacity: 1, scale: 1 }}
            exit={{ opacity: 0, scale: 1.02 }}
            className="text-xl md:text-2xl font-light tracking-wide text-textPrimary max-w-md"
          >
            {slides[slideIndex]}
          </motion.p>
        </AnimatePresence>
        <div className="absolute bottom-16 flex space-x-2">
          {slides.map((_, i) => (
            <div key={i} className={`h-[1px] w-4 transition-all duration-700 ${i === slideIndex ? 'bg-textPrimary' : 'bg-white/10'}`} />
          ))}
        </div>
      </div>
    );
  }

  return (
    <motion.div 
      initial={{ opacity: 0 }} 
      animate={{ opacity: 1 }}
      className="min-h-screen bg-bgMain flex flex-col items-center justify-center p-6 text-center overflow-y-auto no-scrollbar"
    >
      <AnimatePresence>
        {importStatus === 'verifying' && pendingNode && (
          <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 bg-bgMain/98 z-[200] flex items-center justify-center p-6 backdrop-blur-xl">
            <motion.div initial={{ y: 20, opacity: 0 }} animate={{ y: 0, opacity: 1 }} className="noah-card max-w-xs w-full p-8 space-y-8 border-accent/40">
              <div className="flex flex-col items-center space-y-4">
                <ShieldCheck size={32} className="text-accent" />
                <h3 className="noah-title text-center text-textPrimary">Verify Node Identity</h3>
                <p className="text-[10px] text-textSecondary/60 font-mono tracking-widest uppercase leading-relaxed">Enter the Node ID to authorize restoration.</p>
              </div>
              <input
                type="text"
                value={nodeIdInput}
                onChange={(e) => setNodeIdInput(e.target.value)}
                placeholder="ID: xxxx-xxxx..."
                className={`w-full bg-muted/30 border p-4 text-center text-xs font-mono tracking-widest focus:outline-none focus:ring-1 ${verificationError ? 'border-red-500/50 ring-red-500' : 'border-border focus:ring-accent'}`}
                autoFocus
              />
              <button onClick={verifyNodeId} disabled={nodeIdInput.length < 4} className="w-full bg-accent py-4 text-[10px] font-mono tracking-[0.3em] uppercase flex items-center justify-center space-x-2 disabled:opacity-20">
                <span>Verify and Restore</span>
                <ArrowRight size={12} />
              </button>
            </motion.div>
          </motion.div>
        )}

        {showConfirm && (
          <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 bg-bgMain/95 z-[100] flex items-center justify-center p-6 backdrop-blur-sm">
            <motion.div initial={{ scale: 0.95, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} className="noah-card max-w-xs w-full p-8 space-y-8 border-accent/20 text-center">
              <AlertTriangle size={32} className="text-accent opacity-50 mx-auto" />
              <div className="space-y-4">
                <h3 className="noah-title text-textPrimary">Final Confirmation</h3>
                <p className="text-sm text-textSecondary font-light leading-relaxed">This identity cannot be changed for 30 days.</p>
              </div>
              <button onClick={handleLock} className="w-full bg-accent py-4 text-[10px] font-mono tracking-[0.3em] uppercase">Confirm Lock</button>
              <button onClick={() => setShowConfirm(false)} className="w-full py-4 text-[10px] font-mono tracking-[0.3em] uppercase text-textSecondary/40">Review</button>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      <div className="w-full max-w-sm space-y-12 py-12">
        <header className="flex flex-col items-center space-y-4">
           <button onClick={() => fileInputRef.current?.click()} className="flex items-center space-x-3 px-6 py-3 border border-white/5 rounded-sm text-[10px] uppercase tracking-widest font-mono text-textSecondary/60">
            <FileUp size={14} /> <span>Import Node</span>
          </button>
          <input ref={fileInputRef} type="file" accept=".json" onChange={handleImportJson} className="hidden" />
        </header>

        <div className="space-y-4">
          <label htmlFor="identity-input" className="noah-title block">Target Identity</label>
          <input
            id="identity-input"
            type="text"
            value={role}
            onChange={(e) => setRole(e.target.value)}
            placeholder="Founder. Artist. Student."
            className="w-full bg-transparent border-b border-white/10 py-3 text-2xl text-center focus:outline-none focus:border-accent transition-colors"
            autoFocus
          />
        </div>

        <div className="space-y-4">
          <h2 className="noah-title">Anchors</h2>
          <div className="space-y-3">
            {anchors.map((a, i) => (
              <input
                key={i}
                type="text"
                value={a}
                onChange={(e) => {
                  const n = [...anchors];
                  n[i] = e.target.value;
                  setAnchors(n);
                }}
                placeholder={`Behavioral Anchor ${i + 1}`}
                className="w-full bg-muted/30 border border-border/50 rounded-sm p-3 text-sm focus:outline-none focus:border-accent text-center"
              />
            ))}
          </div>
        </div>

        <div className="space-y-4">
          <h2 className="noah-title">Observation Window</h2>
          <p className="text-[10px] text-textSecondary/40 font-mono tracking-widest uppercase">Preferred check-in time (6 PM - 10 PM)</p>
          <div className="flex items-center justify-center space-x-4">
            <Clock size={16} className="text-accent" />
            <select 
              value={checkInTime} 
              onChange={(e) => setCheckInTime(e.target.value)}
              className="bg-muted border border-border p-3 text-xs font-mono tracking-widest rounded-sm focus:ring-1 focus:ring-accent outline-none"
            >
              <option value="18:00">18:00 (6:00 PM)</option>
              <option value="18:30">18:30 (6:30 PM)</option>
              <option value="19:00">19:00 (7:00 PM)</option>
              <option value="19:30">19:30 (7:30 PM)</option>
              <option value="20:00">20:00 (8:00 PM)</option>
              <option value="20:30">20:30 (8:30 PM)</option>
              <option value="21:00">21:00 (9:00 PM)</option>
              <option value="21:30">21:30 (9:30 PM)</option>
              <option value="22:00">22:00 (10:00 PM)</option>
            </select>
          </div>
        </div>

        <button
          onClick={() => setShowConfirm(true)}
          disabled={!isFormValid || isLocking}
          className="w-full bg-accent py-4 text-[11px] font-mono tracking-[0.4em] uppercase disabled:opacity-10"
        >
          {isLocking ? 'Processing...' : 'Lock Identity'}
        </button>
      </div>
    </motion.div>
  );
};

