  const handleCopyNodeId = () => {
    // The identity.id is the master anon_id
    navigator.clipboard.writeText(identity.id);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="w-full space-y-10 view-transition pb-12 overflow-y-auto no-scrollbar">
      <header className="space-y-4 pt-6">
        <h1 className="text-xs font-mono tracking-[0.3em] uppercase text-textSecondary opacity-40">Operational Identity</h1>
        <p className="text-4xl font-mono tracking-tighter uppercase text-textPrimary">{identity.role}</p>
      </header>

      {/* Node ID Collapsible */}
      <section className="noah-card overflow-hidden">
        <button 
          onClick={() => setShowNodeInfo(!showNodeInfo)} 
          className="w-full flex items-center justify-between p-4 active-feedback"
        >
          <div className="flex items-center space-x-2">
            <Fingerprint size={12} className="text-textSecondary/40" />
            <span className="noah-title">Node Signature</span>
          </div>
          <ChevronDown size={14} className={`text-textSecondary/40 transition-transform ${showNodeInfo ? 'rotate-180' : ''}`} />
        </button>
        <AnimatePresence>
          {showNodeInfo && (
            <motion.div 
              initial={{ height: 0, opacity: 0 }} 
              animate={{ height: 'auto', opacity: 1 }} 
              exit={{ height: 0, opacity: 0 }} 
              className="px-4 pb-4 space-y-4"
            >
              <div className="bg-bgMain p-3 border border-white/5 rounded-sm flex items-center justify-between group">
                <code className="text-[10px] font-mono text-textSecondary truncate mr-4">
                  {identity.id}
                </code>
                <button 
                  onClick={handleCopyNodeId} 
                  className="p-2 text-textSecondary/40 hover:text-textPrimary transition-colors active-feedback"
                  aria-label="Copy Node ID"
                >
                  {copied ? <Check size={12} className="text-accent" /> : <Copy size={12} />}
                </button>
              </div>
              <p className="text-[9px] font-mono tracking-widest text-textSecondary/20 uppercase text-center">Identity persistency token (Locked)</p>
            </motion.div>
          )}
        </AnimatePresence>
      </section>

      <section className="space-y-6">
        <h2 className="text-xs font-mono tracking-widest uppercase text-textSecondary">Observation Targets</h2>
        <div className="space-y-4">
          {identity.anchors.map((anchor, i) => (
            <div key={i} className="flex items-center space-x-4 border-b border-white/5 py-4 last:border-0">
              <span className="text-[10px] font-mono text-textSecondary opacity-30">{String(i + 1).padStart(2, '0')}</span>
              <span className="text-sm tracking-wide text-textPrimary/80">{anchor}</span>
            </div>
          ))}
        </div>
      </section>

      <section className="pt-4 space-y-4">
        <div className="flex justify-between items-end">
          <h2 className="text-[10px] font-mono uppercase tracking-widest text-textSecondary">Cycle Fidelity</h2>
          <span className="text-sm font-mono text-textPrimary">{daysPassed}/30 Days</span>
        </div>
        <div className="h-[2px] w-full bg-white/5 overflow-hidden">
          <motion.div 
            initial={{ width: 0 }}
            animate={{ width: `${progressPercent}%` }}
            transition={{ duration: 1.5, ease: "easeOut" }}
            className="h-full bg-accent" 
          />
        </div>
        <div className="flex justify-between items-center">
           <p className="text-[10px] font-mono text-textSecondary/40 uppercase tracking-widest">
            {daysRemaining} Days remaining
          </p>
          <p className="text-[10px] font-mono text-accent/60 uppercase tracking-widest">
            Window: {identity.checkInTime}
          </p>
        </div>
      </section>

      <footer className="pt-12 text-center opacity-10">
        <p className="text-[8px] font-mono tracking-[0.5em] uppercase">
          Persistence node established {new Date(identity.created_at).toLocaleDateString()}
        </p>
      </footer>
    </div>
  );
};

export default IdentityView;

import { DailyLog, EnergyLevel } from '../types';
import { SignalMetrics, WindowAnalysis } from './types';

const energyValue: Record<EnergyLevel, number> = { 'LOW': 0.1, 'MEDIUM': 0.5, 'HIGH': 1.0 };
const NEGATIVE_THRESHOLD = 0.4;

function calculateMetrics(logs: DailyLog[]): SignalMetrics {
  if (logs.length === 0) return { avg: 0, negCount: 0, variance: 0, authenticity: 1 };

  const values = logs.map(l => {
    const time = Math.min(l.timeSpent / 180, 1.0);
    const energy = energyValue[l.energy];
    const anchors = l.anchorsCompleted || [];
    const anchorRatio = anchors.length > 0 ? anchors.filter(Boolean).length / anchors.length : 0;

    // Core signal formula: Weighted towards Anchors (40%) and Time (40%)
    return (time * 0.4) + (energy * 0.2) + (anchorRatio * 0.4);
  });

  // Advanced Authenticity Calculation
  const authenticityScores = logs.map(l => {
    let score = 1.0;
    const time = l.timeSpent;
    const anchors = l.anchorsCompleted || [];
    const completedCount = anchors.filter(Boolean).length;
    const noteLength = (l.note || "").trim().length;

    // Rule 1: Effort Paradox (High time, no anchors)
    if (time > 120 && completedCount === 0) score -= 0.4;

    // Rule 2: Ghost Achievement (No time, completed anchors)
    if (time === 0 && completedCount > 0) score -= 0.6;

    // Rule 3: Superficiality (All anchors done in < 30 mins)
    if (time < 30 && completedCount === anchors.length && anchors.length > 0) score -= 0.3;

    // Rule 4: Signal Insufficiency (Minimal note)
    if (noteLength < 10) score -= 0.2;

    return Math.max(0, score);
  });

  const avg = values.reduce((a, b) => a + b, 0) / values.length;
  const negCount = values.filter(v => v < NEGATIVE_THRESHOLD).length;
  const variance = values.length < 2 ? 0 : values.reduce((acc, v) => acc + Math.pow(v - avg, 2), 0) / values.length;
  const authenticity = authenticityScores.reduce((a, b) => a + b, 0) / authenticityScores.length;

  return { avg, negCount, variance, authenticity };
}

export const signalAnalyzer = {
  analyze(logs: DailyLog[]): WindowAnalysis {
    const sorted = [...logs].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    const windowRecent = sorted.slice(0, 7);
    const windowPrevious = sorted.slice(7, 14);

    const recent = calculateMetrics(windowRecent);
    const previous = calculateMetrics(windowPrevious);

    const delta = recent.avg - previous.avg;
    const volatility = Math.abs(recent.avg - previous.avg) + (recent.variance * 2);

    let dominantCategory: 'Time' | 'Energy' | 'Alignment' | 'None' = 'None';
    let maxNeg = 0;

    if (windowRecent.length > 0) {
      const timeNeg = windowRecent.filter(l => l.timeSpent < 45).length;
      const energyNeg = windowRecent.filter(l => l.energy === 'LOW').length;
      const alignNeg = windowRecent.filter(l => (l.anchorsCompleted?.filter(Boolean).length || 0) === 0).length;

      maxNeg = Math.max(timeNeg, energyNeg, alignNeg);
      if (maxNeg > 0) {
        if (maxNeg === timeNeg) dominantCategory = 'Time';
        else if (maxNeg === energyNeg) dominantCategory = 'Energy';
        else dominantCategory = 'Alignment';
      }
    }

    return {
      recent,
      previous,
      delta,
      volatility,
      dominantCategory,
      repetitionCount: maxNeg
    };
  }
};

import { WindowAnalysis } from './types';

export const driftDetector = {
  detect(analysis: WindowAnalysis): number {
    let score = 0;

    // 1. Negative trend delta -> +2
    if (analysis.delta < -0.1) {
      score += 2;
    }

    // 2. Repeated negative signals (>=3 same category) -> +2
    if (analysis.repetitionCount >= 3) {
      score += 2;
    }

    // 3. High instability -> +1
    if (analysis.recent.variance > 0.15) {
      score += 1;
    }

    // 4. Low Authenticity (Incoherent Data) -> +2
    // If authenticity is low, it suggests a disconnect between reality and logging.
    if (analysis.recent.authenticity < 0.7) {
      score += 2;
    }

    return score;
  }
};

