import { WindowAnalysis, DriftState } from './types';

export const explanationBuilder = {
  build(analysis: WindowAnalysis, state: DriftState): string {
    if (analysis.dominantCategory === 'None' && analysis.recent.avg > 0.7) {
      return "Operational stability detected. Identity signals are congruent across all measured metrics.";
    }

    const segments = [];

    // Authenticity Check
    if (analysis.recent.authenticity < 0.7) {
      segments.push("Critical authenticity failure: Incoherent signal patterns suggest identity inflation or reality disconnect.");
    } else if (analysis.recent.authenticity < 0.85) {
      segments.push("Minor signal incongruity: Behavioral anchors do not fully map to operational time.");
    }

    // Volatility Check
    if (analysis.volatility > 0.4) {
      segments.push("High trajectory volatility: Signal variance suggests unsustainable effort or emotional oscillation.");
    }

    // Category Specifics
    if (analysis.dominantCategory !== 'None') {
      const trend = analysis.delta < 0 ? "deteriorating" : "stagnant";
      segments.push(`${analysis.dominantCategory} metrics are ${trend} (Negative signal density: ${analysis.repetitionCount}/7).`);
    }

    return segments.length > 0 
      ? segments.join(" ") 
      : "Insufficient signal density for deep diagnostic explanation.";
  }
};

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { DailyLog, EnergyLevel, UserIdentity } from '../types';
import { ChevronDown, AlertCircle, Mic, Square, Loader2, Info, Lock, Zap, ClipboardCheck } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { transcribeAudio } from '../services/geminiService';

interface Props {
  identity: UserIdentity;
  logs: DailyLog[];
  onComplete: (log: DailyLog) => void;
}

const CheckIn: React.FC<Props> = ({ identity, logs, onComplete }) => {
  const [note, setNote] = useState('');
  const [time, setTime] = useState(60);
  const [state, setState] = useState('');
  const [energy, setEnergy] = useState<EnergyLevel>('MEDIUM');
  const [anchorStatus, setAnchorStatus] = useState<boolean[]>(new Array(identity.anchors.length).fill(false));
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [showAnchors, setShowAnchors] = useState(false);

  const [isRecording, setIsRecording] = useState(false);
  const [isTranscribing, setIsTranscribing] = useState(false);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioChunksRef = useRef<Blob[]>([]);

  // Daily Restriction Logic
  const todayStart = new Date();
  todayStart.setHours(0,0,0,0);

  const hasCheckedInToday = useMemo(() => {
    return logs.some(log => {
      const logDate = new Date(log.date);
      logDate.setHours(0,0,0,0);
      return logDate.getTime() === todayStart.getTime();
    });
  }, [logs]);

  const isFirstCheckIn = logs.length === 0;

  const isWithinWindow = useMemo(() => {
    const now = new Date();
    const currentHour = now.getHours();
    return currentHour >= 18 && currentHour < 22;
  }, []);

  const canCheckIn = isFirstCheckIn || (isWithinWindow && !hasCheckedInToday);

  // Coherency Logic & Validations
  const trimmedNote = note.trim();
  const trimmedState = state.trim();
  const anchorsChecked = anchorStatus.filter(Boolean).length;

  const coherencyWarnings = useMemo(() => {
    const warnings: string[] = [];

    // Rule 1: Ghost Achievement (Anchors marked with 0 time)
    if (time === 0 && anchorsChecked > 0) {
      warnings.push("Reality Disconnect: Anchors cannot be validated with zero time investment.");
    }

    // Rule 2: Effort Paradox (High time, 0 anchors)
    if (time > 120 && anchorsChecked === 0) {
      warnings.push("Incoherent Effort: 2h+ logged without specific behavioral anchor results.");
    }

    // Rule 3: Velocity Warning (Claiming all anchors in too little time)
    if (time < 20 && anchorsChecked >= 2) {
      warnings.push("Velocity Alert: Effort density claimed exceeds reasonable human execution window.");
    }

    // Rule 4: Detail Integrity (Documentation too short for claimed effort)
    if (time >= 90 && trimmedNote.length < 15) {
      warnings.push("Documentation Gap: 90m+ of activity requires deeper objective documentation.");
    }

    // Rule 5: Sustainability Check (Very high time with low energy)
    if (time > 150 && energy === 'LOW') {
      warnings.push("Friction Warning: High operational volume paired with low energy signal.");
    }

    return warnings;
  }, [time, anchorsChecked, trimmedNote, energy]);

  const isNoteValid = trimmedNote.length >= 3 && trimmedNote.length <= 120;
  const isStateValid = trimmedState.length >= 2;
  const isCoherent = coherencyWarnings.length === 0;

  const isFormValid = isNoteValid && isStateValid && isCoherent;

  const handleSubmit = () => {
    if (!isFormValid || !canCheckIn) return;
    setIsSubmitting(true);
    const log: DailyLog = {
      id: Math.random().toString(36).substring(7),
      identity_id: identity.id,
      date: new Date().toISOString(),
      note: trimmedNote,
      timeSpent: time,
      state: trimmedState,
      energy,
      anchorsCompleted: anchorStatus
    };
    setTimeout(() => onComplete(log), 400);
  };

  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const mediaRecorder = new MediaRecorder(stream);
      mediaRecorderRef.current = mediaRecorder;
      audioChunksRef.current = [];
      mediaRecorder.ondataavailable = (event) => audioChunksRef.current.push(event.data);
      mediaRecorder.onstop = async () => {
        const audioBlob = new Blob(audioChunksRef.current, { type: 'audio/webm' });
        const reader = new FileReader();
        reader.readAsDataURL(audioBlob);
        reader.onloadend = async () => {
          const base64Data = (reader.result as string).split(',')[1];
          setIsTranscribing(true);
          try {
            const text = await transcribeAudio(base64Data, 'audio/webm');
            setNote((prev) => (prev + ' ' + text).trim().slice(0, 120));
          } catch (error) { console.error(error); } finally { setIsTranscribing(false); }
        };
        stream.getTracks().forEach(track => track.stop());
      };
      mediaRecorder.start();
      setIsRecording(true);
    } catch (error) { console.error('Mic error:', error); }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
    }
  };

  if (!canCheckIn) {
    return (
      <div className="flex-grow flex flex-col items-center justify-center space-y-8 py-20 text-center animate-fade-in">
        <div className="relative">
          <div className="absolute inset-0 bg-accent/20 blur-3xl rounded-full" />
          <Lock size={48} className="text-textSecondary/20 relative z-10" />
        </div>
        <div className="space-y-4 max-w-xs">
          <h2 className="text-xs font-mono tracking-[0.4em] uppercase text-textSecondary/40">Portal Locked</h2>
          <p className="text-sm font-light text-textSecondary leading-relaxed">
            {hasCheckedInToday 
              ? "Your reality for today has been documented. The mirror reopens tomorrow." 
              : `Access restricted. The daily observation window opens between 18:00 and 22:00.`}
          </p>
        </div>
        <div className="pt-8">
           <span className="text-[9px] font-mono tracking-[0.3em] uppercase text-accent/40">Target Window: {identity.checkInTime} — 22:00</span>
        </div>
      </div>
    );
  }

  return (
    <div className="w-full pb-20 view-transition font-sans">
      <AnimatePresence>
        {isSubmitting && (
          <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 bg-bgMain z-[100] flex items-center justify-center">
            <span className="text-[11px] font-mono tracking-[0.5em] uppercase text-textPrimary">Logged.</span>
          </motion.div>
        )}
      </AnimatePresence>

      <header className="space-y-6 mb-12 pt-6">
        <div className="flex justify-between items-start">
          <div className="space-y-1">
            <h1 className="text-[11px] font-mono tracking-[0.2em] text-textSecondary uppercase">Daily Check-in</h1>
            <p className="text-sm font-semibold uppercase tracking-widest text-textPrimary">Day {isFirstCheckIn ? 1 : Math.floor((Date.now() - new Date(identity.created_at).getTime())/(1000*60*60*24))+1} of 30</p>
          </div>
          <div className="text-right">
             <p className="text-[10px] font-mono tracking-widest text-accent uppercase">{isFirstCheckIn ? "Setup Node" : "Observation"}</p>
          </div>
        </div>

        <div className="noah-card overflow-hidden">
          <button onClick={() => setShowAnchors(!showAnchors)} className="w-full flex items-center justify-between p-4 active-feedback" aria-expanded={showAnchors}>
            <div className="flex items-center space-x-2">
              <ClipboardCheck size={12} className="text-textSecondary/40" />
              <span className="noah-title">Identity Anchors</span>
            </div>
            <ChevronDown size={14} className={`text-textSecondary/40 transition-transform ${showAnchors ? 'rotate-180' : ''}`} />
          </button>
          <AnimatePresence>
            {showAnchors && (
              <motion.div initial={{ height: 0 }} animate={{ height: 'auto' }} exit={{ height: 0 }} className="px-4 pb-4 space-y-2">
                {identity.anchors.map((anchor, i) => (
                  <p key={i} className="text-xs text-textSecondary font-light leading-relaxed">• {anchor}</p>
                ))}
              </motion.div>
            )}
          </AnimatePresence>
        </div>
      </header>

      <div className="space-y-10">
        <AnimatePresence>
          {!isCoherent && (
            <motion.div initial={{ opacity: 0, height: 0 }} animate={{ opacity: 1, height: 'auto' }} exit={{ opacity: 0, height: 0 }} className="space-y-2 overflow-hidden">
              {coherencyWarnings.map((warning, i) => (
                <div key={i} className="p-3 bg-red-950/20 border border-red-900/40 rounded-sm flex items-start space-x-3">
                  <AlertCircle size={14} className="text-red-500 mt-0.5 shrink-0" />
                  <p className="text-[9px] text-red-400 font-mono uppercase tracking-widest leading-relaxed">{warning}</p>
                </div>
              ))}
            </motion.div>
          )}
        </AnimatePresence>

        <section className="space-y-4">
          <div className="flex justify-between items-center">
            <label className="text-[10px] font-mono tracking-widest uppercase text-textSecondary">Action Observation</label>
            <div className="flex items-center space-x-3">
              {isTranscribing && <Loader2 size={12} className="text-accent animate-spin" />}
              <button type="button" onClick={isRecording ? stopRecording : startRecording} disabled={isTranscribing} className={`p-2 rounded-full transition-all ${isRecording ? 'text-accent animate-pulse bg-accent/10' : 'text-textSecondary/40 hover:text-textPrimary'}`}>
                {isRecording ? <Square size={14} /> : <Mic size={14} />}
              </button>
            </div>
          </div>
          <textarea 
            value={note} 
            onChange={(e) => setNote(e.target.value.slice(0, 120))} 
            className={`w-full bg-muted/30 border p-4 text-sm text-textPrimary focus:outline-none transition-all min-h-[120px] resize-none ${note.length > 0 && !isNoteValid ? 'border-red-500/50' : 'border-border focus:border-accent'}`} 
            placeholder={isRecording ? "Listening..." : "Document today's core reality..."} 
          />
          <div className="flex justify-between">
             <p className="text-[9px] text-red-500/60 font-mono tracking-widest">{note.length > 0 && note.length < 3 ? 'Min 3 chars' : ''}</p>
            <span className={`text-[8px] font-mono tracking-widest uppercase ${note.length > 120 ? 'text-red-500' : 'text-textSecondary/20'}`}>{note.length}/120</span>
          </div>
        </section>

        <section className="space-y-4">
          <h2 className="text-[10px] font-mono tracking-widest uppercase text-textSecondary">Alignment Verification</h2>
          <div className="space-y-2">
            {identity.anchors.map((anchor, i) => (
              <button key={i} onClick={() => {
                const n = [...anchorStatus];
                n[i] = !n[i];
                setAnchorStatus(n);
              }} className={`w-full text-left p-4 flex items-center justify-between border transition-all duration-300 ${anchorStatus[i] ? 'border-accent bg-accent/10 text-textPrimary' : 'border-border bg-muted/20 text-textSecondary/40'}`}>
                <span className="text-[11px] uppercase tracking-widest">{anchor}</span>
                <div className={`w-3 h-3 border ${anchorStatus[i] ? 'bg-accent border-accent' : 'border-white/10'}`} />
              </button>
            ))}
          </div>
        </section>

