          <input type="range" min="0" max="180" step="15" value={time} onChange={(e) => setTime(parseInt(e.target.value))} className="w-full active-feedback" />
        </section>

        <section className="space-y-4">
          <h2 className="text-[10px] font-mono tracking-widest uppercase text-textSecondary">Internal State</h2>
          <input type="text" value={state} onChange={(e) => setState(e.target.value)} placeholder="Focused / Avoidant / Calm..." className={`w-full bg-muted/30 border p-4 text-sm text-textPrimary focus:outline-none transition-all ${state.length > 0 && !isStateValid ? 'border-red-500/50' : 'border-border focus:border-accent'}`} />
