              <button key={level} onClick={() => setEnergy(level)} className={`py-4 text-[10px] font-mono tracking-widest border transition-all active-feedback ${energy === level ? 'bg-accent text-textPrimary border-accent' : 'bg-muted/30 text-textSecondary/40 border-border'}`}>{level}</button>
