import React, { useState, useMemo, useRef, useEffect } from 'react';
import { DailyLog, EnergyLevel, UserIdentity } from '../types';
import { ChevronDown, AlertCircle, Mic, Square, Loader2, Info, Lock, Zap, ClipboardCheck } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { transcribeAudio } from '../services/geminiService';

interface Props {
  identity: UserIdentity;
  logs: DailyLog[];
  onComplete: (log: DailyLog) => void;
}

const CheckIn: React.FC<Props> = ({ identity; logs; onComplete }) => {
  const [note, setNote] = useState('');
  const [time, setTime] = useState(60);
  const [state, setState] = useState('');
  const [energy, setEnergy] = useState<EnergyLevel>('MEDIUM');
  const [anchorStatus, setAnchorStatus] = useState<boolean[]>(new Array(identity.anchors.length).fill(false));
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [showAnchors, setShowAnchors] = useState(false);

  const [isRecording, setIsRecording] = useState(false);
  const [isTranscribing, setIsTranscribing] = useState(false);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioChunksRef = useRef<Blob[]>([]);

  // Daily Restriction Logic
  const todayStart = new Date();
  todayStart.setHours(0,0,0,0);

  const hasCheckedInToday = useMemo(() => {
    return logs.some(log => {
      const logDate = new Date(log.date);
      logDate.setHours(0,0,0,0);
      return logDate.getTime() === todayStart.getTime();
    });
  }, [logs]);

  const isFirstCheckIn = logs.length === 0;

  const isWithinWindow = useMemo(() => {
    const now = new Date();
    const currentHour = now.getHours();
    return currentHour >= 18 && currentHour < 22;
  }, []);

  const canCheckIn = isFirstCheckIn || (isWithinWindow && !hasCheckedInToday);

  // Coherency Logic & Validations
  const trimmedNote = note.trim();
  const trimmedState = state.trim();
  const anchorsChecked = anchorStatus.filter(Boolean).length;

  const coherencyWarnings = useMemo(() => {
    const warnings: string[] = [];

    // Rule 1: Ghost Achievement (Anchors marked with 0 time)
    if (time === 0 && anchorsChecked > 0) {
      warnings.push("Reality Disconnect: Anchors cannot be validated with zero time investment.");
    }

    // Rule 2: Effort Paradox (High time, 0 anchors)
    if (time > 120 && anchorsChecked === 0) {
      warnings.push("Incoherent Effort: 2h+ logged without specific behavioral anchor results.");
    }

    // Rule 3: Velocity Warning (Claiming multiple anchors in too little time)
    if (time < 30 && anchorsChecked >= 2) {
      warnings.push("Velocity Alert: High anchor volume claimed for minimal time window.");
    }

    // Rule 4: Detail Integrity (Documentation too short for significant time)
    if (time >= 90 && trimmedNote.length < 15) {
      warnings.push("Documentation Gap: Substantial time investment requires objective proof in notes.");
    }

    // Rule 5: State-Time Disparity (High state words with no time)
    const highPerformanceWords = ['focus', 'productive', 'crushed', 'flow', 'efficient'];
    const lowerState = trimmedState.toLowerCase();
    const hasHighWord = highPerformanceWords.some(w => lowerState.includes(w));
    if (hasHighWord && time < 15) {
      warnings.push("Cognitive Dissonance: High-performance state claims lack operational time backing.");
    }

    // Rule 6: Sustainability Check (Very high time with low energy)
    if (time > 150 && energy === 'LOW') {
      warnings.push("Friction Warning: High operational volume paired with low energy signal.");
    }

    return warnings;
  }, [time, anchorsChecked, trimmedNote, energy, trimmedState]);

  const isNoteValid = trimmedNote.length >= 3 && trimmedNote.length <= 120;
  const isStateValid = trimmedState.length >= 2;
  const isCoherent = coherencyWarnings.length === 0;

  const isFormValid = isNoteValid && isStateValid && isCoherent;

  const handleSubmit = () => {
    if (!isFormValid || !canCheckIn) return;
    setIsSubmitting(true);
    const log: DailyLog = {
      id: Math.random().toString(36).substring(7),
      identity_id: identity.id,
      date: new Date().toISOString(),
      note: trimmedNote,
      timeSpent: time,
      state: trimmedState,
      energy,
      anchorsCompleted: anchorStatus
    };
    // Sync logic is managed in App, we just trigger the callback
    setTimeout(() => onComplete(log), 400);
  };

  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const mediaRecorder = new MediaRecorder(stream);
      mediaRecorderRef.current = mediaRecorder;
      audioChunksRef.current = [];
      mediaRecorder.ondataavailable = (event) => audioChunksRef.current.push(event.data);
      mediaRecorder.onstop = async () => {
        const audioBlob = new Blob(audioChunksRef.current, { type: 'audio/webm' });
        const reader = new FileReader();
        reader.readAsDataURL(audioBlob);
        reader.onloadend = async () => {
          const base64Data = (reader.result as string).split(',')[1];
          setIsTranscribing(true);
          try {
            const text = await transcribeAudio(base64Data, 'audio/webm');
            setNote((prev) => (prev + ' ' + text).trim().slice(0, 120));
          } catch (error) { console.error(error); } finally { setIsTranscribing(false); }
        };
        stream.getTracks().forEach(track => track.stop());
      };
      mediaRecorder.start();
      setIsRecording(true);
    } catch (error) { console.error('Mic error:', error); }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
    }
  };

  if (!canCheckIn) {
    return (
      <div className="flex-grow flex flex-col items-center justify-center space-y-8 py-20 text-center animate-fade-in">
        <div className="relative">
          <div className="absolute inset-0 bg-accent/20 blur-3xl rounded-full" />
          <Lock size={48} className="text-textSecondary/20 relative z-10" />
        </div>
        <div className="space-y-4 max-w-xs">
          <h2 className="text-xs font-mono tracking-[0.4em] uppercase text-textSecondary/40">Portal Locked</h2>
          <p className="text-sm font-light text-textSecondary leading-relaxed">
            {hasCheckedInToday 
              ? "Your reality for today has been documented. The mirror reopens tomorrow." 
              : `Access restricted. The daily observation window opens between 18:00 and 22:00.`}
          </p>
        </div>
        <div className="pt-8">
           <span className="text-[9px] font-mono tracking-[0.3em] uppercase text-accent/40">Target Window: {identity.checkInTime} — 22:00</span>
        </div>
      </div>
    );
  }

  return (
    <div className="w-full pb-20 view-transition font-sans">
