    ${recentLogs.map(l => `- "${l.note}" | Time: ${l.timeSpent}m | State: ${l.state} | Anchors: ${l.anchorsCompleted?.filter(Boolean).length}/${l.anchorsCompleted?.length}`).join('\n')}

