import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { AppView, UserIdentity, DailyLog } from './types';
import { store } from './store';
import IdentitySetup from './components/IdentitySetup';
import CheckIn from './components/CheckIn';
import Feedback from './components/Feedback';
import History from './components/History';
import Landing from './components/Landing';
import Auth from './components/Auth';
import Onboarding from './components/Onboarding';
import Renewal from './components/Renewal';
import IdentityView from './components/IdentityView';
import { Circle, MessageSquare, Clock, User as UserIcon, RefreshCw, WifiOff } from 'lucide-react';
import { AnimatePresence, motion } from 'framer-motion';

const App: React.FC = () => {
  const [view, setView] = useState<AppView>('LANDING');
  const [identity, setIdentity] = useState<UserIdentity | null>(null);
  const [logs, setLogs] = useState<DailyLog[]>([]);
  const [userEmail, setUserEmail] = useState<string | null>(null);
  const [anonId, setAnonId] = useState<string | null>(null);
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [isSyncing, setIsSyncing] = useState(false);

  const isExpired = useMemo(() => {
    if (!identity) return false;
    const expiresAt = new Date(identity.expiresAt).getTime();
    const now = new Date().getTime();
    return now >= expiresAt;
  }, [identity]);

  const triggerSync = useCallback(async () => {
    if (!isOnline || isSyncing) return;

    const pending = store.getPendingSync();
    if (!pending.identity && pending.logs.length === 0) return;

    setIsSyncing(true);
    console.log('NOAH: Processing pending sync queue...', pending);

    try {
      // Simulation of a batch API sync request
      await new Promise(resolve => setTimeout(resolve, 2000));

      store.clearPending();
      console.log('NOAH: Sync complete. Node state updated.');
    } catch (error) {
      console.error('NOAH: Sync failed. Will retry on next connectivity cycle.', error);
    } finally {
      setIsSyncing(false);
    }
  }, [isOnline, isSyncing]);

  useEffect(() => {
    const id = store.getAnonId();
    setAnonId(id);

    const storedIdentity = store.getIdentity();
    const storedLogs = store.getLogs();
    const storedEmail = store.getEmail();
    const seenLanding = store.hasSeenLanding();
    const seenOnboarding = store.hasSeenOnboarding();

    setIdentity(storedIdentity);
    setLogs(storedLogs);
    setUserEmail(storedEmail);

    if (seenLanding) {
      if (!seenOnboarding) setView('ONBOARDING');
      else if (!storedIdentity) setView('SETUP');
      else if (new Date().getTime() >= new Date(storedIdentity.expiresAt).getTime()) setView('RENEWAL');
      else setView('CHECKIN');
    } else {
      setView('LANDING');
    }

    const handleOnline = () => {
      setIsOnline(true);
      setTimeout(triggerSync, 500); 
    };
    const handleOffline = () => setIsOnline(false);

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    const syncInterval = setInterval(() => {
      if (isOnline) triggerSync();
    }, 30000);

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
      clearInterval(syncInterval);
    };
  }, [isOnline, triggerSync]);

  const handleLandingProceed = () => setView('AUTH');
  const handleLandingEnter = () => {
    store.setSeenLanding();
    if (!store.hasSeenOnboarding()) setView('ONBOARDING');
    else if (!identity) setView('SETUP');
    else if (isExpired) setView('RENEWAL');
    else setView('CHECKIN');
  };

  const handleOnboardingComplete = () => {
    store.setSeenOnboarding();
    if (!identity) setView('SETUP');
    else setView('CHECKIN');
  };

  const handleAuthSuccess = (email: string) => {
    store.saveEmail(email);
    setUserEmail(email);
    store.setSeenLanding();
    if (!store.hasSeenOnboarding()) setView('ONBOARDING');
    else if (!identity) setView('SETUP');
    else if (isExpired) setView('RENEWAL');
    else setView('CHECKIN');
    triggerSync();
  };

  const handleIdentityLocked = (newIdentity: UserIdentity) => {
    setIdentity(newIdentity);
    store.saveIdentity(newIdentity); 
    setView('CHECKIN');
    triggerSync();
  };

  const handleLogSubmitted = (newLog: DailyLog) => {
    store.addLog(newLog); 
    setLogs(prev => [...prev.filter(l => l.id !== newLog.id), newLog]);
    setView('FEEDBACK');
    triggerSync();
  };

  const handleCycleReset = () => {
    store.clearAll();
    setIdentity(null);
    setLogs([]);
    setView('SETUP');
  };

  if (view === 'LANDING') return <Landing onProceed={handleLandingProceed} onEnter={handleLandingEnter} />;
  if (view === 'AUTH') return <Auth onSuccess={handleAuthSuccess} onSkip={handleLandingEnter} />;
  if (view === 'ONBOARDING') return <Onboarding onComplete={handleOnboardingComplete} />;
  if (view === 'SETUP' || !identity) return <IdentitySetup onLock={handleIdentityLocked} />;

  return (
    <div className="min-h-screen bg-bgMain flex flex-col items-center max-w-md mx-auto relative px-6 pb-24 overflow-hidden">
      <header className="w-full py-6 flex justify-between items-center z-20" role="banner">
        <div className="flex flex-col">
          <span className="text-[12px] font-mono tracking-[0.5em] text-textPrimary uppercase font-bold">N.O.A.H</span>
        </div>
        <div className="flex items-center space-x-3">
          {isSyncing && (
            <div className="flex items-center space-x-2">
              <span className="text-[8px] font-mono tracking-widest text-accent uppercase animate-pulse">Syncing</span>
              <RefreshCw size={10} className="text-accent animate-spin" aria-label="Synchronizing" />
            </div>
          )}
          {!isOnline && (
            <div className="flex items-center space-x-1.5 opacity-60" aria-label="Offline Mode">
              <span className="text-[8px] font-mono tracking-widest text-textSecondary uppercase">Offline</span>
              <WifiOff size={12} className="text-textSecondary" />
            </div>
          )}
        </div>
      </header>

      <main className="w-full flex-grow flex flex-col relative z-10" id="main-content" role="main">
        <AnimatePresence mode="wait">
          <motion.div
            key={view}
            initial={{ opacity: 0, scale: 0.98 }}
            animate={{ opacity: 1, scale: 1 }}
            exit={{ opacity: 0, scale: 1.02 }}
            transition={{ duration: 0.15, ease: "easeOut" }}
            className="w-full flex-grow flex flex-col"
          >
            {view === 'CHECKIN' && <CheckIn identity={identity} logs={logs} onComplete={handleLogSubmitted} />}
            {view === 'FEEDBACK' && <Feedback identity={identity} logs={logs} onCycleReset={handleCycleReset} />}
            {view === 'HISTORY' && <History logs={logs} identity={identity} loading={isSyncing} />}
            {view === 'RENEWAL' && <Renewal identity={identity} onRecommit={() => setView('CHECKIN')} onReset={handleCycleReset} />}
            {view === 'IDENTITY' && <IdentityView identity={identity} />}
          </motion.div>
        </AnimatePresence>
      </main>

      <nav className="fixed bottom-0 left-0 right-0 bg-bgSurface/95 backdrop-blur-md border-t border-white/5 h-20 flex items-center justify-around px-4 z-50 pb-[env(safe-area-inset-bottom)]" role="navigation" aria-label="Main Navigation">
        <NavButton active={view === 'CHECKIN'} icon={<Circle size={18} />} label="Check-in" onClick={() => setView('CHECKIN')} />
        <NavButton active={view === 'FEEDBACK'} icon={<MessageSquare size={18} />} label="Truth" onClick={() => setView('FEEDBACK')} />
        <NavButton active={view === 'HISTORY'} icon={<Clock size={18} />} label="History" onClick={() => setView('HISTORY')} />
        <NavButton active={view === 'IDENTITY'} icon={<UserIcon size={18} />} label="Id" onClick={() => setView('IDENTITY')} />
      </nav>
    </div>
  );
};

const NavButton = ({ active, icon, label, onClick }: { active: boolean, icon: React.ReactNode, label: string, onClick: () => void }) => (
  <button 
    onClick={onClick}
    aria-current={active ? 'page' : undefined}
    className={`flex flex-col items-center space-y-1 transition-all duration-300 active-feedback ${active ? 'text-textPrimary' : 'text-textSecondary/30'}`}
  >
    <div className={`${active ? 'text-accent scale-110' : ''} transition-all`} aria-hidden="true">{icon}</div>
    <span className="text-[9px] uppercase tracking-widest font-mono font-medium">{label}</span>
  </button>
);

export default App;

import React, { useState, useRef } from 'react';
import { UserIdentity, DailyLog } from '../types';
import { motion, AnimatePresence } from 'framer-motion';
import { FileUp, AlertTriangle, ShieldCheck } from 'lucide-react';
import { store } from '../store';

interface Props {
  onLock: (id: UserIdentity) => void;
}

const IdentitySetup: React.FC<Props> = ({ onLock }) => {
  const [role, setRole] = useState('');
  const [anchors, setAnchors] = useState(['', '', '']);
  const [isLocking, setIsLocking] = useState(false);
  const [showConfirm, setShowConfirm] = useState(false);
  const [importStatus, setImportStatus] = useState<'idle' | 'success' | 'error' | 'verifying'>('idle');
  const [pendingNode, setPendingNode] = useState<{ identity: UserIdentity, logs: DailyLog[] } | null>(null);
  const [nodeIdInput, setNodeIdInput] = useState('');

  const fileInputRef = useRef<HTMLInputElement>(null);

  const trimmedRole = role.trim();
  const validAnchors = anchors.map(a => a.trim()).filter(a => a.length >= 2);
  const isFormValid = trimmedRole.length >= 3 && validAnchors.length === 3;

  const handleLock = () => {
    if (!isFormValid) return;
    setIsLocking(true);
    const now = new Date().toISOString();
    const anonId = store.getAnonId();

    onLock({
      id: anonId,
      role: trimmedRole,
      anchors: validAnchors,
      checkInTime: "19:00", // Defaulting to standard evening window
      created_at: now,
      cycle_start: now,
      status: 'UNSTABLE',
      expiresAt: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString()
    });
  };

  const handleImportJson = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const json = JSON.parse(event.target?.result as string);
        if (json.identity && json.logs) {
          setPendingNode({ identity: json.identity, logs: json.logs });
          setImportStatus('verifying');
        }
      } catch (err) {
        setImportStatus('error');
        setTimeout(() => setImportStatus('idle'), 2000);
      }
    };
    reader.readAsText(file);
  };

  const verifyNodeId = () => {
    if (!pendingNode) return;
    if (nodeIdInput.trim() === pendingNode.identity.id) {
      store.saveIdentity(pendingNode.identity);
      pendingNode.logs.forEach(l => store.addLog(l));
      window.location.reload();
    }
  };

  return (
    <motion.div 
      initial={{ opacity: 0 }} 
      animate={{ opacity: 1 }}
      className="min-h-screen bg-bgMain flex flex-col items-center p-6 pt-20 text-center font-sans"
    >
      <AnimatePresence>
        {importStatus === 'verifying' && (
          <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 bg-bgMain/98 z-[200] flex items-center justify-center p-6 backdrop-blur-xl">
            <div className="noah-card max-w-xs w-full p-8 space-y-6">
              <ShieldCheck size={32} className="text-accent mx-auto" />
              <h3 className="noah-title">Authorize Node</h3>
              <input
                type="text"
                value={nodeIdInput}
                onChange={(e) => setNodeIdInput(e.target.value)}
                placeholder="Enter Node ID"
                className="w-full bg-muted/30 border border-border p-4 text-center text-xs font-mono focus:outline-none"
              />
              <button onClick={verifyNodeId} className="w-full bg-accent py-4 text-[10px] font-mono uppercase tracking-widest active-feedback">Restore</button>
              <button onClick={() => setImportStatus('idle')} className="w-full text-[9px] font-mono uppercase text-textSecondary/40">Cancel</button>
            </div>
          </motion.div>
        )}

        {showConfirm && (
          <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 bg-bgMain/95 z-[100] flex items-center justify-center p-6 backdrop-blur-sm">
            <div className="noah-card max-w-xs w-full p-8 space-y-8 text-center border-accent/20">
              <AlertTriangle size={32} className="text-accent mx-auto opacity-50" />
              <div className="space-y-4">
                <h3 className="noah-title text-textPrimary">30-Day Commitment</h3>
                <p className="text-sm text-textSecondary font-light leading-relaxed">This identity cannot be changed for 30 days. Observe strictly.</p>
              </div>
              <button onClick={handleLock} className="w-full bg-accent py-4 text-[10px] font-mono tracking-[0.3em] uppercase active-feedback">Lock Identity</button>
              <button onClick={() => setShowConfirm(false)} className="w-full py-4 text-[10px] font-mono tracking-[0.3em] uppercase text-textSecondary/40">Review</button>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      <div className="w-full max-w-sm space-y-16">
        <div className="space-y-6">
          <label className="text-[10px] font-mono tracking-[0.4em] uppercase text-textSecondary/60">Who do you want to become?</label>
          <input
            type="text"
            value={role}
            onChange={(e) => setRole(e.target.value)}
            placeholder="Future Identity"
            className="w-full bg-transparent border-b border-white/10 py-4 text-3xl text-center focus:outline-none focus:border-accent transition-colors font-light"
          />
        </div>

        <div className="space-y-6">
          <h2 className="noah-title">Behavioral Anchors</h2>
          <div className="space-y-4">
            {anchors.map((a, i) => (
              <input
                key={i}
                type="text"
                value={a}
                onChange={(e) => {
                  const n = [...anchors];
                  n[i] = e.target.value;
                  setAnchors(n);
                }}
                placeholder={`Anchor ${i + 1}`}
                className="w-full bg-muted/20 border border-border/40 rounded-sm p-4 text-sm text-center focus:outline-none focus:border-accent"
              />
            ))}
          </div>
        </div>

        <div className="space-y-8 pt-8">
          <div className="space-y-2">
            <p className="text-[10px] font-mono tracking-widest text-accent uppercase">30-day commitment</p>
            <p className="text-[9px] text-textSecondary/40 font-mono uppercase tracking-[0.2em]">Locked cycle required for valid signal.</p>
          </div>
          <button
            onClick={() => setShowConfirm(true)}
            disabled={!isFormValid || isLocking}
            className="w-full bg-accent py-5 text-[11px] font-mono tracking-[0.5em] uppercase disabled:opacity-10 active-feedback"
          >
            Lock Identity
          </button>

          <button 
            onClick={() => fileInputRef.current?.click()}
            className="text-[9px] font-mono tracking-widest uppercase text-textSecondary/30 hover:text-textSecondary transition-colors flex items-center justify-center space-x-2 w-full"
          >
            <FileUp size={12} />
            <span>Import existing Node</span>
          </button>
          <input ref={fileInputRef} type="file" accept=".json" onChange={handleImportJson} className="hidden" />
        </div>
      </div>
    </motion.div>
  );
};

export default IdentitySetup;

