              />
              <button onClick={verifyNodeId} className="w-full bg-accent py-4 text-[10px] font-mono uppercase tracking-widest active-feedback">Restore</button>
              <button onClick={() => setImportStatus('idle')} className="w-full text-[9px] font-mono uppercase text-textSecondary/40">Cancel</button>
