const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export async function transcribeAudio(
  base64Audio: string,
  mimeType: string
): Promise<string> {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          {
            inlineData: {
              data: base64Audio,
              mimeType: mimeType,
            },
          },
          { text: "Transcribe the following audio precisely. This is a daily activity log. Output raw text only. No punctuation meta-talk, no introductions, no closing remarks." }
        ]
      },
    });
    return response.text || "";
  } catch (error) {
    console.error('Transcription error:', error);
    throw new Error('Failed to interpret audio signal.');
  }
}

