import { GoogleGenAI, Type } from "@google/genai";
import { UserIdentity, DailyLog, FeedbackData } from "../types";
import { noahCoreEngine } from "../noah-core/engine";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export async function transcribeAudio(
  base64Audio: string,
  mimeType: string
): Promise<string> {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          {
            inlineData: {
              data: base64Audio,
              mimeType: mimeType,
            },
          },
          { text: "Transcribe the following audio exactly as spoken. Output the raw transcription only. Do not add punctuation marks if not spoken, do not provide summaries, and do not include any meta-talk or introductory/closing text." }
        ]
      },
    });
    return response.text?.trim() || "";
  } catch (error) {
    console.error('Transcription error:', error);
    throw new Error('Failed to interpret audio signal.');
  }
}

