): Promise<FeedbackData> {
  if (logs.length === 0) {
    return {
      status: 'UNSTABLE',
      message: 'Initial observation required.',
      observation: 'No signal.'
    };
  }

  const coreResult = noahCoreEngine.process(logs);
  const recentLogs = logs.slice(-7);

  const prompt = `
    AUDIT ALIGNMENT SIGNAL.

    TARGET IDENTITY: ${identity.role}
    INTENDED ANCHORS: ${identity.anchors.join(', ')}

    SYSTEM DIAGNOSTICS: 
    - Explanation: ${coreResult.explanation}
    - Authenticity: ${coreResult.meta.authenticity.toFixed(2)}

    RECENT LOG DATA:
    ${recentLogs.map(l => `- "${l.note}" | Time: ${l.timeSpent}m | State: ${l.state} | Anchors: ${l.anchorsCompleted?.filter(Boolean).length}/${l.anchorsCompleted?.length}`).join('\n')}

    CRITICAL INSTRUCTIONS:
    - Analyze for "Narrative Smoothing": where a user writes a detailed note to feel productive despite logging < 30 mins or 0 anchors.
    - If Authenticity < 0.7, the "message" MUST confront the user about self-deception and the "Effort Paradox".
    - The "observation" should be a concise summary of the core drift pattern.
    - Status MUST respect the deterministic Noah Core Diagnostics.
    - Output ONLY valid JSON.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: 'application/json',
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            status: { type: Type.STRING, enum: ['ALIGNED', 'UNSTABLE', 'DRIFTING'] },
            message: { type: Type.STRING, description: "A cold, direct interpretation of the alignment. Confront self-deception if authenticity is low." },
            observation: { type: Type.STRING, description: "A technical observation of the behavioral pattern observed." }
          },
          required: ['status', 'message', 'observation']
        }
      }
    });

    const result = JSON.parse(response.text || '{}');
    return {
      status: result.status || 'UNSTABLE',
