import { DailyLog, EnergyLevel } from '../types';
import { SignalMetrics, WindowAnalysis } from './types';

const energyValue: Record<EnergyLevel, number> = { 'LOW': 0.1, 'MEDIUM': 0.5, 'HIGH': 1.0 };
const NEGATIVE_THRESHOLD = 0.4;

function calculateMetrics(logs: DailyLog[]): SignalMetrics {
  if (logs.length === 0) return { avg: 0, negCount: 0, variance: 0, authenticity: 1 };

  const values = logs.map(l => {
    const time = Math.min(l.timeSpent / 180, 1.0);
    const energy = energyValue[l.energy];
    const anchors = l.anchorsCompleted || [];
    const anchorRatio = anchors.length > 0 ? anchors.filter(Boolean).length / anchors.length : 0;

    // Core signal formula: Weighted towards Anchors (40%) and Time (40%)
    return (time * 0.4) + (energy * 0.2) + (anchorRatio * 0.4);
  });

  // Advanced Authenticity Calculation
  const authenticityScores = logs.map(l => {
    let score = 1.0;
    const time = l.timeSpent;
    const anchors = l.anchorsCompleted || [];
    const completedCount = anchors.filter(Boolean).length;
    const noteLength = (l.note || "").trim().length;
    const energy = l.energy;
    const state = (l.state || "").toLowerCase();

    // Rule 1: Ghost Achievement (Anchors marked with 0 time)
    if (time === 0 && completedCount > 0) score -= 0.7;

    // Rule 2: Effort Paradox (Significant time, 0 anchors)
    // Heavier penalty for extreme drift (120m+)
    if (time > 90 && completedCount === 0) score -= 0.5;
    if (time >= 120 && completedCount === 0) score -= 0.9; // Extreme signal disconnect

    // Rule 3: Velocity Check (Claiming all anchors in too little time)
    if (time < 30 && completedCount >= 2) score -= 0.4;

    // Rule 4: Documentation Integrity (Very short note for significant time)
    if (time > 90 && noteLength < 15) score -= 0.3;

    // Rule 5: State-Time Disparity (High performance words with low time)
    const perfWords = ['focus', 'productive', 'crushed', 'flow', 'efficient'];
    if (perfWords.some(w => state.includes(w)) && time < 15) score -= 0.4;

    return Math.max(0, score);
  });

  const avg = values.reduce((a, b) => a + b, 0) / values.length;
  const negCount = values.filter(v => v < NEGATIVE_THRESHOLD).length;
  const variance = values.length < 2 ? 0 : values.reduce((acc, v) => acc + Math.pow(v - avg, 2), 0) / values.length;
  const authenticity = authenticityScores.reduce((a, b) => a + b, 0) / authenticityScores.length;

  return { avg, negCount, variance, authenticity };
}

export const signalAnalyzer = {
  analyze(logs: DailyLog[]): WindowAnalysis {
    const sorted = [...logs].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    const windowRecent = sorted.slice(0, 7);
    const windowPrevious = sorted.slice(7, 14);

    const recent = calculateMetrics(windowRecent);
    const previous = calculateMetrics(windowPrevious);

    const delta = recent.avg - previous.avg;
    const volatility = Math.abs(recent.avg - previous.avg) + (recent.variance * 2);

    let dominantCategory: 'Time' | 'Energy' | 'Alignment' | 'None' = 'None';
    let maxNeg = 0;

    if (windowRecent.length > 0) {
      const timeNeg = windowRecent.filter(l => l.timeSpent < 45).length;
      const energyNeg = windowRecent.filter(l => l.energy === 'LOW').length;
      const alignNeg = windowRecent.filter(l => (l.anchorsCompleted?.filter(Boolean).length || 0) === 0).length;

      maxNeg = Math.max(timeNeg, energyNeg, alignNeg);
      if (maxNeg > 0) {
        if (maxNeg === timeNeg) dominantCategory = 'Time';
        else if (maxNeg === energyNeg) dominantCategory = 'Energy';
        else dominantCategory = 'Alignment';
      }
    }

    return {
      recent,
      previous,
      delta,
      volatility,
      dominantCategory,
      repetitionCount: maxNeg
    };
  }
};

import React, { useState, useMemo, useRef } from 'react';
import { DailyLog, EnergyLevel, UserIdentity } from '../types';
import { ChevronDown, AlertCircle, Lock, ClipboardCheck, Mic, Square, Loader2, ShieldAlert, Zap } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { transcribeAudio } from '../services/geminiService';

interface Props {
  identity: UserIdentity;
  logs: DailyLog[];
  onComplete: (log: DailyLog) => void;
}

const CheckIn: React.FC<Props> = ({ identity, logs, onComplete }) => {
  const [note, setNote] = useState('');
  const [time, setTime] = useState(60);
  const [state, setState] = useState('');
  const [energy, setEnergy] = useState<EnergyLevel>('MEDIUM');
  const [anchorStatus, setAnchorStatus] = useState<boolean[]>(new Array(identity.anchors.length).fill(false));
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [showAnchors, setShowAnchors] = useState(false);

  // Audio recording states
  const [isRecording, setIsRecording] = useState(false);
  const [isTranscribing, setIsTranscribing] = useState(false);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioChunksRef = useRef<Blob[]>([]);

  const today = new Date();
  const MAX_CHARS = 120;

  const dayOfCycle = useMemo(() => {
    const start = new Date(identity.created_at);
    start.setHours(0,0,0,0);
    const d = new Date();
    d.setHours(0,0,0,0);
    return Math.floor((d.getTime() - start.getTime()) / (1000 * 60 * 60 * 24)) + 1;
  }, [identity]);

  const continuity = useMemo(() => {
    if (logs.length === 0) return 0;
    const sorted = [...logs].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    let streak = 0;
    let streakDate = new Date();
    streakDate.setHours(0,0,0,0);

    for (let i = 0; i < sorted.length; i++) {
      const logDate = new Date(sorted[i].date);
      logDate.setHours(0,0,0,0);
      const diff = Math.floor((streakDate.getTime() - logDate.getTime()) / (1000 * 60 * 60 * 24));

      if (diff === 0) {
        streak++;
        streakDate.setDate(streakDate.getDate() - 1);
      } else if (diff === 1) {
        streak++;
        streakDate = logDate;
        streakDate.setDate(streakDate.getDate() - 1);
      } else {
        break;
      }
    }
    return streak;
  }, [logs]);

  const gapDetected = useMemo(() => {
    if (logs.length === 0) return false;
    const sorted = [...logs].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    const lastLog = new Date(sorted[0].date);
    lastLog.setHours(0,0,0,0);
    const d = new Date();
    d.setHours(0,0,0,0);
    const diff = Math.floor((d.getTime() - lastLog.getTime()) / (1000 * 60 * 60 * 24));
    return diff >= 2;
  }, [logs]);

  const coherencyWarnings = useMemo(() => {
    const warnings: { message: string; critical: boolean; type: 'disconnect' | 'paradox' }[] = [];
    const anchorsChecked = anchorStatus.filter(Boolean).length;

    if (time === 0 && anchorsChecked > 0) {
      warnings.push({ 
        message: "REALITY DISCONNECT: Anchors marked as complete with zero time logged. Signal is fraudulent.", 
        critical: true,
        type: 'disconnect'
      });
    }
    if (time >= 120 && anchorsChecked === 0) {
      warnings.push({ 
        message: "INCOHERENT EFFORT: Significant time (2h+) logged with zero behavioral anchors. Narrative does not manifest.", 
        critical: false,
        type: 'paradox'
      });
    }
    return warnings;
  }, [time, anchorStatus]);

  const hasLoggedToday = useMemo(() => {
    return logs.some(l => {
      const d = new Date(l.date);
      return d.getDate() === today.getDate() && d.getMonth() === today.getMonth() && d.getFullYear() === today.getFullYear();
    });
  }, [logs]);

  const isFormValid = note.trim().length >= 2;

  const handleSubmit = () => {
    if (!isFormValid || isSubmitting) return;
    setIsSubmitting(true);

    const log: DailyLog = {
      id: Math.random().toString(36).substring(7),
      identity_id: identity.id,
      date: new Date().toISOString(),
      note: note.trim(),
      timeSpent: time,
      state: state.trim(),
      energy,
      anchorsCompleted: anchorStatus
    };

    setTimeout(() => onComplete(log), 400);
  };

  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const mediaRecorder = new MediaRecorder(stream);
      mediaRecorderRef.current = mediaRecorder;
      audioChunksRef.current = [];

      mediaRecorder.ondataavailable = (event) => {
        if (event.data.size > 0) {
          audioChunksRef.current.push(event.data);
        }
      };

      mediaRecorder.onstop = async () => {
        const audioBlob = new Blob(audioChunksRef.current, { type: 'audio/webm' });
        await processAudio(audioBlob);
        stream.getTracks().forEach(track => track.stop());
      };

      mediaRecorder.start();
      setIsRecording(true);
    } catch (err) {
      console.error("Microphone access denied", err);
    }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
    }
  };

  const processAudio = async (blob: Blob) => {
    setIsTranscribing(true);
    try {
      const reader = new FileReader();
      reader.readAsDataURL(blob);
      reader.onloadend = async () => {
        const base64Audio = (reader.result as string).split(',')[1];
        const transcription = await transcribeAudio(base64Audio, 'audio/webm');
        if (transcription) {
          const cleanTranscription = transcription.trim();
          setNote(prev => {
            const combined = prev ? prev + ' ' + cleanTranscription : cleanTranscription;
            return combined.slice(0, MAX_CHARS);
          });
        }
        setIsTranscribing(false);
      };
    } catch (err) {
      console.error("Transcription failed", err);
      setIsTranscribing(false);
    }
  };

  const handlePaste = (e: React.ClipboardEvent) => {
    e.preventDefault();
    const pastedText = e.clipboardData.getData('text');
    const currentLength = note.length;
    const allowedLength = MAX_CHARS - currentLength;
    if (allowedLength > 0) {
      const textToAppend = pastedText.slice(0, allowedLength);
      setNote(prev => prev + textToAppend);
    }
  };

  const handleNoteChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    if (e.target.value.length <= MAX_CHARS) {
      setNote(e.target.value);
    }
  };

  if (hasLoggedToday) {
    return (
      <div className="flex-grow flex flex-col items-center justify-center space-y-8 py-20 text-center font-sans">
        <div className="p-4 rounded-full bg-accent/10">
          <Lock size={32} className="text-textSecondary/40" />
        </div>
        <div className="space-y-2">
          <p className="text-sm font-light text-textSecondary uppercase tracking-widest">Entry recorded</p>
          <p className="text-[10px] font-mono text-textSecondary/40 uppercase tracking-widest">The window reopens tomorrow.</p>
        </div>
      </div>
    );
  }

  return (
    <div className="w-full pb-20 animate-fade-in font-sans">
      <AnimatePresence>
        {isSubmitting && (
          <motion.div 
            initial={{ opacity: 0 }} 
            animate={{ opacity: 1 }} 
            exit={{ opacity: 0 }} 
            className="fixed inset-0 bg-bgMain z-[100] flex items-center justify-center"
          >
            <span className="text-[11px] font-mono tracking-[0.5em] uppercase text-textPrimary">Logged.</span>
          </motion.div>
        )}
      </AnimatePresence>

      <header className="sticky top-0 z-20 bg-bgMain/95 backdrop-blur-md space-y-6 mb-12 pt-6 pb-4 border-b border-white/5 -mx-6 px-6">
        <div className="flex justify-between items-start">
          <div className="space-y-1">
            <h1 className="text-[11px] font-mono tracking-widest text-textSecondary uppercase">
              {today.toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' }).toUpperCase()}
            </h1>
            <p className="text-sm font-semibold tracking-widest text-textPrimary uppercase">Day {dayOfCycle} of 30</p>
          </div>
          <div className="text-right space-y-1">
             <p className="text-[10px] font-mono tracking-widest text-textSecondary/60 uppercase">Identity: {identity.role}</p>
             <p className="text-[9px] font-mono tracking-widest text-accent uppercase">Continuity: {continuity} days</p>
          </div>
        </div>

        <AnimatePresence mode="popLayout">
          {gapDetected && (
            <motion.div 
              initial={{ height: 0, opacity: 0 }}
              animate={{ height: 'auto', opacity: 1 }}
              exit={{ height: 0, opacity: 0 }}
              className="p-3 bg-red-950/20 border border-red-900/40 rounded-sm flex items-center space-x-3"
            >
              <AlertCircle size={14} className="text-red-500" />
              <span className="text-[10px] text-red-400 font-mono uppercase tracking-widest">Observation gap detected.</span>
            </motion.div>
          )}

          {coherencyWarnings.map((w, i) => (
            <motion.div 
              key={w.type}
              initial={{ x: -10, opacity: 0 }}
              animate={{ x: w.critical ? [0, -4, 4, -4, 4, 0] : 0, opacity: 1 }}
              transition={{ x: { duration: 0.4, ease: "easeInOut" } }}
              className={`p-4 border rounded-sm flex items-start space-x-3 transition-all ${w.critical ? 'bg-red-950/40 border-red-500 shadow-[0_0_20px_rgba(239,68,68,0.1)]' : 'bg-orange-950/20 border-orange-500/40'}`}
            >
              <div className="mt-0.5">
                {w.critical ? <ShieldAlert size={16} className="text-red-500" /> : <Zap size={16} className="text-orange-400" />}
              </div>
              <div className="space-y-1">
                <span className={`text-[10px] font-mono uppercase tracking-widest block font-bold ${w.critical ? 'text-red-400' : 'text-orange-400'}`}>
                  {w.critical ? "Critical Violation" : "Warning: Effort Paradox"}
                </span>
                <span className={`text-[9px] font-mono uppercase tracking-widest leading-relaxed block ${w.critical ? 'text-red-300' : 'text-orange-300/70'}`}>
                  {w.message}
                </span>
              </div>
            </motion.div>
          ))}
        </AnimatePresence>

        <div className="noah-card overflow-hidden">
          <button 
            onClick={() => setShowAnchors(!showAnchors)} 
            className="w-full flex items-center justify-between p-4 active-feedback"
            aria-expanded={showAnchors}
          >
            <div className="flex items-center space-x-2">
              <ClipboardCheck size={12} className="text-textSecondary/40" />
              <span className="noah-title">Anchors being tracked</span>
            </div>
