export const driftDetector = {
  detect(analysis: WindowAnalysis): number {
    let score = 0;

    // 1. Negative trend delta -> +2
    if (analysis.delta < -0.1) {
      score += 2;
    }

    // 2. Repeated negative signals (>=3 same category) -> +2
    if (analysis.repetitionCount >= 3) {
      score += 2;
    }

    // 3. High instability -> +1
    if (analysis.recent.variance > 0.15) {
      score += 1;
    }

    // 4. Low Authenticity (Incoherent Data) -> Massive penalty
    // If authenticity is low, it suggests a disconnect between reality and logging.
    if (analysis.recent.authenticity < 0.7) {
      score += 2;
    }

    // CRITICAL: Force critical state if authenticity collapses
    if (analysis.recent.authenticity < 0.4) {
      score += 4;
    }

    return score;
  }
};

import { WindowAnalysis, DriftState } from './types';

export const explanationBuilder = {
  build(analysis: WindowAnalysis, state: DriftState): string {
    if (analysis.dominantCategory === 'None' && analysis.recent.avg > 0.7) {
      return "Operational stability detected. Identity signals are congruent across all measured metrics. No drift observed.";
    }

    const segments = [];

    // Authenticity Check
    if (analysis.recent.authenticity < 0.4) {
      segments.push("Critical signal collapse. The discrepancy between logged time and behavioral output suggests a total reality disconnect.");
    } else if (analysis.recent.authenticity < 0.7) {
      segments.push("Identity inflation observed. Subjective narrative is compensating for an operational void.");
    } else if (analysis.recent.authenticity < 0.85) {
      segments.push("Minor signal incongruity. Behavioral anchors do not fully map to reported operational time.");
    }

    // Volatility Check
    if (analysis.volatility > 0.4) {
      segments.push("High trajectory volatility. Signal variance indicates emotional oscillation rather than disciplined commitment.");
    }

    // Category Specifics
    if (analysis.dominantCategory !== 'None') {
      const trend = analysis.delta < -0.1 ? "decaying" : "stagnant";
      segments.push(`${analysis.dominantCategory} metrics are ${trend}. Negative signal density: ${analysis.repetitionCount}/7 observations.`);
    }

    // Verdict for Critical/Drift states
    if (state === 'critical' || state === 'drift') {
      segments.push("The Target Identity is becoming a conceptual abstraction. Operational correction is required immediately.");
    }

    return segments.length > 0 
      ? segments.join(" ") 
      : "Signal density remains low. Behavioral patterns have not yet reached a clinical threshold for analysis.";
  }
};

