  const MAX_CHARS = 120;

  const dayOfCycle = useMemo(() => {
    const start = new Date(identity.created_at);
    start.setHours(0,0,0,0);
    const d = new Date();
    d.setHours(0,0,0,0);
    return Math.floor((d.getTime() - start.getTime()) / (1000 * 60 * 60 * 24)) + 1;
  }, [identity]);

  const continuity = useMemo(() => {
    if (logs.length === 0) return 0;
    const sorted = [...logs].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    let streak = 0;
    let streakDate = new Date();
    streakDate.setHours(0,0,0,0);

    for (let i = 0; i < sorted.length; i++) {
      const logDate = new Date(sorted[i].date);
      logDate.setHours(0,0,0,0);
      const diff = Math.floor((streakDate.getTime() - logDate.getTime()) / (1000 * 60 * 60 * 24));

      if (diff === 0) {
        streak++;
        streakDate.setDate(streakDate.getDate() - 1);
      } else if (diff === 1) {
        streak++;
        streakDate = logDate;
        streakDate.setDate(streakDate.getDate() - 1);
      } else {
        break;
      }
    }
    return streak;
