import React, { Component, ErrorInfo, ReactNode } from 'react';
import { AlertOctagon, RefreshCcw } from 'lucide-react';

interface Props {
  children: ReactNode;
  moduleName?: string;
}

interface State {
  hasError: boolean;
  error: Error | null;
}

class ErrorBoundary extends Component<Props, State> {
  public state: State = {
    hasError: false,
    error: null,
  };

  public static getDerivedStateFromError(error: Error): State {
    return { hasError: true, error };
  }

  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error(`N.O.A.H Module Failure [${this.props.moduleName || 'UNKNOWN'}]:`, error, errorInfo);
  }

  private handleReset = () => {
    this.setState({ hasError: false, error: null });
    window.location.reload();
  };

  public render() {
    if (this.state.hasError) {
      return (
        <div className="flex-grow flex flex-col items-center justify-center p-8 text-center space-y-8 animate-fade-in">
          <div className="p-4 rounded-full bg-red-950/20 border border-red-500/20">
            <AlertOctagon size={32} className="text-red-500/60" />
          </div>

          <div className="space-y-3">
            <h2 className="text-[11px] font-mono tracking-[0.4em] uppercase text-red-500">Module Failure</h2>
            <p className="text-xs font-light text-textSecondary max-w-[240px] leading-relaxed">
              The {this.props.moduleName || 'system'} component encountered a critical state exception. Signal integrity cannot be guaranteed.
            </p>
          </div>

          <div className="noah-card p-4 bg-red-950/10 border-red-900/20 w-full max-w-xs overflow-hidden">
            <p className="text-[9px] font-mono text-red-400/50 truncate">
              {this.state.error?.message || "Internal diagnostic error."}
            </p>
          </div>

          <button 
            onClick={handleReset}
            className="flex items-center space-x-3 text-[10px] font-mono tracking-[0.3em] uppercase text-textPrimary border border-white/10 px-8 py-4 hover:bg-white/5 transition-all active-feedback"
          >
            <RefreshCcw size={12} />
            <span>Attempt Re-Sync</span>
          </button>
        </div>
      );
    }

    return this.props.children;
  }
}

export default ErrorBoundary;

