import { WindowAnalysis, DriftState } from './types';

export const explanationBuilder = {
  build(analysis: WindowAnalysis, state: DriftState): string {
    if (analysis.dominantCategory === 'None' && analysis.recent.avg > 0.75) {
      return "Your actions match your goals. All metrics show high consistency between your intended identity and your actual daily behavior.";
    }

    const segments = [];

    // Authenticity Check (Reality Disconnect)
    if (analysis.recent.authenticity < 0.5) {
      segments.push("Major gap detected: You are checking off tasks without putting in the actual work time. This suggests your records may not be honest.");
    } else if (analysis.recent.authenticity < 0.7) {
      segments.push("Narrative disconnect: You are writing detailed notes, but your metrics (time and tasks) don't back them up.");
    } else if (analysis.recent.authenticity < 0.85) {
      segments.push("Slight misalignment: Your daily actions aren't perfectly matching the role you defined.");
    }

    // Volatility Check (Consistency)
    if (analysis.volatility > 0.4) {
      segments.push("Your effort is inconsistent. Large swings in daily performance make it hard to maintain your identity.");
    }

    // Category Specifics
    if (analysis.dominantCategory !== 'None') {
      const trend = analysis.delta < 0 ? "dropping" : "staying low";
      if (analysis.dominantCategory === 'Time') {
        segments.push(`You aren't spending enough time on your goal. In ${analysis.repetitionCount} of the last 7 days, your effort was below the required threshold.`);
      } else if (analysis.dominantCategory === 'Energy') {
        segments.push(`Low energy is stalling your progress. You've reported fatigue or low focus in ${analysis.repetitionCount} of your recent check-ins.`);
      } else if (analysis.dominantCategory === 'Alignment') {
        segments.push(`You are missing your behavioral anchors. Even when you log time, you aren't doing the specific actions you committed to.`);
      }
    }

    return segments.length > 0 
      ? segments.join(" ") 
      : "We need more data to give a clear analysis. Continue checking in daily to establish a baseline.";
  }
};

import { GoogleGenAI, Type } from "@google/genai";
import { UserIdentity, DailyLog, FeedbackData } from "../types";
import { noahCoreEngine } from "../noah-core/engine";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export async function transcribeAudio(base64Audio: string, mimeType: string): Promise<string> {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [
        {
          parts: [
            {
              inlineData: {
                data: base64Audio,
                mimeType: mimeType,
              },
            },
            { text: "Transcribe the following audio precisely. Output only the transcription text, nothing else." },
          ],
        },
      ],
    });
    return response.text || "";
  } catch (error) {
    console.error("Transcription error:", error);
    return "";
  }
}

export async function getDeepReflectiveAnalysis(
  identity: UserIdentity,
  logs: DailyLog[]
): Promise<string> {
  const recentLogs = logs.slice(-14);
  const coreResult = noahCoreEngine.process(logs);

  const prompt = `
    SYSTEM: DEEP TRAJECTORY AUDIT [N.O.A.H CORE INTERFACE].

    TARGET IDENTITY: ${identity.role}
    ANCHOR COMMITMENTS: ${identity.anchors.join(', ')}

    DIAGNOSTIC TELEMETRY:
    - State: ${coreResult.state.toUpperCase()}
    - Core Logic: ${coreResult.explanation}
    - Authenticity Score: ${coreResult.meta.authenticity.toFixed(2)}

    RAW OBSERVATION DATA (Last 14 Nodes):
    ${recentLogs.map(l => `- [${l.date}] Note: "${l.note}" | Time: ${l.timeSpent}m | State: "${l.state}" | Energy: ${l.energy} | Anchors: ${l.anchorsCompleted?.filter(Boolean).length}/${l.anchorsCompleted?.length}`).join('\n')}

    ANALYTICAL FRAMEWORK:
    1. Check if the user's notes sound productive but their time/anchors are low.
    2. Identify the "Effort Paradox": lots of time spent but zero tasks finished.
    3. Tell the user the harsh truth about why they aren't becoming their target identity.

    CONSTRAINTS: 
    - Use clear, simple, but perfect English.
    - Be direct and honest. No fluff.
    - Avoid over-complicated jargon. Speak like a clinical psychologist.
    - Focus on the GAP between what they say and what they do.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: prompt,
      config: {
        thinkingConfig: { thinkingBudget: 32768 }
      },
    });

    return response.text || "Analysis interrupted. Logic buffer empty.";
  } catch (error) {
    console.error('Deep analysis error:', error);
    return "Deep reflection failed. Deterministic metrics suggest a state of " + coreResult.state + ". System authenticity is compromised.";
  }
}

export async function generateAlignmentFeedback(
  identity: UserIdentity,
  logs: DailyLog[]
): Promise<FeedbackData> {
  if (logs.length === 0) {
    return {
      status: 'UNSTABLE',
      message: 'Initial observation required.',
      observation: 'No signal.'
    };
  }

  const coreResult = noahCoreEngine.process(logs);
  const recentLogs = logs.slice(-7);

  const prompt = `
    AUDIT ALIGNMENT SIGNAL.

    TARGET IDENTITY: ${identity.role}
    INTENDED ANCHORS: ${identity.anchors.join(', ')}

    SYSTEM DIAGNOSTICS: 
    - NoahCore Explanation: ${coreResult.explanation}

    RECENT LOG DATA:
    ${recentLogs.map(l => `- Note: "${l.note}" | Time: ${l.timeSpent}m | State: "${l.state}" | Anchors: ${l.anchorsCompleted?.filter(Boolean).length}/${l.anchorsCompleted?.length}`).join('\n')}

    CRITICAL INSTRUCTIONS:
    - Compare what the user wrote (Note) with their effort (Time) and results (Anchors).
    - If they write a lot but do very little, point it out clearly.
    - Be serious and direct.
    - Use plain English that anyone can understand, but maintain a clinical tone.
    - The "observation" should be a 1-sentence summary of their current pattern.
    - Output ONLY valid JSON.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: 'application/json',
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            status: { type: Type.STRING, enum: ['ALIGNED', 'UNSTABLE', 'DRIFTING'] },
            message: { type: Type.STRING, description: "A direct, honest summary of the user's alignment." },
            observation: { type: Type.STRING, description: "A technical summary of the pattern." }
          },
          required: ['status', 'message', 'observation']
        }
      }
    });

    const result = JSON.parse(response.text || '{}');
    return {
      status: result.status || 'UNSTABLE',
      message: result.message || 'We are still analyzing your behavior patterns.',
      observation: result.observation || coreResult.explanation
    };
  } catch (error) {
    console.error('Gemini feedback error:', error);
    return {
      status: 'UNSTABLE',
      message: 'Mirror systems offline. Rely on deterministic diagnostics.',
      observation: coreResult.explanation
    };
  }
}

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { AppView, UserIdentity, DailyLog } from './types';
import { store } from './store';
import IdentitySetup from './components/IdentitySetup';
import CheckIn from './components/CheckIn';
import Feedback from './components/Feedback';
import History from './components/History';
import Landing from './components/Landing';
import Auth from './components/Auth';
import Renewal from './components/Renewal';
import IdentityView from './components/IdentityView';
import NotFound from './components/NotFound';
import ErrorBoundary from './components/ErrorBoundary';
import { Circle, MessageSquare, Clock, User as UserIcon, RefreshCw, WifiOff, AlertTriangle, ArrowRight } from 'lucide-react';
import { AnimatePresence, motion } from 'framer-motion';

const App: React.FC = () => {
  const [view, setView] = useState<AppView>('LANDING');
  const [identity, setIdentity] = useState<UserIdentity | null>(null);
  const [logs, setLogs] = useState<DailyLog[]>([]);
  const [userEmail, setUserEmail] = useState<string | null>(null);
  const [anonId, setAnonId] = useState<string | null>(null);
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [isSyncing, setIsSyncing] = useState(false);
  const [isWarningDismissed, setIsWarningDismissed] = useState(false);
  const [isInitializing, setIsInitializing] = useState(false);

  const isExpired = useMemo(() => {
    if (!identity) return false;
    const expiresAt = new Date(identity.expiresAt).getTime();
    const now = new Date().getTime();
    return now >= expiresAt;
  }, [identity]);

  const daysLeft = useMemo(() => {
    if (!identity) return null;
    const expiry = new Date(identity.expiresAt).getTime();
    const diff = expiry - Date.now();
    return Math.ceil(diff / (1000 * 60 * 60 * 24));
  }, [identity]);

  const showRenewalWarning = useMemo(() => {
    return (
      !isWarningDismissed &&
      daysLeft !== null &&
      daysLeft <= 3 &&
      daysLeft > 0 &&
      ['CHECKIN', 'FEEDBACK', 'HISTORY', 'IDENTITY'].includes(view)
    );
  }, [daysLeft, view, isWarningDismissed]);

  const triggerSync = useCallback(async () => {
    if (!isOnline || isSyncing) return;

    const pending = store.getPendingSync();
    if (!pending.identity && pending.logs.length === 0) return;

    setIsSyncing(true);

    try {
      await new Promise(resolve => setTimeout(resolve, 2000));
      store.clearPending();
    } catch (error) {
      console.error('NOAH: Sync failed.', error);
    } finally {
      setIsSyncing(false);
    }
  }, [isOnline, isSyncing]);

  useEffect(() => {
    const id = store.getAnonId();
    setAnonId(id);

    const storedIdentity = store.getIdentity();
    const storedLogs = store.getLogs();
    const storedEmail = store.getEmail();
    const seenLanding = store.hasSeenLanding();

    setIdentity(storedIdentity);
    setLogs(storedLogs);
    setUserEmail(storedEmail);

    if (seenLanding) {
      if (!storedIdentity) setView('SETUP');
      else if (new Date().getTime() >= new Date(storedIdentity.expiresAt).getTime()) setView('RENEWAL');
      else setView('CHECKIN');
    } else {
      setView('LANDING');
    }

    const handleOnline = () => {
      setIsOnline(true);
      setTimeout(triggerSync, 500); 
    };
    const handleOffline = () => setIsOnline(false);

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    const syncInterval = setInterval(() => {
      if (isOnline) triggerSync();
    }, 30000);

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
      clearInterval(syncInterval);
    };
  }, [isOnline, triggerSync]);

  const handleLandingProceed = () => setView('AUTH');
  const handleLandingEnter = () => {
    store.setSeenLanding();
    if (!identity) setView('SETUP');
    else if (isExpired) setView('RENEWAL');
    else setView('CHECKIN');
  };

  const handleAuthSuccess = (email: string) => {
    store.saveEmail(email);
    setUserEmail(email);
    store.setSeenLanding();
    if (!identity) setView('SETUP');
    else if (isExpired) setView('RENEWAL');
    else setView('CHECKIN');
    triggerSync();
  };

  const handleIdentityLocked = (newIdentity: UserIdentity) => {
    setIsInitializing(true);
    // Explicit transition delay for impact
    setTimeout(() => {
      setIdentity(newIdentity);
      store.saveIdentity(newIdentity); 
      setIsInitializing(false);
      setView('CHECKIN');
      triggerSync();
    }, 2000);
  };

  const handleImport = (importedIdentity: UserIdentity, importedLogs: DailyLog[]) => {
    store.saveIdentity(importedIdentity);
    localStorage.setItem('noah_logs', JSON.stringify(importedLogs));
    setIdentity(importedIdentity);
    setLogs(importedLogs);

    const today = new Date();
    const hasLoggedToday = importedLogs.some(l => {
      const d = new Date(l.date);
      return d.getDate() === today.getDate() && 
             d.getMonth() === today.getMonth() && 
             d.getFullYear() === today.getFullYear();
    });

    setView(hasLoggedToday ? 'FEEDBACK' : 'CHECKIN');
    triggerSync();
  };

  const handleLogSubmitted = (newLog: DailyLog) => {
    store.addLog(newLog); 
    setLogs(prev => [...prev.filter(l => l.id !== newLog.id), newLog]);
    setView('FEEDBACK');
    triggerSync();
  };

  const handleCycleReset = () => {
    store.clearAll();
    setIdentity(null);
    setLogs([]);
    setView('SETUP');
    setIsWarningDismissed(false);
  };

  const handleReturnFromNotFound = () => {
    if (!identity) setView('SETUP');
    else setView('CHECKIN');
  };

  if (view === 'LANDING') return <Landing onProceed={handleLandingProceed} onEnter={handleLandingEnter} />;
  if (view === 'AUTH') return <Auth onSuccess={handleAuthSuccess} onSkip={handleLandingEnter} />;

  if (isInitializing) {
    return (
      <div className="min-h-screen bg-bgMain flex flex-col items-center justify-center p-12 text-center space-y-8">
        <motion.div 
          animate={{ opacity: [0.3, 1, 0.3], scale: [0.98, 1.02, 0.98] }}
          transition={{ repeat: Infinity, duration: 2 }}
          className="w-16 h-16 border border-accent/30 rounded-full flex items-center justify-center"
        >
          <div className="w-2 h-2 bg-accent rounded-full animate-pulse" />
        </motion.div>
        <div className="space-y-2">
          <p className="text-[10px] font-mono tracking-[0.5em] uppercase text-textPrimary">Locking Node Signal</p>
          <p className="text-[9px] font-mono tracking-widest text-textSecondary/40 uppercase">Establishing 30-Day Mirror</p>
        </div>
      </div>
    );
  }

  if (view === 'SETUP' || !identity) return (
    <ErrorBoundary moduleName="IDENTITY_SETUP">
      <IdentitySetup onLock={handleIdentityLocked} onImport={handleImport} />
    </ErrorBoundary>
  );

  return (
    <div className="min-h-screen bg-bgMain flex flex-col items-center max-w-md mx-auto relative px-6 pb-24 overflow-hidden">
      <header className="w-full py-6 flex justify-between items-center z-20" role="banner">
        <div className="flex flex-col">
          <span className="text-[12px] font-mono tracking-[0.5em] text-textPrimary uppercase font-bold">N.O.A.H</span>
        </div>
        <div className="flex items-center space-x-3">
          {isSyncing && (
            <motion.div 
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              className="flex items-center space-x-2"
            >
              <span className="text-[8px] font-mono tracking-widest text-accent uppercase animate-pulse">Syncing</span>
              <RefreshCw size={10} className="text-accent animate-spin opacity-60" aria-label="Synchronizing" />
            </motion.div>
          )}
          {!isOnline && (
            <div className="flex items-center space-x-1.5 opacity-60" aria-label="Offline Mode">
              <span className="text-[8px] font-mono tracking-widest text-textSecondary uppercase">Offline</span>
              <WifiOff size={12} className="text-textSecondary" />
            </div>
          )}
        </div>
      </header>

      <main className="w-full flex-grow flex flex-col relative z-10" id="main-content" role="main">
        <AnimatePresence>
          {showRenewalWarning && (
            <motion.div
              initial={{ height: 0, opacity: 0 }}
              animate={{ height: 'auto', opacity: 1 }}
              exit={{ height: 0, opacity: 0 }}
              className="overflow-hidden mb-4"
            >
              <div className="bg-accent/10 border border-accent/30 rounded p-4 flex items-center justify-between space-x-4">
                <div className="flex items-center space-x-3">
                  <AlertTriangle size={16} className="text-accent flex-shrink-0" />
                  <div className="flex flex-col">
                    <span className="text-[10px] font-mono uppercase tracking-widest text-textPrimary">Cycle Expiry Approaching</span>
                    <span className="text-[9px] font-mono uppercase tracking-wider text-textSecondary/60">{daysLeft} days remaining in current node.</span>
                  </div>
                </div>
                <button 
                  onClick={() => setView('RENEWAL')}
                  className="flex items-center space-x-1 text-[9px] font-mono uppercase tracking-widest text-accent hover:text-textPrimary transition-colors active-feedback"
                >
                  <span>Renew</span>
                  <ArrowRight size={10} />
                </button>
              </div>
            </motion.div>
          )}
        </AnimatePresence>

        <AnimatePresence mode="wait">
          <motion.div
            key={view}
            initial={{ opacity: 0, scale: 0.98 }}
            animate={{ opacity: 1, scale: 1 }}
            exit={{ opacity: 0, scale: 1.02 }}
            transition={{ duration: 0.15, ease: "easeOut" }}
            className="w-full flex-grow flex flex-col"
          >
            {view === 'CHECKIN' && (
              <ErrorBoundary moduleName="CHECK_IN">
                <CheckIn identity={identity} logs={logs} onComplete={handleLogSubmitted} />
              </ErrorBoundary>
            )}
            {view === 'FEEDBACK' && (
              <ErrorBoundary moduleName="TRUTH_MIRROR">
                <Feedback identity={identity} logs={logs} onCycleReset={handleCycleReset} />
              </ErrorBoundary>
            )}
            {view === 'HISTORY' && (
              <ErrorBoundary moduleName="HISTORY_TRAJECTORY">
                <History logs={logs} identity={identity} loading={isSyncing} />
              </ErrorBoundary>
            )}
            {view === 'RENEWAL' && (
              <ErrorBoundary moduleName="RENEWAL_CYCLE">
                <Renewal identity={identity} onRecommit={() => { setView('CHECKIN'); setIsWarningDismissed(true); }} onReset={handleCycleReset} />
              </ErrorBoundary>
            )}
            {view === 'IDENTITY' && (
              <ErrorBoundary moduleName="IDENTITY_OPERATIONAL">
                <IdentityView identity={identity} />
              </ErrorBoundary>
            )}
            {view === 'NOT_FOUND' && (
              <NotFound onReturn={handleReturnFromNotFound} />
            )}
            {!['CHECKIN', 'FEEDBACK', 'HISTORY', 'RENEWAL', 'IDENTITY', 'NOT_FOUND'].includes(view) && (
               <NotFound onReturn={handleReturnFromNotFound} />
            )}
          </motion.div>
        </AnimatePresence>
      </main>

      <nav className="fixed bottom-0 left-0 right-0 bg-bgSurface/95 backdrop-blur-md border-t border-white/5 h-20 flex items-center justify-around px-4 z-50 pb-[env(safe-area-inset-bottom)]" role="navigation" aria-label="Main Navigation">
        <NavButton active={view === 'CHECKIN'} icon={<Circle size={18} />} label="Check-in" onClick={() => setView('CHECKIN')} />
        <NavButton active={view === 'FEEDBACK'} icon={<MessageSquare size={18} />} label="Truth" onClick={() => setView('FEEDBACK')} />
        <NavButton active={view === 'HISTORY'} icon={<Clock size={18} />} label="History" onClick={() => setView('HISTORY')} />
        <NavButton active={view === 'IDENTITY'} icon={<UserIcon size={18} />} label="Id" onClick={() => setView('IDENTITY')} />
      </nav>
    </div>
  );
};

const NavButton = ({ active, icon, label, onClick }: { active: boolean, icon: React.ReactNode, label: string, onClick: () => void }) => (
  <button 
    onClick={onClick}
    aria-current={active ? 'page' : undefined}
    className={`flex flex-col items-center space-y-1 transition-all duration-300 active-feedback ${active ? 'text-textPrimary' : 'text-textSecondary/30'}`}
  >
    <div className={`${active ? 'text-accent scale-110' : ''} transition-all`} aria-hidden="true">{icon}</div>
    <span className="text-[9px] uppercase tracking-widest font-mono font-medium">{label}</span>
  </button>
);

export default App;

import React, { useState, useMemo, useRef } from 'react';
import { DailyLog, EnergyLevel, UserIdentity } from '../types';
import { ChevronDown, AlertCircle, Lock, ClipboardCheck, ShieldAlert, Mic, Square, Loader2 } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { transcribeAudio } from '../services/geminiService';

interface Props {
  identity: UserIdentity;
  logs: DailyLog[];
  onComplete: (log: DailyLog) => void;
}

const CheckIn: React.FC<Props> = ({ identity, logs, onComplete }) => {
  const [note, setNote] = useState('');
  const [time, setTime] = useState(60);
  const [state, setState] = useState('');
  const [energy, setEnergy] = useState<EnergyLevel>('MEDIUM');
  const [anchorStatus, setAnchorStatus] = useState<boolean[]>(new Array(identity.anchors.length).fill(false));
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [showAnchors, setShowAnchors] = useState(false);

  // Audio recording states
  const [isRecording, setIsRecording] = useState(false);
  const [isTranscribing, setIsTranscribing] = useState(false);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioChunksRef = useRef<Blob[]>([]);

  const today = new Date();
  const MAX_CHARS = 120;

  const dayOfCycle = useMemo(() => {
    const start = new Date(identity.created_at);
    start.setHours(0,0,0,0);
    const d = new Date();
    d.setHours(0,0,0,0);
    return Math.floor((d.getTime() - start.getTime()) / (1000 * 60 * 60 * 24)) + 1;
  }, [identity]);

  const lastCheckInTime = useMemo(() => {
    if (logs.length === 0) return 'NO SIGNAL';
    const latest = [...logs].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime())[0];
    const date = new Date(latest.date);
    return date.toLocaleString('en-US', { 
      month: 'short', 
      day: 'numeric', 
      hour: '2-digit', 
      minute: '2-digit', 
      hour12: false 
    }).toUpperCase();
  }, [logs]);

  const continuity = useMemo(() => {
    if (logs.length === 0) return 0;
    const sorted = [...logs].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    let streak = 0;
    let streakDate = new Date();
    streakDate.setHours(0,0,0,0);

    for (let i = 0; i < sorted.length; i++) {
      const logDate = new Date(sorted[i].date);
      logDate.setHours(0,0,0,0);
      const diff = Math.floor((streakDate.getTime() - logDate.getTime()) / (1000 * 60 * 60 * 24));

      if (diff === 0) {
        streak++;
        streakDate.setDate(streakDate.getDate() - 1);
      } else if (diff === 1) {
        streak++;
        streakDate = logDate;
        streakDate.setDate(streakDate.getDate() - 1);
      } else {
        break;
      }
    }
    return streak;
  }, [logs]);

  const gapDetected = useMemo(() => {
    if (logs.length === 0) return false;
    const sorted = [...logs].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    const lastLog = new Date(sorted[0].date);
    lastLog.setHours(0,0,0,0);
    const d = new Date();
    d.setHours(0,0,0,0);
    const diff = Math.floor((d.getTime() - lastLog.getTime()) / (1000 * 60 * 60 * 24));
    return diff >= 2;
  }, [logs]);

  const coherencyWarnings = useMemo(() => {
    const warnings: { message: string; critical: boolean; title: string; type: 'disconnect' | 'paradox' }[] = [];
    const anchorsChecked = anchorStatus.filter(Boolean).length;

    if (time === 0 && anchorsChecked > 0) {
      warnings.push({ 
        title: "REALITY CHECK",
        message: "You marked tasks as complete but logged 0 minutes. This creates an dishonest record.", 
        critical: true,
        type: 'disconnect'
      });
    }
    if (time > 90 && anchorsChecked === 0) {
      warnings.push({ 
        title: "BUSY WORK DETECTED",
        message: "You spent a lot of time but didn't finish any of your core tasks. Avoid self-distraction.", 
        critical: false,
        type: 'paradox'
      });
    }
    return warnings;
  }, [time, anchorStatus]);

  const hasLoggedToday = useMemo(() => {
    return logs.some(l => {
      const d = new Date(l.date);
      return d.getDate() === today.getDate() && d.getMonth() === today.getMonth() && d.getFullYear() === today.getFullYear();
    });
  }, [logs]);

  const isFormValid = note.trim().length >= 3 && !coherencyWarnings.some(w => w.critical);

  const handleSubmit = () => {
    if (!isFormValid || isSubmitting) return;
    setIsSubmitting(true);

    const log: DailyLog = {
      id: Math.random().toString(36).substring(7),
      identity_id: identity.id,
      date: new Date().toISOString(),
      note: note.trim(),
      timeSpent: time,
      state: state.trim(),
      energy,
      anchorsCompleted: anchorStatus
    };

    setTimeout(() => onComplete(log), 400);
  };

  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const mediaRecorder = new MediaRecorder(stream);
      mediaRecorderRef.current = mediaRecorder;
      audioChunksRef.current = [];

      mediaRecorder.ondataavailable = (event) => {
        if (event.data.size > 0) {
          audioChunksRef.current.push(event.data);
        }
      };

      mediaRecorder.onstop = async () => {
        const audioBlob = new Blob(audioChunksRef.current, { type: 'audio/webm' });
        await processAudio(audioBlob);
        stream.getTracks().forEach(track => track.stop());
      };

      mediaRecorder.start();
      setIsRecording(true);
    } catch (err) {
      console.error("Microphone access denied", err);
    }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
    }
  };

  const processAudio = async (blob: Blob) => {
    setIsTranscribing(true);
    try {
      const reader = new FileReader();
      reader.readAsDataURL(blob);
      reader.onloadend = async () => {
        const base64Audio = (reader.result as string).split(',')[1];
        const transcription = await transcribeAudio(base64Audio, 'audio/webm');
        if (transcription) {
          const cleanTranscription = transcription.trim();
          setNote(prev => {
            const combined = prev ? prev + ' ' + cleanTranscription : cleanTranscription;
            return combined.slice(0, MAX_CHARS);
          });
        }
        setIsTranscribing(false);
      };
    } catch (err) {
      console.error("Transcription failed", err);
      setIsTranscribing(false);
    }
  };

  const handleNoteChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    if (e.target.value.length <= MAX_CHARS) {
      setNote(e.target.value);
    }
  };

  if (hasLoggedToday) {
    return (
      <div className="flex-grow flex flex-col items-center justify-center space-y-8 py-20 text-center font-sans">
        <div className="p-4 rounded-full bg-accent/10">
          <Lock size={32} className="text-textSecondary/40" />
        </div>
        <div className="space-y-2">
          <p className="text-sm font-light text-textSecondary uppercase tracking-widest">Observation Logged</p>
          <p className="text-[10px] font-mono text-textSecondary/40 uppercase tracking-widest">The mirror will reset tomorrow.</p>
        </div>
      </div>
    );
  }

  return (
    <div className="w-full pb-20 animate-fade-in font-sans">
      <AnimatePresence>
        {isSubmitting && (
          <motion.div 
            initial={{ opacity: 0 }} 
            animate={{ opacity: 1 }} 
            exit={{ opacity: 0 }} 
            className="fixed inset-0 bg-bgMain z-[100] flex items-center justify-center"
          >
            <span className="text-[11px] font-mono tracking-[0.5em] uppercase text-textPrimary">Stored.</span>
          </motion.div>
        )}
      </AnimatePresence>

      <header className="sticky top-0 z-20 bg-bgMain/95 backdrop-blur-md space-y-6 mb-12 pt-6 pb-4 border-b border-white/5 -mx-6 px-6">
        <div className="flex justify-between items-start">
          <div className="space-y-1">
            <h1 className="text-[11px] font-mono tracking-widest text-textSecondary uppercase">
              {today.toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' }).toUpperCase()}
            </h1>
            <p className="text-sm font-semibold tracking-widest text-textPrimary uppercase">Day {dayOfCycle} of 30</p>
          </div>
          <div className="text-right space-y-1">
             <p className="text-[10px] font-mono tracking-widest text-textSecondary/60 uppercase">Node: {identity.role}</p>
             <p className="text-[9px] font-mono tracking-widest text-accent uppercase">Streak: {continuity} days</p>
          </div>
        </div>

        <AnimatePresence mode="popLayout">
          {gapDetected && (
            <motion.div 
              initial={{ height: 0, opacity: 0 }} 
              animate={{ height: 'auto', opacity: 1 }}
              exit={{ height: 0, opacity: 0 }}
              className="p-3 bg-red-950/20 border border-red-900/40 rounded-sm flex items-center space-x-3 overflow-hidden"
            >
              <AlertCircle size={14} className="text-red-500" />
              <span className="text-[10px] text-red-400 font-mono uppercase tracking-widest">Log gap detected.</span>
            </motion.div>
          )}

          {coherencyWarnings.map((w) => (
            <motion.div 
              key={w.type} 
              initial={{ opacity: 0, y: -10 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: 10 }}
              className={`p-4 border rounded-sm flex items-start space-x-3 transition-all ${w.critical ? 'bg-red-950/40 border-red-500 animate-shake' : 'bg-accent/10 border-accent/20'}`}
            >
              {w.critical ? <ShieldAlert size={16} className="text-red-500 mt-0.5" /> : <AlertCircle size={16} className="text-accent mt-0.5" />}
              <div className="flex flex-col space-y-1">
                <span className={`text-[10px] font-mono uppercase tracking-widest font-bold ${w.critical ? 'text-red-400' : 'text-accent'}`}>
                  {w.title}
                </span>
                <span className={`text-[9px] font-mono uppercase tracking-widest leading-relaxed ${w.critical ? 'text-red-300' : 'text-accent/70'}`}>
                  {w.message}
                </span>
              </div>
            </motion.div>
          ))}
        </AnimatePresence>

        <div className="noah-card overflow-hidden">
          <button 
            onClick={() => setShowAnchors(!showAnchors)} 
            className="w-full flex items-center justify-between p-4 active-feedback"
            aria-expanded={showAnchors}
          >
            <div className="flex items-center space-x-2">
              <ClipboardCheck size={12} className="text-textSecondary/40" />
              <span className="noah-title">Your Commitments</span>
            </div>
            <ChevronDown size={14} className={`text-textSecondary/40 transition-transform ${showAnchors ? 'rotate-180' : ''}`} />
          </button>
          <AnimatePresence>
            {showAnchors && (
              <motion.div 
                initial={{ height: 0, opacity: 0 }} 
                animate={{ height: 'auto', opacity: 1 }} 
                exit={{ height: 0, opacity: 0 }} 
                className="px-4 pb-4 space-y-3"
              >
                {identity.anchors.map((anchor, i) => (
                  <p key={i} className="text-xs text-textSecondary font-light leading-relaxed border-l border-white/5 pl-3">• {anchor}</p>
                ))}
              </motion.div>
            )}
          </AnimatePresence>
        </div>
      </header>

      <div className="space-y-12 px-1">
        <section className="space-y-4">
          <div className="flex justify-between items-center">
            <label className="text-[10px] font-mono tracking-widest uppercase text-textSecondary">What did you do today?</label>
            <div className="flex items-center space-x-2">
               {isTranscribing && (
                 <div className="flex items-center space-x-2 text-[8px] font-mono uppercase tracking-widest text-accent animate-pulse">
                    <Loader2 size={10} className="animate-spin" />
                    <span>Transcribing</span>
                 </div>
               )}
               <div className="flex items-center space-x-1">
                 {isRecording && (
                   <button 
                    onClick={stopRecording}
                    className="p-2 rounded-sm bg-red-950/20 border border-red-500/50 text-red-400 active-feedback"
                    aria-label="Stop recording"
                   >
                     <Square size={12} fill="currentColor" />
                   </button>
                 )}
                 <button 
                  onClick={isRecording ? stopRecording : startRecording}
                  disabled={isTranscribing}
                  className={`p-2 rounded-sm border transition-all active-feedback ${isRecording ? 'bg-accent/20 border-accent/50 text-accent' : 'bg-muted/30 border-border text-textSecondary/60'}`}
                  aria-label={isRecording ? "Stop" : "Speak Note"}
                 >
                   <Mic size={14} />
                 </button>
               </div>
            </div>
          </div>

          <div className="relative">
            <textarea 
              value={note} 
              onChange={handleNoteChange}
              className={`w-full bg-muted/30 border p-4 text-sm text-textPrimary focus:outline-none focus:border-accent transition-all min-h-[120px] resize-none ${isRecording ? 'border-red-500/30' : 'border-border'}`} 
              placeholder={isRecording ? "Listening..." : "Write a brief, honest note..."} 
            />
            {isRecording && (
              <motion.div 
                animate={{ opacity: [0.4, 0.8, 0.4] }}
                transition={{ repeat: Infinity, duration: 2 }}
                className="absolute top-4 right-4 pointer-events-none"
              >
                <div className="w-2 h-2 rounded-full bg-red-500" />
              </motion.div>
            )}
          </div>

          <div className="text-right flex justify-end items-center space-x-2">
            <div className="h-[1px] flex-grow bg-white/5 mr-2" />
            <span className={`text-[9px] font-mono uppercase tracking-[0.2em] transition-colors duration-300 ${note.length >= MAX_CHARS ? 'text-accent' : 'text-textSecondary/40'}`}>
              {note.length}/{MAX_CHARS}
            </span>
          </div>
        </section>

        <section className="space-y-8">
          <div className="flex justify-between items-end">
            <label className="text-[10px] font-mono tracking-widest uppercase text-textSecondary">Operational Time (min)</label>
            <span className="text-sm font-mono text-textPrimary">{time}m</span>
          </div>
          <input 
            type="range" 
            min="0" 
            max="180" 
            step="15" 
            value={time} 
            onChange={(e) => setTime(parseInt(e.target.value))} 
            className="w-full active-feedback" 
          />
        </section>

        <section className="space-y-4">
          <label className="text-[10px] font-mono tracking-widest uppercase text-textSecondary">Mental State</label>
          <input 
            type="text" 
            value={state} 
            onChange={(e) => setState(e.target.value)} 
            placeholder="e.g., Tired but focused" 
            className="w-full bg-muted/30 border border-border p-4 text-sm text-textPrimary focus:outline-none focus:border-accent transition-all" 
          />
        </section>

        <section className="space-y-4">
          <h2 className="text-[10px] font-mono tracking-widest uppercase text-textSecondary">Energy Level</h2>
          <div className="grid grid-cols-3 gap-3">
            {(['LOW', 'MEDIUM', 'HIGH'] as EnergyLevel[]).map((level) => (
              <button 
                key={level} 
                onClick={() => setEnergy(level)} 
                className={`py-4 text-[10px] font-mono tracking-widest border transition-all active-feedback ${energy === level ? 'bg-accent text-textPrimary border-accent' : 'bg-muted/30 text-textSecondary/40 border-border'}`}
              >
                {level}
              </button>
            ))}
          </div>
        </section>

        <section className="space-y-4">
          <h2 className="text-[10px] font-mono tracking-widest uppercase text-textSecondary">Task Fulfillment</h2>
          <div className="space-y-3">
            {identity.anchors.map((anchor, i) => (
              <button 
                key={i} 
                onClick={() => {
                  const n = [...anchorStatus];
                  n[i] = !n[i];
                  setAnchorStatus(n);
                }} 
                className={`w-full text-left p-4 flex items-center justify-between border transition-all ${anchorStatus[i] ? 'border-accent bg-accent/10 text-textPrimary' : 'border-border bg-muted/20 text-textSecondary/40'}`}
              >
                <span className="text-[11px] uppercase tracking-widest font-light">{anchor}</span>
                <div className={`w-3 h-3 border ${anchorStatus[i] ? 'bg-accent border-accent' : 'border-white/10'}`} />
              </button>
            ))}
          </div>
        </section>

        <button 
          onClick={handleSubmit} 
          disabled={!isFormValid || isSubmitting || isRecording || isTranscribing}
          className={`w-full py-5 text-[11px] font-mono tracking-[0.5em] uppercase transition-all duration-300 active-feedback ${coherencyWarnings.some(w => w.critical) ? 'bg-red-950 text-red-400 border border-red-500/50' : 'bg-accent text-textPrimary disabled:opacity-20'}`}
        >
          {isSubmitting ? 'Syncing...' : 'Log Observation'}
        </button>
      </div>
    </div>
  );
};

export default CheckIn;

import React, { useState, useRef } from 'react';
import { UserIdentity, DailyLog } from '../types';
import { motion, AnimatePresence } from 'framer-motion';
import { FileUp, AlertTriangle, ShieldCheck, Info } from 'lucide-react';
import { store } from '../store';

interface Props {
  onLock: (id: UserIdentity) => void;
  onImport: (identity: UserIdentity, logs: DailyLog[]) => void;
}

const IdentitySetup: React.FC<Props> = ({ onLock, onImport }) => {
  const [slideIndex, setSlideIndex] = useState(0);
  const [role, setRole] = useState('');
  const [anchors, setAnchors] = useState(['', '', '']);
  const [isLocking, setIsLocking] = useState(false);
  const [showConfirm, setShowConfirm] = useState(false);
  const [importStatus, setImportStatus] = useState<'idle' | 'success' | 'error' | 'verifying'>('idle');
  const [pendingNode, setPendingNode] = useState<{ identity: UserIdentity, logs: DailyLog[] } | null>(null);
  const [nodeIdInput, setNodeIdInput] = useState('');

  const fileInputRef = useRef<HTMLInputElement>(null);

  const slides = [
    "This is not a productivity app.",
    "This is a mirror.",
    "You will define who you want to become.",
    "Then you will observe yourself.",
    "Nothing more. Nothing less."
  ];

  const handleNextSlide = () => {
    if (slideIndex < slides.length - 1) setSlideIndex(slideIndex + 1);
    else setSlideIndex(99); 
  };

  const handleSkipSlides = () => setSlideIndex(99);

  const trimmedRole = role.trim();
  const validAnchors = anchors.map(a => a.trim()).filter(a => a.length >= 3);
  const uniqueAnchors = new Set(anchors.map(a => a.trim().toLowerCase())).size === 3;
  const isFormValid = trimmedRole.length >= 3 && validAnchors.length === 3 && uniqueAnchors;

  const handleLock = () => {
    if (!isFormValid) return;
    setIsLocking(true);
    const now = new Date().toISOString();
    const anonId = store.getAnonId();

    // Impactful delay for the "Locking" process
    setTimeout(() => {
      onLock({
        id: anonId,
        role: trimmedRole,
        anchors: anchors.map(a => a.trim()),
        checkInTime: "19:00",
        created_at: now,
        cycle_start: now,
        status: 'UNSTABLE',
        expiresAt: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString()
      });
    }, 1500);
  };

  const handleImportJson = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const json = JSON.parse(event.target?.result as string);
        if (json.identity && json.logs) {
          setPendingNode({ identity: json.identity, logs: json.logs });
          setImportStatus('verifying');
        }
      } catch (err) {
        setImportStatus('error');
        setTimeout(() => setImportStatus('idle'), 2000);
      }
    };
    reader.readAsText(file);
  };

  const verifyNodeId = () => {
    if (!pendingNode) return;
    if (nodeIdInput.trim() === pendingNode.identity.id) {
      onImport(pendingNode.identity, pendingNode.logs);
    } else {
      setImportStatus('error');
      setTimeout(() => setImportStatus('verifying'), 1500);
    }
  };

  if (slideIndex < slides.length) {
    return (
      <div className="min-h-screen bg-bgMain flex flex-col items-center justify-center p-12 text-center relative">
        <button 
          onClick={handleSkipSlides}
          className="absolute top-12 right-12 text-[9px] font-mono tracking-[0.3em] uppercase text-textSecondary/40 hover:text-textPrimary transition-colors"
        >
          Skip
        </button>
        <div 
          onClick={handleNextSlide}
          className="flex-grow flex flex-col items-center justify-center cursor-pointer select-none w-full"
        >
          <AnimatePresence mode="wait">
            <motion.p 
              key={slideIndex}
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -10 }}
              className="text-xl md:text-2xl font-light tracking-wide text-textPrimary max-w-md leading-relaxed"
            >
              {slides[slideIndex]}
            </motion.p>
          </AnimatePresence>
        </div>
        <div className="pb-12 flex space-x-2">
          {slides.map((_, i) => (
            <div key={i} className={`h-[1px] w-4 transition-all duration-700 ${i === slideIndex ? 'bg-textPrimary' : 'bg-white/10'}`} />
          ))}
        </div>
        <p className="absolute bottom-6 text-[8px] font-mono tracking-[0.4em] uppercase text-textSecondary/20">Tap to continue</p>
      </div>
    );
  }

  return (
    <motion.div 
      initial={{ opacity: 0 }} 
      animate={{ opacity: 1 }}
      className="min-h-screen bg-bgMain flex flex-col items-center p-6 pt-20 text-center"
    >
      <AnimatePresence>
