        </AnimatePresence>

        <AnimatePresence mode="wait">
          <motion.div
            key={view}
            initial={{ opacity: 0, scale: 0.98 }}
            animate={{ opacity: 1, scale: 1 }}
            exit={{ opacity: 0, scale: 1.02 }}
            transition={{ duration: 0.15, ease: "easeOut" }}
            className="w-full flex-grow flex flex-col"
          >
            {view === 'CHECKIN' && (
              <ErrorBoundary moduleName="CHECK_IN">
                <CheckIn identity={identity} logs={logs} onComplete={handleLogSubmitted} />
              </ErrorBoundary>
            )}
            {view === 'FEEDBACK' && (
              <ErrorBoundary moduleName="TRUTH_MIRROR">
                <Feedback identity={identity} logs={logs} onCycleReset={handleCycleReset} />
              </ErrorBoundary>
            )}
            {view === 'HISTORY' && (
              <ErrorBoundary moduleName="HISTORY_TRAJECTORY">
                <History logs={logs} identity={identity} loading={isSyncing} />
